    let n2 = platform::read_u32(0x807D_2C18);
    let n3 = platform::read_u32(0x807D_2C1C);
    let n4 = platform::read_u32(0x807D_2C20);
    let n5 = platform::read_u32(0x807D_2C24);
    let n6 = platform::read_u32(0x807D_2C28);
    let n7 = platform::read_u32(0x807D_2C2C);
    let n8 = platform::read_u32(0x807D_2C30);
    let n9 = platform::read_u32(0x807D_2C34);

    abi_call2!(0x8015_F7C0, 0x8082_3240, 0x807D_2C88);
    platform::write_u32(0x8082_3240, 0x807D_2CD4);
    platform::write_u32(0x8082_324C, n7);
    platform::write_u32(0x8082_3250, n8);
    platform::write_u32(0x8082_3254, n9);
    platform::write_u32(0x8082_3258, n4);
    platform::write_u32(0x8082_325C, n5);
    platform::write_u32(0x8082_3260, n6);
    platform::write_u32(0x8082_3264, n1);
    platform::write_u32(0x8082_3268, n2);
    platform::write_u32(0x8082_326C, n3);
    fn_80600160(0x8082_3240, 0x8060_9E70, 0x8082_3230);

    // State "E" at 0x80823280.
    let e1 = platform::read_u32(0x807D_2C38);
    let e2 = platform::read_u32(0x807D_2C3C);
    let e3 = platform::read_u32(0x807D_2C40);
    let e4 = platform::read_u32(0x807D_2C44);
    let e5 = platform::read_u32(0x807D_2C48);
    let e6 = platform::read_u32(0x807D_2C4C);
    let e7 = platform::read_u32(0x807D_2C50);
    let e8 = platform::read_u32(0x807D_2C54);
    let e9 = platform::read_u32(0x807D_2C58);

    abi_call2!(0x8015_F7C0, 0x8082_3280, 0x807D_2CB0);
    platform::write_u32(0x8082_3280, 0x807D_2CD4);
    platform::write_u32(0x8082_328C, e7);
