    let current = platform::read_u32(actor + 0x248) as i32;
    let requested = platform::read_u32(actor + 0x24C) as i32;

    if current == requested {
        if current != 0 {
            return;
        }
        let slot = platform::read_u32(actor + 0x23C) as usize;
        let player = platform::read_u32(player_table + slot * 4 + 4) as usize;
        let player_vtable = platform::read_u32(player + 0x5C) as usize;
        let get_object = platform::read_u32(player_vtable + 0x28) as usize;
        let object = call0_ret(get_object) as usize;
        let object_vtable = platform::read_u32(object) as usize;
        let has_tag = platform::read_u32(object_vtable + 0x10) as usize;
        if abi_call2!(has_tag, object, 0x8037_1870) != 0 {
            return;
        }
        if platform::read_u8(actor + 0x23A) == 0 {
            return;
        }
        abi_call3!(0x800C_93D0, actor + 0x70, 0, 0);
        platform::write_u8(actor + 0x23A, 0);
        platform::write_u32(actor + 0x23C, 0);
        return;
    }

    if requested == 3 {
        return;
    }

    // unknown: 0x800CDC60 returns the current animation handle/frame base.
    let animation = call0_ret(0x800C_DC60);
    platform::write_u32(actor + 0x248, requested as u32);
