/// Copies a nine-word palette block and the source actor's variant byte.
///
/// # Original
/// `FUN_806b59a0`, `0x806b59a0`, 212 bytes,
/// `work/ghidra/rel-d_basesNP/export/806b59a0_FUN_806b59a0.c`.
/// `// synthetic base: 0x80600000` (analysis address, not a runtime address).
///
/// # Arguments
/// * `actor` - live object; palette at `+0x414..+0x432`.
/// * `source` - optional source object whose virtual `+0x6C` returns a pointer
///   to a byte; `0` keeps the default `0xFF` variant.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x432`, `+0x414..+0x42C`, `+0x430` and `+0x431`.
///
/// # Safety
/// `source`, when non-zero, must be live with the same vtable shape.
///
/// # Confidence
/// high - every constant word is explicit; the palette meaning is `// unknown:`.
pub unsafe fn fn_806b59a0(actor: usize, source: usize) {
    let mut variant = 0xFFu8;
    if source != 0 {
        let vtable = platform::read_u32(source + 0x60) as usize;
        let function = platform::read_u32(vtable + 0x6C) as usize;
        let byte_ptr = abi_call1!(function, source) as usize;
        variant = platform::read_u8(byte_ptr);
    }

    platform::write_u8(actor + 0x432, 1);
    platform::write_u32(actor + 0x414, platform::read_u32(0x807C_AAE0));
    platform::write_u32(actor + 0x418, platform::read_u32(0x807C_AAE4));
    platform::write_u32(actor + 0x41C, platform::read_u32(0x807C_AAE8));
    platform::write_u32(actor + 0x420, platform::read_u32(0x807C_AAEC));
    platform::write_u32(actor + 0x424, platform::read_u32(0x807C_AAF0));
    platform::write_u32(actor + 0x428, platform::read_u32(0x807C_AAF4));
    platform::write_u32(actor + 0x42C, platform::read_u32(0x807C_AAF8));
    platform::write_u8(
        actor + 0x430,
        (platform::read_u32(0x807C_AAFC) >> 24) as u8,
    );
    platform::write_u8(actor + 0x431, variant);
}

/// Sets the actor's starting angles from the local player's variant table.
///
/// The byte at `+0x348` indexes two `main.dol` tables at `0x8042C1A0` (signed
/// bytes) and `0x8042C1A4` (signed halfwords). With no player the angles are
/// rebuilt from those tables; with a player the source angle at `+0x102` is
/// kept and shifted by the table delta.
///
/// # Original
/// `FUN_806b5a80`, `0x806b5a80`, 308 bytes,
/// `work/ghidra/rel-d_basesNP/export/806b5a80_FUN_806b5a80.c`.
/// `// synthetic base: 0x80600000` (analysis address, not a runtime address).
///
/// # Arguments
/// * `actor` - live object; variant byte `+0x348`, angles `+0x100..+0x104`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Optionally writes `+0x348`; always writes `+0x100` (zero), `+0x102` and
/// `+0x104` (zero).
///
/// # Safety
/// `actor` must be live. The `main.dol` tables must be readable.
///
/// # Confidence
/// high - the table indexing and both arithmetic paths are explicit.
/// `// unknown:` the physical meaning of the table entries.
pub unsafe fn fn_806b5a80(actor: usize) {
    let player = abi_call1!(0x8016_2590, actor) as usize;
    let scale = platform::read_f32(0x807C_AA9C);

    // observed: `(double)CONCAT44(0x43300000, x ^ 0x80000000)` minus the
    // double at `0x807CAB00` (0x43300000_80000000 = 2^52 + 2^31) is the
    // compiler's signed-integer-to-double conversion. The expressions below are
    // therefore plain signed table values.
    if player == 0 {
        let index = platform::read_u8(actor + 0x348) as usize;
        let angle = platform::read_u16(0x8042_C1A4 + index * 2) as i16;
        let table_char = platform::read_u8(0x8042_C1A0 + index) as i8;

        platform::write_u16(actor + 0x100, 0);
        let y = (angle as f32) + (table_char as f32) * scale;
        platform::write_u16(actor + 0x102, (y as i32 as i16) as u16);
    } else {
        let index = platform::read_u8(player + 0x348) as usize;
        let table_char = platform::read_u8(0x8042_C1A0 + index) as i8;
        let previous = platform::read_u16(player + 0x102) as i16;

        platform::write_u8(actor + 0x348, index as u8);
        platform::write_u16(actor + 0x100, platform::read_u16(player + 0x100));

        let y = (previous as f32) + (table_char as f32) * scale;
        platform::write_u16(actor + 0x102, (y as i32 as i16) as u16);
    }

    platform::write_u16(actor + 0x104, 0);
}

/// Initialises the unnamed actor's palette, scale, variant and state.
///
/// # Original
/// `FUN_806b5ce0`, `0x806b5ce0`, 264 bytes,
/// `work/ghidra/rel-d_basesNP/export/806b5ce0_FUN_806b5ce0.c`.
/// `// synthetic base: 0x80600000` (analysis address, not a runtime address).
///
/// # Arguments
/// * `actor` - live object; vtable at `+0x60`, variant byte `+0x348`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0xE8`, `+0xEC`, `+0xF8`, `+0x114`, `+0x360`, `+0x6C8`, `+0x6D4`
/// and `+0x6D8`; calls [`fn_806b5a80`], `0x8007F900` and the sound helper
/// `0x80197F00` with sound id `0x536`.
///
/// # Safety
/// `actor` must be live; the `+0x60` vtable must provide slots `+0x2A4` and
/// `+0x28C`.
///
/// # Confidence
/// high - every store, table read, virtual call and sound id is explicit.
pub unsafe fn fn_806b5ce0(actor: usize) {
    platform::write_u32(actor + 0xEC, platform::read_u32(0x807C_AA78));
    platform::write_u32(actor + 0xF8, platform::read_u32(0x807C_AB08));
    platform::write_f32(actor + 0x114, -platform::read_f32(0x807C_AA88));

    let index = platform::read_u8(actor + 0x348) as usize;
    let table_char = platform::read_u8(0x8042_C1A0 + index) as i8;
    // observed: signed-byte conversion through the 2^52+2^31 constant at
    // 0x807CAB00 (see [`fn_806b5a80`]).
    platform::write_f32(
        actor + 0xE8,
        (table_char as f32) * platform::read_f32(0x807C_AA74),
    );

    platform::write_u16(actor + 0x6D4, actor_method0(actor, 0x2A4) as u16);
    platform::write_u32(actor + 0x360, 1);
    fn_806b5a80(actor);
    platform::write_u32(actor + 0x6C8, platform::read_u32(0x807C_AA64));
    platform::write_f32(actor + 0x6D8, actor_method0_f32(actor, 0x28C));

    abi_call1!(0x8007_F900, actor + 0x5E0);

    let mut sample = [0u32; 2];
    abi_call2!(0x8006_A4B0, sample.as_mut_ptr() as u32, actor + 0xAC);
    abi_call4!(
        0x8019_7F00,
        platform::read_u32(0x8042_9D5C),
        0x536,
        sample.as_mut_ptr() as u32,
        0
    );
}

