/// Runs the `jumpA` launch state.
///
/// # Original
/// `FUN_806BDB70`, `0x806bdb70`, 404 bytes,
/// `work/ghidra/rel-d_basesNP/export/806bdb70_FUN_806bdb70.c`.
/// `// synthetic base: 0x80600000` (analysis address, not a runtime address).
///
/// # Arguments
/// * `actor` - live jump actor; animation `+0x604`/`+0x644`, angle `+0x102`,
///   speeds `+0xE8`/`+0xEC`, state `+0x360`, interface `+0x544`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Applies the stored surface angle, binds `0x807F69D0` (`jumpA`) in state 1,
/// sets the launch speeds `2.0`/`3.0`, selects interface states `0x59E`/`0x4E5`,
/// and raises the `+0xC40` landing latch in state 2.
///
/// # Safety
/// `actor` must be live and the animation interface initialised.
///
/// # Confidence
/// high - every gate, speed constant and state transition is explicit.
pub unsafe fn fn_806bdb70(actor: usize) {
    vmethod0(actor + 0x604, 0x1C);
    abi_call1!(0x8006_CDE0, actor);
    abi_call1!(0x8009_55F0, actor);
    if abi_call1!(0x8007_2BC0, actor + 0x1EC) != 0 {
        platform::write_f32(actor + 0xEC, platform::read_f32(0x807C_AD74));
    }

    let variant = platform::read_u8(actor + 0x348) as usize;
    let target = platform::read_u16(0x8042_C1A4 + variant * 2) as i16 as i32;
    abi_call3!(0x8015_F4F0, actor + 0x102, target as u32, 0xA00);

    let state = platform::read_u32(actor + 0x360);
    if state == 1 {
        if abi_call1!(0x8016_9020, actor + 0x644) != 0 {
            let mut clip = [abi_call2!(0x8023_A0B0, actor + 0x600, 0x807F_69D0)];
            abi_call4!(
                0x8016_51F0,
                actor + 0x644,
                actor + 0x604,
                clip.as_mut_ptr() as u32,
                1
            );
            call_f32_u32x2(
                0x8016_9F80,
                platform::read_f32(0x807C_AD84),
                (actor + 0x604) as u32,
                (actor + 0x644) as u32,
            );
            call_f32_u32(
                0x8016_80E0,
                platform::read_f32(0x807C_AD80),
                (actor + 0x644) as u32,
            );
            platform::write_u32(actor + 0xE8, platform::read_u32(0x807C_AD58));
            platform::write_u32(actor + 0xEC, platform::read_u32(0x807C_AD5C));
            abi_call1!(0x8009_C810, actor);
            vmethod1(actor + 0x544, 0x24, 0x59E);
            vmethod1(actor + 0x544, 0x24, 0x4E5);
            platform::write_u32(actor + 0x360, platform::read_u32(actor + 0x360) + 1);
        }
    } else if state == 2
        && platform::read_f32(actor + 0xEC) < platform::read_f32(0x807C_AD74)
        && platform::read_f32(actor + 0xB0)
            < platform::read_f32(actor + 0x780) - platform::read_f32(0x807C_ADD0)
    {
        platform::write_u32(actor + 0xC40, 1);
    }
}

/// Returns the jump actor's current angle scaled by the `main.dol` facing table.
///
/// # Original
/// `FUN_806BE160`, `0x806be160`, 84 bytes,
/// `work/ghidra/rel-d_basesNP/export/806be160_FUN_806be160.c`.
/// `// synthetic base: 0x80600000` (analysis address, not a runtime address).
///
/// # Arguments
/// * `actor` - live jump actor; vtable `+0x60`, variant `+0x348`.
///
/// # Returns
/// The signed table byte at `0x8042C1A0 + variant` multiplied by the virtual
/// `+0x404` result, truncated to 16 bits and sign-extended.
///
/// # Side effects
/// Calls the `+0x404` virtual; no memory is written.
///
/// # Safety
/// `actor` must be live and its vtable valid.
///
/// # Confidence
/// high - the table, multiplier and truncation are explicit. The C prints no
/// argument for the virtual; the Rust keeps that shape.
pub unsafe fn fn_806be160(actor: usize) -> i32 {
    let vtable = platform::read_u32(actor + 0x60) as usize;
    let function = platform::read_u32(vtable + 0x404) as usize;
    let angle = call0_ret(function) as u16 as i16;
    let variant = platform::read_u8(actor + 0x348) as usize;
    let facing = platform::read_u8(0x8042_C1A0 + variant) as i8 as i32;
    (facing * angle as i32) as i16 as i32
}

