    call_f32_u32(0x8007_FD10, platform::read_f32(actor + 0x82C), (actor + 0x5E0) as u32);
    abi_call1!(0x8007_FDA0, actor + 0x5E0);

    let timer = platform::read_u16(actor + 0x6F4) as i16;
    if timer > 0 {
        platform::write_u16(actor + 0x6F4, (timer - 1) as u16);
    }

