/// Advances one axis through the clamped wire-fence sweep.
///
/// # Original
/// `FUN_80755F70`, `0x80755F70`, 216 bytes,
/// `work/ghidra/rel-d_basesNP/export/80755f70_FUN_80755f70.c`.
/// `// synthetic base: 0x80600000` (analysis address, not a runtime address).
///
/// # Arguments
/// * `input` - current axis coordinate.
/// * `actor` - the `0x568`-byte actor; direction `+0x348`, speed `+0x544`,
///   countdown `+0x548`, selector `+0x54C`, index `+0x554`, limits
///   `+0x538`/`+0x53C`.
///
/// # Returns
/// The next coordinate, or the hit limit when the sweep reverses.
///
/// # Side effects
/// Advances and clamps `+0x544`; on reaching a limit it flips `+0x348`, stores
/// the limit in `+0x54C`, reloads the step timer (`+0x548 = 0x1E`) and resets
/// the sequence index `+0x554` to `1`.
///
/// # Safety
/// `actor` must be live and `+0x348` in `0..=1`.
///
/// # Confidence
/// high - the clamp, the two limit branches and the four resets are explicit.
pub unsafe fn fn_80755f70(input: f64, actor: usize) -> f64 {
    let limit = platform::read_f32(0x807C_E95C);
    let mut phase = platform::read_f32(actor + 0x544) + platform::read_f32(0x807C_E958);
    platform::write_f32(actor + 0x544, phase);
    if limit <= phase {
        phase = limit;
        platform::write_f32(actor + 0x544, phase);
    }

    let direction = platform::read_u8(actor + 0x348) as u32;
    let mut value = platform::read_f32(actor + 0x544) as f64;
    if direction == 1 {
        value = -value;
    }
    let candidate = (input + value) as f32 as f64;

    let mut boundary = actor + 0x538;
    let mut hit = false;
    if direction == 0 {
        if (platform::read_f32(boundary) as f64) <= candidate {
            platform::write_i32(actor + 0x54C, 0);
            hit = true;
            platform::write_u8(actor + 0x348, 1);
        }
    } else {
        if direction == 1 {
            boundary += 4;
        }
        if candidate <= platform::read_f32(boundary) as f64 {
            platform::write_i32(actor + 0x54C, direction as i32);
            hit = true;
            platform::write_u8(actor + 0x348, 0);
        }
    }

    if hit {
        platform::write_i32(actor + 0x554, 1);
        platform::write_f32(actor + 0x544, platform::read_f32(0x807C_E920));
        platform::write_i32(actor + 0x548, 0x1E);
        return platform::read_f32(boundary) as f64;
    }
    candidate
}

