/// Every pane pointer in the listed fields must be live.
///
/// # Confidence
/// high - every offset, bit mask and the animation index are literal.
pub unsafe fn fn_80620d70(this: usize) {
    let root = platform::read_u32(this + 0x244) as usize;
    let flags = platform::read_u8(root + 0xBB);
    platform::write_u8(root + 0xBB, flags & 0xFE | 1);

    for field in [0x328usize, 0x2B8, 0x2BC, 0x2C0, 0x348, 0x34C] {
        let pane = platform::read_u32(this + field) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
    }

    let selected = platform::read_u32(this + 0x33C) as usize;
    let flags = platform::read_u8(selected + 0xBB);
    platform::write_u8(selected + 0xBB, flags & 0xFE | 1);

    for field in [0x2CCusize, 0x2D0, 0x2D4, 0x2D8, 0x2DC, 0x2E0, 0x2E4] {
        let pane = platform::read_u32(this + field) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
    }

    let counter = platform::read_u32(this + 0x2C4) as usize;
    platform::write_u8(counter + 0xB8, 0xFF);
    abi_call1!(0x800C_9500, this + 0x70);
    abi_call3!(0x800C_92F0, this + 0x70, 0x11, 0);
    platform::write_u8(this + 0x37D, 1);
}

