    for animation in 3..10u32 {
        abi_call3!(0x800C_93D0, this + 0x70, animation, 0);
    }
    abi_call3!(0x800C_92F0, this + 0x70, 0, 0);

    let pane = platform::read_u32(this + 0x328) as usize;
    platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) | 1);
    for field in [0x33Cusize, 0x348] {
        let pane = platform::read_u32(this + field) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
    }
    let pane = platform::read_u32(this + 0x34C) as usize;
    platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) | 1);

    let mode = platform::read_u32(this + 0x354);
