/// Tests the launcher's position against a six-float zone record.
///
/// # Original
/// - Ghidra: `FUN_807698a0` at `0x807698A0` (304 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/807698a0_FUN_807698a0.c`
///
/// # Arguments
/// * `actor` - the launcher; position `+0xAC..+0xB4`, zone centre `+0xB8` /
///   `+0xC0`.
/// * `record` - address of six floats; entries `0`/`2` are one corner, entries
///   `3`/`5` the opposite corner on the same two axes.
///
/// # Returns
/// `1` when the actor lies inside the scaled rectangle, otherwise `0`. The
/// direction codes `2..5` computed inside are not part of the result.
///
/// # Side effects
/// None.
///
/// # Safety
/// `record` must point to six readable floats.
///
/// # Confidence
/// medium - the comparisons and the scaled tolerance are literal; the meaning of
/// the four direction codes is inferred from the axis they test.
pub unsafe fn fn_807698a0(actor: usize, record: usize) -> u32 {
    let x = platform::read_f32(actor + 0xAC);
    let z = platform::read_f32(actor + 0xB4);
    let mut direction = 6i32;

    if x == platform::read_f32(actor + 0xB8) {
        let target_z = platform::read_f32(actor + 0xC0);
        if z != target_z {
            direction = if z <= target_z { 3 } else { 2 };
        }
    } else if x <= platform::read_f32(actor + 0xB8) {
        direction = 4;
    } else {
        direction = 5;
    }

    if direction == 6 {
        return 0;
    }

    let scale = platform::read_f32(0x807C_F03C);
    let corner_x = platform::read_f32(record);
    let corner_z = platform::read_f32(record + 8);
    let center_x = (corner_x + platform::read_f32(record + 12)) * scale;
    let center_z = (corner_z + platform::read_f32(record + 20)) * scale;
    let tolerance_x = platform::read_f32(0x8081_6030) * scale + (center_x - corner_x).abs();
    let tolerance_z = platform::read_f32(0x8081_6034) * scale + (center_z - corner_z).abs();

    ((x - center_x).abs() < tolerance_x && (z - center_z).abs() < tolerance_z) as u32
}

