    // observed: the stepper returns int, the C truncates it to `short`.
    let returned = abi_call1!(0x800D_F890, actor + 0x43C) as u16 as i16;
    let current = platform::read_u16(actor + 0x43C) as i16;
    let bound = platform::read_u16(actor + 0x44A) as i16;
