        platform::write_u32(actor + 0x114, platform::read_u32(0x8042_D0B4));
        platform::write_u32(actor + 0xEC, platform::read_u32(0x807C_F698));
        platform::write_u32(actor + 0x118, platform::read_u32(0x8042_D0B8));
        return;
