    let stop0 = platform::read_u32(vtable0 + 0xB0) as usize;
    abi_call4!(stop0, effect0, actor + 0xAC, 0, 0);

    let effect1 = actor + 0x78C;
    let vtable1 = platform::read_u32(effect1) as usize;
    let stop1 = platform::read_u32(vtable1 + 0xB0) as usize;
    abi_call4!(stop1, effect1, actor + 0xAC, 0, 0);
