        platform::write_u32(object + 0x60, 0x8080_B5C8);
        abi_call1!(0x8006_9020, object + 0x3D0);
        platform::write_u32(object + 0x3EC, 0);
        abi_call1!(0x8016_9CD0, object + 0x3F0);
        abi_call1!(0x8016_8D10, object + 0x430);
        // unknown: 0x807E3E98 is the vtable installed over the fresh +0x430.
