    if actor == 0 {
        return mask;
    }

    let mut children = 0usize;
    let kind = platform::read_u16(actor + 8);
    if kind == 0x19B {
        children = actor + 0x460;
    } else if kind == 0x1A1 {
        children = actor + 0x4CC;
    }

    if children == 0 {
        if platform::read_u8(actor + 0x38C) as i8 == 1 {
            // observed: the vtable slot returns a pointer whose first byte is
            // the player index.
            let player = platform::read_u8(vmethod0(actor, 0x6C) as usize) as i8 as i32;
            if (player as u32) < 4 {
                let bit = 1u32 << (player as u32);
                if mask & bit == 0 {
                    let owner = abi_call1!(0x8016_2D00, platform::read_u32(actor + 0x2A78));
                    return fn_80728fe0(owner as usize, mask | bit);
                }
            }
        }
    } else {
        let mut link = platform::read_u32(children + 0xC) as usize;
        while link != 0 {
            mask = fn_80728fe0(platform::read_u32(link + 4) as usize, mask);
            link = platform::read_u32(link + 0x6C) as usize;
        }
    }
    mask
