/// Runs `0x80169CD0(+0x10)`, installs `0x803295D8` at `+0x50`, clears
/// `+0x54`/`+0x58`/`+0x78`, runs `0x8016A5E0(+0x5C)` and finally overwrites
/// `+0x50` with `0x80329578`.
///
/// # Safety
/// `slot` must hold at least 0x7C writable bytes.
///
/// # Confidence
/// high - the two vtable words and the sub-object calls are literal.
pub unsafe fn fn_8075ccb0(slot: usize) -> usize {
    abi_call1!(0x8016_9CD0, slot + 0x10);
    platform::write_u32(slot + 0x50, 0x8032_95D8);
    platform::write_u32(slot + 0x54, 0);
    platform::write_u32(slot + 0x58, 0);
    abi_call1!(0x8016_A5E0, slot + 0x5C);
    platform::write_u32(slot + 0x78, 0);
    // observed: the C sets the vtable word a second time, so the final value is
    // 0x80329578 rather than 0x803295D8.
    platform::write_u32(slot + 0x50, 0x8032_9578);
    slot
}

/// Destroys one bubble-ring record.
