    platform::write_u32(actor + 0x3A0, platform::read_u32(actor + 0xAC));
    platform::write_u32(actor + 0x3A4, platform::read_u32(actor + 0xB0));
    platform::write_u32(actor + 0x3A8, platform::read_u32(actor + 0xB4));
    fn_8075cff0(actor);
    platform::write_u32(actor + 0x128, platform::read_u32(actor + 0xAC));
    platform::write_u32(actor + 0x12C, platform::read_u32(actor + 0xB0));
    platform::write_u32(actor + 0x130, platform::read_u32(actor + 0xB4));
    platform::write_u32(actor + 0x134, platform::read_u32(0x807C_EC48));
    let record = abi_call1!(0x802B_9210, 0x40) as usize;
