        let base = 0x8081_47F4 + (platform::read_u32(actor + 4) & 0xFF) as usize * 0x2C;
        let mut position = [0f32; 3];
        position[0] = platform::read_f32(actor + 0xAC) - platform::read_f32(base);
        // observed: the middle component is the shared constant, not the actor's
        // own Y.
