    platform::write_u8(actor + 0x3AC, 0);
    fn_8075df70(actor);
    let record = 0x8081_47E0 + (platform::read_u32(actor + 4) & 0xFF) as usize * 0x2C;
    let scale = platform::read_f32(0x8081_479C);
    let mut position = [0f32; 3];
    position[0] = platform::read_f32(actor + 0xAC) - platform::read_f32(record + 0x14);
    position[1] = platform::read_f32(actor + 0xB0) - platform::read_f32(record + 0x18);
    position[2] = platform::read_f32(actor + 0xB4) - platform::read_f32(record + 0x1C);
    let first = platform::read_f32(record + 4);
    let horizontal = platform::read_f32(record + 0x10) * scale;
    let vertical = platform::read_f32(record + 0x0C) * scale;
