///
/// # Arguments
/// * `actor` - manager; state `+0xDC`, timer `+0xEC`, interface `+0xA0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the state and timer words, plays three sound cues, resets the board
/// through `0x800B4920`/`0x800B49E0` and dispatches one state event.
///
/// # Safety
/// The manager, its `+0xA0` interface and the main.dol audio managers must be
/// live.
///
/// # Confidence
/// medium - every state, timer, cue and event is literal; the roles of the
/// `0x800B48F0`-family board calls are `// unknown:`, and
/// `0x8042A440 + 0x10` is a player-count query whose exact meaning is
/// `// inferred:` from `fn_8064bcd0`.
pub unsafe fn fn_806f9060(actor: usize) {
    let state = platform::read_i32(actor + 0xDC);
    if state == 0 {
        let timer = platform::read_i32(actor + 0xEC) - 1;
        platform::write_i32(actor + 0xEC, timer);
        if timer < 1 {
            let vtable = platform::read_u32(0x8042_A440) as usize;
            let value = call0_ret(platform::read_u32(vtable + 0x10) as usize) as i32;
            // observed: `countLeadingZeros(value - 1) >> 5` is the `value == 1`
            // test, spelled the way Ghidra prints it.
            if value.wrapping_sub(1).leading_zeros() >> 5 != 0 {
                // unknown: 0x800B48F0 starts the board sequence.
                platform::call0(0x800B_48F0);
                platform::write_u32(actor + 0xEC, 0x96);
                platform::write_u32(actor + 0xDC, 1);
            }
        }
    } else if state == 1 {
        let timer = platform::read_i32(actor + 0xEC) - 1;
        platform::write_i32(actor + 0xEC, timer);
        if timer < 1 {
            // unknown: 0x800B49B0 finishes the board reveal.
            platform::call0(0x800B_49B0);
            platform::write_u32(actor + 0xEC, 0);
            platform::write_u32(actor + 0xDC, 2);
        }
    } else if state == 2 {
        // unknown: 0x800B4980 reports whether the board is still moving.
        if call0_ret(0x800B_4980) == 0 {
            // unknown: 0x800B4920 resets the board for the next phase.
            platform::call0(0x800B_4920);
            abi_call2!(0x8019_BED0, platform::read_u32(0x8042_A4A8), 2);
            abi_call3!(
                0x8019_5380,
                platform::read_u32(0x8042_A488),
                0x5DC,
                1
            );
            fn_806f8fc0(actor, 0x2D);
            platform::write_u32(actor + 0xEC, 0x1E0);
            platform::write_u32(actor + 0xDC, 3);
        }
    } else if state == 3 {
        platform::write_i32(actor + 0xEC, platform::read_i32(actor + 0xEC) - 1);
        // observed: Ghidra prints the callee without arguments; the manager is
        // still in r3, so the this pointer is passed here.
        let result = fn_806f8f70(actor);
        if platform::read_i32(actor + 0xEC) < 1 || result != 0 {
            let cue = if result != 0 { 0x5DA } else { 0x5DB };
            abi_call3!(
                0x8019_5380,
                platform::read_u32(0x8042_A488),
                cue,
                1
            );
            // unknown: 0x800B49E0 closes the board phase.
            platform::call0(0x800B_49E0);
            platform::write_u32(actor + 0xEC, 0);
            platform::write_u32(actor + 0xDC, 4);
        }
    } else if state == 4 && call0_ret(0x800B_4980) == 0 {
        vmethod1(actor + 0xA0, 0x18, 0x8082_ECF0);
        platform::write_u32(actor + 0xDC, 5);
    }
}

/// Publishes the round result and moves the manager to its terminal state.
///
/// Stores the `0x807CC330` word and `0x0F` in the global event block at
/// `0x80429DD0 + 0x90110`, plays cue `0x5DD`, sets the `+0xE0` flag, resets the
/// player state with `0x8005CA50`, raises the `0x8019BED0` event `3` and clears
/// the state id.
///
/// # Original
/// - Ghidra: `FUN_806F9250` at `0x806F9250` (148 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806f9250_FUN_806f9250.c`
///
/// # Arguments
/// * `actor` - manager; flag `+0xE0`, state `+0xDC`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two global stores, one cue, one local flag, one player reset, one event and
/// one state clear.
///
/// # Safety
/// The globals at `0x80429DD0`, `0x80429C94`, `0x8042A488` and `0x8042A4A8`
/// must be live.
///
/// # Confidence
/// high - every write, cue and event id is literal; the two-word event block is
/// the same one `fn_8074fa80` fills.
pub unsafe fn fn_806f9250(actor: usize) {
    let word = platform::read_u32(0x807C_C330);
    let event = platform::read_u32(0x8042_9DD0) as usize;
    platform::write_u8(event + 0x90114, 0x0F);
    platform::write_u32(event + 0x90110, word);
    abi_call3!(0x8019_5380, platform::read_u32(0x8042_A488), 0x5DD, 1);
    platform::write_u8(actor + 0xE0, 1);
    abi_call2!(0x8005_CA50, platform::read_u32(0x8042_9C94), 0);
    abi_call2!(0x8019_BED0, platform::read_u32(0x8042_A4A8), 3);
    platform::write_u32(actor + 0xDC, 0);
}

/// Tweens the global event word and raises the result event.
///
/// Feeds the four single-precision constants `0x807CC334..0x807CC33C` and the
/// current event word to `0x8015F140`, stores the updated word back, and when
/// the two compared counters `+0xE4`/`+0xE8` are equal and positive dispatches
/// descriptor `0x8082ED30` on the manager interface.
///
/// # Original
/// - Ghidra: `FUN_806F92F0` at `0x806F92F0` (176 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806f92f0_FUN_806f92f0.c`
///
/// # Arguments
/// * `actor` - manager; counters `+0xE4`/`+0xE8`, interface `+0xA0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One global event-word update and one possible state dispatch.
///
/// # Safety
/// The event block at `0x80429DD0` and the interface at `+0xA0` must be live.
///
/// # Confidence
/// medium - the argument order and the event address are literal; the four
/// arguments print as `(double)` because `0x8015F140` has no prototype, so they
/// are passed as `f32` through the existing `call_f32x4_u32` wrapper (the same
/// idiom as `0x806EC420`).
pub unsafe fn fn_806f92f0(actor: usize) {
    let event = platform::read_u32(0x8042_9DD0) as usize;
    let mut word = [0u32; 4];
    word[0] = platform::read_u32(event + 0x90110);
    call_f32x4_u32(
        0x8015_F140,
        platform::read_f32(0x807C_C334),
        platform::read_f32(0x807C_C338),
        platform::read_f32(0x807C_C33C),
        platform::read_f32(0x807C_C33C),
        word.as_mut_ptr() as u32,
    );
    platform::write_u32(event + 0x90110, word[0]);
    let left = platform::read_i32(actor + 0xE4);
    let right = platform::read_i32(actor + 0xE8);
    if left == right && left > 0 && right > 0 {
        vmethod1(actor + 0xA0, 0x18, 0x8082_ED30);
    }
}

