#[inline]
unsafe fn call_f32_u32x2_i16(addr: usize, a: f32, b: u32, c: u32, d: i16) -> u32 {
    let function: extern "C" fn(f32, u32, u32, i16) -> u32 = core::mem::transmute(addr);
    function(a, b, c, d)
}

