        // observed: 0x8012DE80 fills a three-float record from the rider.
        let mut source = [0f32; 3];
        abi_call2!(0x8012_DE80, source.as_mut_ptr() as u32, player as u32);

        // unknown: 0x801C0BD0 builds a 12-word transform from three floats.
        let mut matrix = [0f32; 12];
