/// Steps the sled along its rail while the brake lever is held.
///
/// Ticks the `+0x544` holder, and while the source object's byte `+0x790` is
/// set it maps the source phase onto one of six recorded sample slots, advances
/// the travel angle by a distance-proportional step, re-evaluates the anchor,
/// and latches the brake engagement into `+0x6F8` (playing the brake sound on
/// the first engaged frame).
///
/// # Original
/// - Ghidra: `FUN_8070a7c0` at `0x8070A7C0` (752 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8070a7c0_FUN_8070a7c0.c`
///
/// # Arguments
/// * `owner` - live sled actor; source pointer `+0x6D8`, sample bounds
///   `+0x6C0..+0x6CC`, travel angle `+0x6DC`, step `+0x6E0`, anchor `+0x6E4`,
///   slot `+0x6F0`, direction `+0x6F4`, state bytes `+0x6F8..+0x6FC`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May write `+0x6DC..+0x700`, and calls [`fn_8070a570`] when the brake is first
/// engaged.
///
/// # Safety
/// `owner` must be live, `+0x6AC`/`+0x544` must hold their interfaces, and the
/// recorded slot `+0x6F0` must stay within `0..6`.
///
/// # Confidence
/// medium - all arithmetic and both interface calls are literal; the six-slot
/// sample table and the "phase to slot" mapping are `// inferred:` from the
/// index arithmetic, and the `CONCAT44(0x43300000, x ^ 0x80000000)` block is
/// documented as the compiler's signed-integer conversion.
pub unsafe fn fn_8070a7c0(owner: usize) {
    vmethod0(owner + 0x544, 0x1C);

    let source = platform::read_u32(owner + 0x6D8) as usize;
    let engaged = platform::read_u8(source + 0x790);
    if engaged == 0 {
        platform::write_u8(owner + 0x6FC, 0);
        return;
    }

    let mode = platform::read_i32(source + 0x6DC);
    let sample_scale = platform::read_f32(0x807C_C8D8);

    // observed: `local_30[4]`, `local_20` and `local_1c` are contiguous, so the
    // C's six possible indices cover the pairs (x0,x1) and (x2,x3) plus their
    // two midpoints.
    let mut samples = [0f32; 6];
    samples[0] = platform::read_f32(owner + 0x6C0);
    samples[1] =
        (platform::read_f32(owner + 0x6C0) + platform::read_f32(owner + 0x6C4)) * sample_scale;
    samples[2] = platform::read_f32(owner + 0x6C4);
    samples[3] = platform::read_f32(owner + 0x6C8);
    samples[4] =
        (platform::read_f32(owner + 0x6C8) + platform::read_f32(owner + 0x6CC)) * sample_scale;
    samples[5] = platform::read_f32(owner + 0x6CC);

    let slot = (platform::read_i32(source + 0x6E0) - (mode * -2 + -5)) % 6;
    let mut switched = false;
    let current_slot = platform::read_i32(owner + 0x6F0);

    if mode == 0 && (slot == current_slot + 1 || slot == current_slot - 5) {
        platform::write_i32(owner + 0x6F0, slot);
        switched = true;
        platform::write_u32(owner + 0x6F4, 0);
    } else if mode == 1 && (slot == current_slot - 1 || slot == current_slot + 5) {
        platform::write_i32(owner + 0x6F0, slot);
        switched = true;
        platform::write_u32(owner + 0x6F4, 1);
    }

    let index = platform::read_i32(owner + 0x6F0) as usize;
    let mut target = [0f32; 3];
    call_f32x2_u32x2(
        ptr_at(ptr_at(owner + 0x6AC) + 0x18),
        samples[index],
        platform::read_f32(owner + 0xB4),
        target.as_mut_ptr() as u32,
        (owner + 0x6AC) as u32,
    );

    let difference = [
        target[0] - platform::read_f32(owner + 0xAC),
        target[1] - platform::read_f32(owner + 0xB0),
        target[2] - platform::read_f32(owner + 0xB4),
    ];
    let mut length = call_f32_1(0x801C_14C0, difference.as_ptr() as u32);
    length = (length / platform::read_f32(0x807C_C8DC)) * platform::read_f32(0x807C_C874);
    let limit = platform::read_f32(0x807C_C87C);
    if limit < length {
        length = limit;
    }

    // observed: `CONCAT44(0x43300000, x ^ 0x80000000)` minus the double at
    // `0x807CC8F0` is the compiler's signed-integer-to-float conversion.
    let converted = f64::from_bits(
        0x4330_0000_0000_0000
            | ((platform::read_u32(owner + 0x6F4) ^ 0x8000_0000) as u64),
    ) - read_f64(0x807C_C8F0);
    let bias = read_f64(0x807C_C8E0)
        - (platform::read_f32(0x807C_C8E8) * (converted as f32)) as f64;

    let step = (length as f64 * bias) as f32;
    platform::write_f32(owner + 0x6E0, step);
    platform::write_f32(owner + 0x6DC, platform::read_f32(owner + 0x6DC) + step);

    let angle = vmethod0_f32(owner + 0x6AC, 0x1C);
    platform::write_f32(owner + 0x6DC, angle);

    let mut anchor = [0f32; 3];
    call_f32x2_u32x2(
        ptr_at(ptr_at(owner + 0x6AC) + 0x18),
        angle,
        platform::read_f32(0x807C_C8D4),
        anchor.as_mut_ptr() as u32,
        (owner + 0x6AC) as u32,
    );
    platform::write_u32(owner + 0x6E4, anchor[0].to_bits());
    platform::write_u32(owner + 0x6E8, anchor[1].to_bits());
    platform::write_u32(owner + 0x6EC, anchor[2].to_bits());

    let just_engaged =
        platform::read_u8(owner + 0x6FC) == 0 && engaged != 0 && switched;
    platform::write_u8(owner + 0x6F8, just_engaged as u8);
    if just_engaged {
        fn_8070a570(owner);
    }

    let signed_limit = platform::read_f32(0x807C_C88C);
    let scale = platform::read_f32(0x807C_C888);
    platform::write_u8(owner + 0x6FC, engaged);

    let slope = -platform::read_f32(owner + 0x6E0) * scale;
    let mut delta = -signed_limit;
    if -signed_limit <= slope {
        delta = slope;
        if signed_limit < slope {
            delta = signed_limit;
        }
    }
    platform::write_f32(owner + 0x700, platform::read_f32(owner + 0x700) + delta);
}

