/// Keeps the rider within 224 units of its saved start position.
///
/// # Original
/// - Ghidra: `FUN_806a3be0` at `0x806A3BE0` (240 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806a3be0_FUN_806a3be0.c`
///
/// # Arguments
/// * `this` - live rider actor; saved start `+0x750`, current x `+0xAC`, speed
///   `+0xE8`, radius from the `+0x314` virtual.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// When the position leaves the `+/-224` band, clamps `+0xAC` back to the near
/// edge and sets the speed `+0xE8` to `-0.5`.
///
/// # Safety
/// `this` must be live and its vtable must provide `+0x314`.
///
/// # Confidence
/// high - the two-sided test, the `224.0` band, the `-0.5` speed and all three
/// virtual calls are literal.
pub unsafe fn fn_806a3be0(this: usize) {
    let radius = platform::read_f32(0x807C_A3E0); // 224.0f
    let high = platform::read_f32(this + 0x750) + radius;
    let low = platform::read_f32(this + 0x750) - radius;
    let x = platform::read_f32(this + 0xAC);

    let first = actor_method0_f32(this, 0x314);
    if low + first <= x {
        let second = actor_method0_f32(this, 0x314);
        if high - second < x {
            let third = actor_method0_f32(this, 0x314);
            platform::write_u32(this + 0xE8, platform::read_u32(0x807C_A3E4)); // -0.5f
            platform::write_f32(this + 0xAC, high - third);
        }
    } else {
        let fourth = actor_method0_f32(this, 0x314);
        platform::write_u32(this + 0xE8, platform::read_u32(0x807C_A3E4));
        platform::write_f32(this + 0xAC, low + fourth);
    }
}

