/// Tests a world point against the rider's overlap box.
///
/// # Original
/// - Ghidra: `FUN_806a42c0` at `0x806A42C0` (328 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806a42c0_FUN_806a42c0.c`
///
/// # Arguments
/// * `this` - live rider actor; centre `+0xAC`/`+0xB0`, facing `+0xE8`/`+0xEC`.
/// * `point` - three `f32` at `x`, `y`, `z`; only `x`/`y` are tested.
/// * `angles` - two `f32` at `x`, `y`; the facing vector of the candidate.
///
/// # Returns
/// `1` when the point falls inside the box, else `0`.
///
/// # Side effects
/// None; reads only.
///
/// # Safety
/// `point` and `angles` must be readable for 12 and 8 bytes.
///
/// # Confidence
/// high - the four half-extent tests, the `20.0` slope scale, the `36.0`
/// height and the `24.0` width are literal.
pub unsafe fn fn_806a42c0(this: usize, point: usize, angles: usize) -> u32 {
    let scale = platform::read_f32(0x807C_A348); // 20.0f
    let dy = platform::read_f32(this + 0xEC) - platform::read_f32(angles + 4);
    let dx = platform::read_f32(this + 0xE8) - platform::read_f32(angles);

    // observed: each term is the signed part of the slope offset, clamped to
    // zero on the other side so it only grows the box.
    let low_y = (dy * scale).min(0.0);
    let high_y = (dy * scale).max(0.0);
    let low_x = (dx * scale).min(0.0);
    let high_x = (dx * scale).max(0.0);

    let y = platform::read_f32(point + 4);
    let x = platform::read_f32(point);
    let base_y = platform::read_f32(this + 0xB0);
    let base_x = platform::read_f32(this + 0xAC);
    let edge = platform::read_f32(0x807C_A344) * platform::read_f32(0x807C_A3DC); // 24.0 * 0.5

    if y <= base_y + platform::read_f32(0x807C_A340) + low_y
        || base_y + platform::read_f32(0x807C_A33C) + high_y <= y
        || x <= (base_x - edge) + low_x
        || base_x + edge + high_x <= x
    {
        0
    } else {
        1
    }
}

