/// # Confidence
/// medium - the sound, the timer and the three stores are literal; the divisor
/// is the C's folded integer-to-double idiom, and `0x8068AB10` exists only as
/// `halt_baddata()` in the export.
pub unsafe fn fn_8068ab60(actor: usize) {
    let mut sample = [0u32; 2];
    abi_call2!(0x8006_A4B0, sample.as_mut_ptr() as u32, actor + 0xAC);
    abi_call4!(
        0x8019_8C30,
        platform::read_u32(0x8042_9D60),
        0x270,
        sample.as_ptr() as u32,
        0
    );

    // observed: the C folds the unsigned-int-to-double idiom into
    // `4503601774854204.0 - DAT_807c9a60`; the two constants are the bias
    // pairs 0x433000008000003C and 0x4330000080000000, so the result is 60.0.
    let frames = (f64::from_bits(0x4330_0000_8000_003C) - read_f64(0x807C_9A60)) as f32;
    let step = platform::read_f32(0x807C_9A44) / frames;

    platform::write_u32(actor + 0x550, 0x3C);
    let velocity_x = platform::read_f32(actor + 0xDC) * step;
    let velocity_y = platform::read_f32(actor + 0xE0) * step;
    let velocity_z = platform::read_f32(actor + 0xE4) * step;
    platform::write_f32(actor + 0x544, velocity_x);
    platform::write_f32(actor + 0x548, velocity_y);
    platform::write_f32(actor + 0x54C, velocity_z);

    // partial: 0x8068AB10 is truncated to `halt_baddata()` by the export, so it
    // is called by address and its behaviour is not reproduced.
    platform::call0(0x8068_AB10);
}

