/// Tests the actor against the scene's horizontal bounds.
///
/// # Original
/// - Ghidra: `FUN_8068C080` at `0x8068c080` (188 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8068c080_FUN_8068c080.c`
///
/// # Arguments
/// * `actor` - the `gabon_rock` actor; position `+0xAC..+0xB4`, flags `+0x04`.
///
/// # Returns
/// `true` when the actor is inside the scene span (or, for the non-flagged
/// variant, below the far edge).
///
/// # Side effects
/// None; only the scene object at `0x80429E00` and the actor are read.
///
/// # Safety
/// The scene object at `0x80429E00` must be live.
///
/// # Confidence
/// medium - the four scene offsets, the flag bit and all comparisons are
/// literal; the meaning of the scene fields is `// inferred:` as a rectangle
/// (`+0x38`/`+0x40` x span, `+0x3C`/`+0x44` z span) from [`fn_806513f0`].
pub unsafe fn fn_8068c080(actor: usize) -> bool {
    let scene = platform::read_u32(0x8042_9E00) as usize;
    let min_x = platform::read_f32(scene + 0x38);
    let max_x = min_x + platform::read_f32(scene + 0x40);
    let near_z = platform::read_f32(scene + 0x3C) - platform::read_f32(scene + 0x44);

    if (platform::read_u32(actor + 4) & 1) == 1 {
        let y = platform::read_f32(actor + 0xB0);
        let x = platform::read_f32(actor + 0xAC);
        return y <= platform::read_f32(scene + 0x3C)
            && near_z <= y
            && min_x <= x
            && x <= max_x;
    }

    if platform::read_f32(0x807C_9B20) + platform::read_f32(actor + 0xB0) < near_z {
        return true;
    }
    let x = platform::read_f32(actor + 0xAC);
    min_x <= x && x <= max_x
}

