/// Rebuilds the horizontal aim and the animation-rate field from the player.
///
/// # Original
/// - Ghidra: `FUN_8068C450` at `0x8068c450` (324 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8068c450_FUN_8068c450.c`
///
/// # Arguments
/// * `actor` - the `gabon_rock` actor; `+0x484` slot byte, `+0x490`/`+0x494`
///   aim mode, `+0xE8` speed, `+0x11C` rate, `+0xF4` horizontal speed.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x11C`, `+0xF4`; may overwrite `+0x11C` again when the ground probe
/// reports type `3`, and ends with the base update `0x8006CD90`.
///
/// # Safety
/// The actor, the ground probe `0x8007_0720` and the base update must be live.
///
/// # Confidence
/// medium - the two modes, the per-player table at `0x807C9B48` and every store
/// are literal; the character table at `0x8042C1A0` and the `0x80070720`
/// ground-type code `3` are `// inferred:`.
pub unsafe fn fn_8068c450(actor: usize) {
    platform::write_f32(actor + 0x11C, platform::read_f32(0x807C_9B58));

    // observed: the aim table is indexed by the word at +0x490.
    let roll = platform::read_f32(
        0x807C_9B48 + platform::read_u32(actor + 0x490) as usize * 4,
    );

    let mut slot = platform::read_u8(actor + 0x484) as i8 as i32;
    let mode = platform::read_u32(actor + 0x494);
    if mode == 1 {
        slot = (platform::read_u8(actor + 0x484) ^ 1) as i8 as i32;
    } else if mode != 0
        && platform::read_f32(0x807C_9B5C) <= platform::read_f32(actor + 0xE8).abs()
    {
        platform::write_f32(actor + 0x11C, platform::read_f32(0x807C_9A70));
    }

    // observed: `(&DAT_8042c1a0)[slot]` is the per-player character byte, and
    // the C converts it with the `CONCAT44(0x43300000, x ^ 0x80000000)` idiom.
    let character =
        platform::read_u8((0x8042_C1A0u32).wrapping_add(slot as u32) as usize) as i8;
    let raw = (character as i32 as u32) ^ 0x8000_0000;
    let converted =
        f64::from_bits(0x4330_0000_0000_0000 | raw as u64) - read_f64(0x807C_9B38);
    platform::write_f32(
        actor + 0xF4,
        platform::read_f32(0x807C_9B08) * converted as f32 * roll,
    );

    let ground = abi_call1!(0x8007_0720, actor + 0x1EC) as i16;
    if ground == 3 {
        let value = abi_call1!(0x800B_2EE0, 5);
        platform::write_f32(actor + 0xF4, platform::read_f32(0x807C_9A70));
        let converted =
            f64::from_bits(0x4330_0000_0000_0000 | value as u64) - read_f64(0x807C_9B68);
        platform::write_f32(
            actor + 0x11C,
            platform::read_f32(0x807C_9B60)
                + converted as f32 / platform::read_f32(0x807C_9B64),
        );
    }

    abi_call1!(0x8006_CD90, actor);
}

