/// Records the current node in the course cursor and rebuilds the map.
///
/// # Original
/// - Ghidra: `FUN_80799f10` at `0x80799F10` (292 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80799f10_FUN_80799f10.c`
///
/// # Arguments
/// * `this` - course-tree node record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// When the `0x3388` scene word matches `0x8081B738` and `0x802E1BD0` matches
/// the four bytes at `0x8081B73C`, the map is left alone. Otherwise the name is
/// classified (`F` + lowercase except `k`, or `W`), the `+0x48` course cursor is
/// set to `+0x22C`, and `0x8079A040` rebuilds the map.
///
/// # Safety
/// The scene, the course object `0x80429F7C` and the byte tables must be live.
///
/// # Confidence
/// medium - every test and store is literal; the `F`/`W` classes are inferred
/// from the character comparisons.
pub unsafe fn fn_80799f10(this: usize) {
    let scene = platform::read_u32(0x8042_A18C) as usize;
    let course = platform::read_u32(0x8042_9F7C) as usize;
    let index = platform::read_u32(scene + 0x338C) as usize;
    let base = scene + index * 0x16518 + 0x3394;
    let id = platform::read_u32(this + 0x22C);
    let mut handled = false;
    if platform::read_i32(0x8081_B738) == platform::read_i32(scene + 0x3388) {
        let name = abi_call2!(0x800F_56B0, base, id);
        if abi_call3!(0x802E_1BD0, name, platform::read_u32(0x8081_B73C), 4) == 0 {
            handled = true;
        }
    }
    if !handled {
        let name = abi_call2!(0x800F_56B0, base, id) as usize;
        let first = platform::read_u8(name);
        let second = platform::read_u8(name + 1);
        if first == b'F' {
            // observed: `(byte)(second + 0x9F) > 2` is the unsigned test
            // `second >= 0x64`; `second != 'k'` excludes the `Fk` class.
            if second.wrapping_add(0x9F) > 2 && second != b'k' {
                platform::write_u32(course + 0x48, id);
            }
        } else if first == b'W' {
            platform::write_u32(course + 0x48, id);
        }
        abi_call1!(0x8079_A040, this);
    }
}

