    platform::write_u8(lift + 0x1EC, platform::read_u8(0x807C_ED98));
    call_f32_u32(
        0x8016_80E0,
        platform::read_f32(0x807C_ED9C),
        (lift + 0x1B8) as u32,
    );
    call_f32_u32(
        0x8016_8FE0,
        platform::read_f32(0x807C_ED9C),
        (lift + 0x1B8) as u32,
    );
