    let owner = platform::read_i32(screen + 0x2DC);
    let record = elem(screen, owner, 0x0C);
    let position_x = platform::read_u32(record + 0x2A4);
    let position_y = platform::read_u32(record + 0x2A8);
    let position_z = platform::read_u32(record + 0x2AC);

    let player = ptr_at(elem(screen + 0x80, preview, 4));
    platform::write_u32(player + 0x22C, position_x);
    platform::write_u32(player + 0x230, position_y);
    platform::write_u32(player + 0x234, position_z);

