///
/// # Safety
/// `actor + 0x394` must hold a live interface object with a valid vtable.
///
/// # Confidence
/// high - the receiver and the slot offset are identical at every cited site.
unsafe fn actor_state_leave(actor: usize) {
    let interface = platform::read_u32(actor + 0x394) as usize;
    abi_call1!(
        platform::read_u32(interface + 0x1C) as usize,
        actor + 0x394
    );
}

