            let height =
                platform::read_f32(node + 0x24) + platform::read_f32(actor + 0x774);
            platform::write_u8(child + 0x459, (height < threshold) as u8);

            // observed: the C tests 0x193, then 0x191, then 0x3C.
            let child_kind = platform::read_u16(child + 8) as i16;
