/// Tests whether the rider may still claim a seat on the board.
///
/// # Original
/// - Ghidra: `FUN_80669DC0` at `0x80669DC0` (272 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80669dc0_FUN_80669dc0.c`
///
/// # Arguments
/// * `actor` - rider/board object; offset `+0x394`, flag `+0x765`.
/// * `other` - candidate player; ready byte `+0x38C`, seat query virtual
///   `+0x6C`, contact box `+0xEA4`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// When the candidate is ready, its seat index is `0..3`, the global player
/// mask selects it, the contact box reports a hit and [`fn_806692b0`] accepts
/// the span, records the seat with [`fn_806693d0`].
///
/// # Safety
/// Both objects must be live and the world transform readable.
///
/// # Confidence
/// medium - the five gates and the offset vector are literal; the box and
/// transform helpers are unprototyped.
pub unsafe fn fn_80669dc0(actor: usize, other: usize) {
    if platform::read_u8(other + 0x38C) != 1 {
        return;
    }

    let descriptor_ptr = {
        // observed: the seat query goes through the class vtable at +0x60.
        let function = ptr_at(ptr_at(other + 0x60) + 0x6C);
        let describe: extern "C" fn(u32) -> u32 = core::mem::transmute(function);
        describe(other as u32) as usize
    };
    let slot = platform::read_u8(descriptor_ptr);
    let seat = slot as i8;
    if seat < 0
        || seat >= 4
        || (platform::read_u32(0x8042_9CA8) & (1u32 << (seat as u32))) == 0
        || abi_call1!(0x8005_E500, other + 0xEA4) == 0
        || fn_806692b0(actor, other) == 0
    {
        return;
    }

    let mut point = [
        platform::read_f32(actor + 0xAC) + platform::read_f32(actor + 0x394),
        platform::read_f32(actor + 0xB0) + platform::read_f32(actor + 0x398),
        platform::read_f32(actor + 0xB4) + platform::read_f32(actor + 0x39C),
    ];
    let inside = abi_call3!(
        0x8013_F9E0,
        other,
        point.as_mut_ptr() as u32,
        (platform::read_u8(actor + 0x765) != 0) as u32
    );
    if inside != 0 {
        fn_806693d0(actor, slot);
    }
}

