    // +32.0f or -48.0f at 0x807CD708/0x807CD70C, selected by bit 3 of flags.
    let lift = platform::read_f32(0x807C_D708 + ((flags >> 2) & 4) as usize);
    // observed: the eight halfwords at 0x807CD6F0 are 0x2000 * n, an angle ramp.
    platform::write_u16(
        actor + 0x9D4,
        platform::read_u16(0x807C_D6F0 + (flags & 7) as usize * 2),
    );
