    platform::write_u32(actor + 0x9CC, (flags >> 4) & 1);
    platform::write_u8(actor + 0x348, ((flags >> 8) & 1) as u8);
    platform::write_u8(actor + 0xA06, (flags >> 12) as u8);
    platform::write_u32(actor + 0x94C, unit);
    platform::write_u32(actor + 0x950, unit);
    platform::write_u32(actor + 0x954, unit);
    platform::write_u32(actor + 0x9FC, unit);
    platform::write_u16(actor + 0x104, pitch);
    platform::write_f32(actor + 0xB0, platform::read_f32(actor + 0xB0) + lift);

