    anim[0] = platform::read_u32(0x807C_D724);
    anim[1] = platform::read_u32(0x807C_D728);
    anim[2] = platform::read_u32(0x807C_D72C);

    let mut arm = actor + 0x5BC;
    let mut angle_slot = actor + 0x9DA;
    let mut budget = actor;
    let mut source = actor;
    let mut phase = 0i16;
    let mut index = 1u32;
