/// Per-frame update that makes the board actor follow the camera height.
///
/// # Original
/// - Ghidra: `FUN_8073BCC0` at `0x8073BCC0` (384 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8073bcc0_FUN_8073bcc0.c`
///
/// # Arguments
/// * `actor` - the board actor; position `+0xAC..+0xB4`, motion `+0xEC`,
///   angle `+0x104`, animation `+0x148`, spawn `+0x448`/`+0x44C`, travel flags
///   `+0x454`/`+0x458`, camera track `+0x45C`/`+0x460`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Emits sound `0x222` through `0x80198660` at the `+0xAC` position, latches
/// `+0x458` once the actor has moved `21.0` from its spawn x, integrates the
/// camera's vertical delta into `+0xB0`, clears `+0xEC` once the actor is `12.0`
/// above the spawn y, clamps `+0xB4` at `3000.0`, and adds or subtracts `0x800`
/// from the `+0x104` angle according to `+0x454`.
///
/// # Safety
/// `actor` must be live and the scene pointer at `0x80429E00` loaded.
///
/// # Confidence
/// medium - every constant, offset and branch is literal; the sound context
/// `0x80429D5C` and the `+0x458` latch role are inferred.
pub unsafe fn fn_8073bcc0(actor: usize) {
    // observed: the export drops the receiver of 0x8006CD40; the object is r3.
    abi_call1!(0x8006_CD40, actor);

    let mut position = [0u32; 4];
    abi_call2!(0x8006_A4B0, position.as_mut_ptr() as u32, actor + 0xAC);
    abi_call5!(
        0x8019_8660,
        platform::read_u32(0x8042_9D5C),
        0x222,
        platform::read_u32(actor),
        position.as_mut_ptr() as u32,
        0
    );

    let threshold = platform::read_f32(0x807C_DD28); // observed: 21.0f
    if platform::read_u8(actor + 0x458) == 0 {
        if platform::read_u32(actor + 0x454) == 0 {
            if threshold
                <= platform::read_f32(actor + 0xAC) - platform::read_f32(actor + 0x448)
            {
                platform::write_u8(actor + 0x458, 1);
                abi_call1!(0x8008_C330, actor + 0x148);
            }
        } else if threshold
            <= platform::read_f32(actor + 0x448) - platform::read_f32(actor + 0xAC)
        {
            platform::write_u8(actor + 0x458, 1);
            abi_call1!(0x8008_C330, actor + 0x148);
        }
    }

    let previous_camera_y = platform::read_f32(actor + 0x45C);
    platform::write_f32(actor + 0x460, previous_camera_y);
    let scene = platform::read_u32(0x8042_9E00) as usize;
    let camera_y = platform::read_f32(scene + 0x3C);
    platform::write_f32(actor + 0x45C, camera_y);

    let y = platform::read_f32(actor + 0xB0) + (camera_y - previous_camera_y);
    platform::write_f32(actor + 0xB0, y);
    if platform::read_f32(0x807C_DD2C) + platform::read_f32(actor + 0x44C) <= y {
        platform::write_u32(actor + 0xEC, platform::read_u32(0x807C_DCE8)); // 0.0f
    }
    let ceiling = platform::read_f32(0x807C_DD30); // observed: 3000.0f
    if ceiling <= platform::read_f32(actor + 0xB4) {
        platform::write_f32(actor + 0xB4, ceiling);
    }

    let angle = platform::read_u16(actor + 0x104) as i16;
    let step = if platform::read_u32(actor + 0x454) == 0 {
        -0x800i16
    } else {
        0x800i16
    };
    platform::write_u16(actor + 0x104, angle.wrapping_add(step) as u16);
}

