                platform::write_u8(record + 0x0A, lane as u8);
                platform::write_u32(record, platform::read_u32(node + 0x1C));
                platform::write_u32(record + 4, platform::read_u32(node + 0x24));
                let id = abi_call1!(0x800D_2270, node);
                platform::write_u16(record + 8, id as u16);
