/// Probes every player against the fourteen collision slots and reports the
/// accumulated height.
///
/// # Original
/// - Ghidra: `FUN_80686550` at `0x80686550` (1884 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80686550_FUN_80686550.c`
///
/// # Arguments
/// * `this` - owner object: fourteen player slots at `+0x420`, height state at
///   `+0x458`, and the inline array object at `+0x4D4` (count at `+0x4D8`,
///   resume index at `+0x4DC`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Releases every live slot through `0x80685140`, then walks the array object's
/// flagged elements, writing `+0x68E`/`+0x38D` on a height-band hit, emitting
/// the `0x5A2` sound context, feeding `0x80684FE0`/`0x80685010` with the
/// quantised height, and finishing with the `0x80685090`/`0x80685150`/
/// `0x80685260` sweeps. The loop never terminates on its own: the final sweep
/// returns once all fourteen slots have been consumed.
///
/// # Safety
/// `this` must be a live owner and every slot pointer must be valid or zero.
///
/// # Confidence
/// medium - the element layout (`+0x00`/`+0x04` floats, `+0x08` table index,
/// `+0x0C` byte) and the array object are only reachable through the five raw
/// offsets the export shows; the reconvergence at `0x80686A84` is written as the
/// equivalent nested loops with the flag-byte `break` preserved.
pub unsafe fn fn_80686550(this: usize) {
    let five = platform::read_f32(0x807C_9894); // 5.0

    let mut slot = 0usize;
    while slot < 0x0E {
        let object = platform::read_u32(this + 0x420 + slot * 4) as usize;
        if object != 0 {
            // observed: r3 still holds the object at the `bl`; the export
            // prints no argument because the callee has no prototype.
            abi_call1!(0x8068_5140, object);
        }
        slot += 1;
    }

    let array = this + 0x4D4;
    let mut current = scan_collision_flags(array, 0);

    loop {
        let found = scan_collision_flags(array, platform::read_i32(this + 0x4D8));
        if current != found {
            // Not the element we were parked on: shift it and re-park.
            if !(-1 < current && current < platform::read_i32(array + 4)) {
                let refresh = ptr_at(platform::read_u32(array) as usize + 0x18);
                abi_call1!(refresh, array);
            }
            let element = platform::read_u32(array + 8) as usize + current as usize * 0x14;
            let weight_index = platform::read_f32(element + 8) as i32 as usize;
            // observed: 0x8042C1A0 is a signed byte table in main.dol.
            let weight = platform::read_u8(0x8042_C1A0 + weight_index) as i8 as f32;
            platform::write_f32(
                element,
                platform::read_f32(element) + weight * five,
            );
            current = advance_collision_flags(array, current);
            if platform::read_f32(element) < platform::read_f32(this + 0x4F4)
                || platform::read_f32(this + 0x4F0) < platform::read_f32(element)
            {
                let notify = ptr_at(platform::read_u32(this + 0x4D4) as usize + 0x24);
                abi_call2!(notify, this + 0x4D4, element);
            }
            continue;
        }

        // Same element: run the full fourteen-slot height sweep.
        let close = platform::read_f32(0x807C_989C); // 48.0
        let band = platform::read_f32(0x807C_98A0); // 28.0
        let step = platform::read_f32(0x807C_98AC); // 4.0
        let ceiling = platform::read_f32(0x807C_98E0); // 255.0
        let mut player = 0usize;
        loop {
            let player_object = platform::read_u32(this + 0x420 + player * 4) as usize;
            let mut height = platform::read_f32(0x807C_98C0); // 0.0
            let mut inner = scan_collision_flags(array, 0);
            loop {
                let resume = scan_collision_flags(array, platform::read_i32(this + 0x4D8));
                if inner != resume {
                    let element = platform::read_u32(array + 8) as usize + inner as usize * 0x14;
                    let anchor = platform::read_f32(player_object + 0xAC);
                    let weight_index = platform::read_f32(element + 8) as i32 as usize;
                    let weight = platform::read_u8(0x8042_C1A0 + weight_index) as i8 as f32;
                    if 0.0 <= weight * (anchor - platform::read_f32(element + 4)) {
                        let delta = weight * (platform::read_f32(element) - anchor);
                        // observed: the callee returns a float in f1; the
                        // wrapper hands back its bit pattern.
                        let gain = f32::from_bits(call_f32_u32(
                            0x800E_85A0,
                            delta,
                            (this + 0x458) as u32,
                        ));
                        height += gain;
                        if (close - band) < delta && delta < (close + band) {
                            let hit = platform::read_u8(element + 0x0C);
                            platform::write_u8(player_object + 0x68E, 1);
                            platform::write_u8(player_object + 0x38D, hit);
                        }
                        if abi_call3!(0x8068_6240, this, player_object, element) != 0 {
                            let id = platform::read_u32(player_object + 0x668);
                            let mut context = [0u32; 2];
                            abi_call2!(
                                0x8006_A4B0,
                                context.as_mut_ptr() as u32,
                                player_object + 0xAC
                            );
                            abi_call5!(
                                0x8019_8FC0,
                                platform::read_u32(0x8042_9D60),
                                0x5A2,
                                context.as_mut_ptr() as u32,
                                id as u16 as i16 as i32,
                                0
                            );
                        }
                    }
                    inner = advance_collision_flags(array, inner);
                    continue;
                }

                // Consume: quantise the accumulated height and feed both
                // helpers.
                // observed: the export prints the height before the player
                // pointer because 0x80684FE0 takes it in f1.
                call_f32_u32(0x8068_4FE0, height, player_object as u32);
                let mut scaled = height * step;
                if ceiling < scaled {
                    scaled = ceiling;
                }
                let quantised = scaled as u32;
                let low = quantised & 0xFF;
                let byte0 = quantised;
                let byte1 = (low * 0x14) as f32 / ceiling;
                let byte2 = (low * 0x50) as f32 / ceiling;
                let byte3 = ((low * 0x100 - low) as f32) / ceiling;
                let packed = (byte0 & 0xFF)
                    | ((byte1 as i32 as u32 & 0xFF) << 8)
                    | ((byte2 as i32 as u32 & 0xFF) << 16)
                    | ((byte3 as i32 as u32 & 0xFF) << 24);
                let mut record = [packed, packed];
                abi_call2!(
                    0x8068_5010,
                    player_object,
                    record.as_mut_ptr() as u32
                );
                break;
            }

            player += 1;
            if 0xD < player {
                // observed: the tail sweeps the same fourteen slots twice.
                let mut first = 0usize;
                while first < 0x0E {
                    let object = platform::read_u32(this + 0x420 + first * 4) as usize;
                    if object != 0 {
                        abi_call1!(0x8068_5090, object);
                        abi_call1!(0x8068_5150, object);
                    }
                    first += 1;
                }
                let mut second = 0usize;
                while second < 0x0E {
                    let object = platform::read_u32(this + 0x420 + second * 4) as usize;
                    if object != 0 {
                        abi_call1!(0x8068_5260, object);
                    }
                    second += 1;
                }
                return;
            }
        }
    }
}

