/// Draws the player-cursor quad and its standby copy.
///
/// # Original
/// - Ghidra: `FUN_806FD820` at `0x806FD820` (912 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806fd820_FUN_806fd820.c`
///
/// # Arguments
/// * `this` - cursor owner: gate words at `+0x210`/`+0x220`/`+0x1D5`/`+0x1D6`,
///   player lookup through `+0x208`, pane objects at `+0x224` and `+0x34C`,
///   standby flag at `+0x460`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Projects the player's `+0x50` pane into a screen point, selects one of four
/// colour pairs from the player index, writes the `+0xA0`/`+0x5C`/`+0x60`
/// pane calls on `this+0x224`, and the same trio plus the `+0x94` call on
/// `this+0x34C` the first time.
///
/// # Safety
/// `this` must be a live owner and the player object returned by `0x8005F900`
/// must be valid.
///
/// # Confidence
/// medium - the eight packed colour words are `li`/`oris` immediates and are
/// reproduced byte for byte, but their channel order is only implied by the
/// `& 0xFF` arguments; the `0x8016F130` output layout (`&r1+0x10`) is not
/// visible in this REL, so the first word and the height are taken from the
/// three-word output block.
pub unsafe fn fn_806fd820(this: usize) {
    if platform::read_i32(this + 0x210) <= 1
        || platform::read_u8(this + 0x220) == 0
        || platform::read_u8(this + 0x1D5) != 0
        || platform::read_u8(this + 0x1D6) != 0
    {
        return;
    }
    let player = abi_call1!(0x8005_F900, platform::read_u32(this + 0x208)) as usize;
    if player == 0 {
        return;
    }

    let mut primary = 0xFFFF_FFFFu32;
    let mut secondary = 0xFFFF_FFFFu32;
    match platform::read_u32(player + 0x14D4) {
        0 => {
            primary = 0xFFAB_00FF;
            secondary = 0xFF1B_00FF;
        }
        1 => {
            primary = 0x66FF_00FF;
            secondary = 0x00FF_15FF;
        }
        2 => {
            primary = 0x00FF_FFFF;
            secondary = 0x006C_FFFF;
        }
        3 => {
            primary = 0xFFFF_44FF;
            secondary = 0xFFC0_00FF;
        }
        _ => {}
    }

    let projected = abi_call1!(0x8005_6E30, player) as usize;
    let mut matrix = [0u32; 15];
    let project = ptr_at(ptr_at(projected) + 0x50);
    abi_call3!(project, projected, matrix.as_mut_ptr() as u32, 1);
    let mut screen = [0u32; 3];
    // unknown: 0x8016F130 converts the pane matrix into screen space; only the
    // first word and the second (height) are read by the callers.
    abi_call2!(
        0x8016_F130,
        matrix.as_mut_ptr() as u32,
        screen.as_mut_ptr() as u32
    );

    let index = platform::read_u32(player + 0x14D4);
    // unknown: out-of-range player indices keep whatever f31/f30 held; zero is
    // the only value the shipped callers can observe.
    let mut height_bias = 0.0f32;
    let mut fallback_bias = 0.0f32;
    if index > 1 {
        if index < 4 {
            height_bias = platform::read_f32(0x807C_C418); // 8.0
            fallback_bias = height_bias;
        }
    } else {
        height_bias = platform::read_f32(0x807C_C410); // 6.5
        fallback_bias = platform::read_f32(0x807C_C414); // 7.0
    }
    // observed: `*(player + 0x1090)` is re-read into the same register the
    // export reuses for the index, so it is a separate field.
    let state = platform::read_u32(player + 0x1090);
    if state == 3 {
        height_bias -= platform::read_f32(0x807C_C41C); // 2.0
    }
    let ground = f32::from_bits(screen[1]);
    let colour = if state == 0 || state == 3 {
        height_bias += ground;
        platform::read_f32(0x807C_C420) // 0.6
    } else {
        height_bias += fallback_bias;
        platform::read_f32(0x807C_C424) // 1.0
    };

    // observed: the `+0xA0` call takes a five-word block at `&local_84` and the
    // colour pair at `&local_78` (`block + 0xC`).
    let mut block = [0u32; 5];
    block[0] = screen[0];
    block[1] = height_bias.to_bits();
    block[2] = platform::read_u32(0x807C_C40C); // 5500.0
    block[3] = colour.to_bits();
    block[4] = colour.to_bits();

    let draw = this + 0x224;
    let place = ptr_at(ptr_at(draw) + 0xA0);
    abi_call6!(
        place,
        draw,
        0x8080_330C, // observed: "Wm_mg_cursor"
        0,
        block.as_mut_ptr() as u32,
        0,
        (block.as_ptr() as usize + 0xC) as u32
    );
    let tint = ptr_at(ptr_at(draw) + 0x5C);
    abi_call5!(
        tint,
        draw,
        (&primary as *const u32) as u32,
        (&secondary as *const u32) as u32,
        0,
        3
    );
    let channel = ptr_at(ptr_at(draw) + 0x60);
    abi_call5!(channel, draw, primary & 0xFF, secondary & 0xFF, 0, 3);

    if platform::read_u8(this + 0x460) == 0 {
        let standby = this + 0x34C;
        let place = ptr_at(ptr_at(standby) + 0xA0);
        abi_call6!(
            place,
            standby,
            0x8080_3320, // observed: "Wm_mg_cursor_st"
            0,
            block.as_mut_ptr() as u32,
            0,
            (block.as_ptr() as usize + 0xC) as u32
        );
        let tint = ptr_at(ptr_at(standby) + 0x5C);
        abi_call5!(
            tint,
            standby,
            (&primary as *const u32) as u32,
            (&secondary as *const u32) as u32,
            0,
            3
        );
        let channel = ptr_at(ptr_at(standby) + 0x60);
        abi_call5!(channel, standby, primary & 0xFF, secondary & 0xFF, 0, 3);
        let commit = ptr_at(ptr_at(standby) + 0x94);
        abi_call1!(commit, standby);
        platform::write_u8(this + 0x460, 1);
    }
}

/// Six-entry animation/digit selector for the cursor-position screen.
///
/// # Original
/// - Ghidra: `FUN_8070D1F0` at `0x8070D1F0` (1200 bytes)
