/// Advances the height gauge of the `+0x4B0` message owner.
///
/// # Original
/// - Ghidra: `FUN_80778500` at `0x80778500` (304 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80778500_FUN_80778500.c`
///
/// # Arguments
/// * `this` - gauge owner: step source at `+0x4F4`, accumulator at `+0xE0`,
///   mode word at `+0x504`, message object at `+0x4B0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Adds `+0x4F4` to `+0xE0`, clamps it against the per-character bounds
/// `0x807CF534[byte]`/`0x807CF54C[byte]` and posts `0x80832A60` or
/// `0x80832B20`.
///
/// # Safety
/// `this` must be a live owner; the byte at `+0x04` must index the two tables.
///
/// # Confidence
/// high - the two table bases, the three comparisons and the two message cells
/// are literal; the `unaff_GQR0` head/tail is the documented spill noise.
pub unsafe fn fn_80778500(this: usize) {
    let index = (platform::read_u32(this + 4) & 0xFF) as usize * 4;
    let lower = platform::read_f32(0x807C_F534 + index);
    let upper = platform::read_f32(0x807C_F54C + index);
    platform::call0(0x8077_7F60);

    let height = platform::read_f32(this + 0xE0) + platform::read_f32(this + 0x4F4);
    platform::write_f32(this + 0xE0, height);

    let message = this + 0x4B0;
    let post = ptr_at(ptr_at(message) + 0x18);
    if platform::read_u32(this + 0x504) == 0 {
        if lower < upper {
            if height <= lower {
                platform::write_f32(this + 0xE0, lower);
                abi_call2!(post, message, 0x8083_2A60);
            }
        } else if lower <= height {
            platform::write_f32(this + 0xE0, lower);
            abi_call2!(post, message, 0x8083_2A60);
        }
    } else if platform::read_f32(this + 0x4F4) <= platform::read_f32(0x807C_F584)
        && height <= lower
    {
        platform::write_f32(this + 0xE0, lower);
        abi_call2!(post, message, 0x8083_2B20);
    }
}

/// Initialises the player-position record and the height scale.
///
/// # Original
/// - Ghidra: `FUN_8077E250` at `0x8077E250` (448 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8077e250_FUN_8077e250.c`
///
/// # Arguments
/// * `this` - owner: follow flag at `+0x124`, position at `+0xAC`, scale at
///   `+0xDC`, message id at `+0x2D8`, `+0x18C` byte and `+0x2F8` byte.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Copies the `0x80780BB0` position into `+0xAC`, mirrors the master fields at
/// `[0x8042A1A0]+0x102/0x240` and `+0xDC/E0/E4`, selects the scale from the
/// `[0x8042A1A0]+0x27C` mode, resolves the message id through `0x80775080`,
/// clears `+0x2F8` and calls `0x8077E680`.
///
/// # Safety
/// `this` must be a live owner and `[0x8042A1A0]` initialised.
///
/// # Confidence
/// high - the nine switch arms, the three scale constants and the two
/// indirections through `[0x8042A1A0]` are literal; the `unaff_GQR0` head/tail
/// is the documented spill noise.
pub unsafe fn fn_8077e250(this: usize) {
    if platform::read_u8(this + 0x124) != 0 {
        let mut position = [0u32; 3];
        abi_call2!(0x8078_0BB0, position.as_mut_ptr() as u32, this);
        platform::write_u32(this + 0xAC, position[0]);
        platform::write_u32(this + 0xB0, position[1]);
        platform::write_u32(this + 0xB4, position[2]);
    }

    let master = platform::read_u32(0x8042_A1A0) as usize;
    platform::write_u32(this + 0x200, platform::read_u32(master + 0x240));
    platform::write_u16(this + 0x1E6, platform::read_u16(master + 0x102));

    let mut scale = platform::read_f32(0x807C_F69C);
    match platform::read_u32(master + 0x27C) {
        2 => {
            platform::write_u32(this + 0xAC, platform::read_u32(master + 0xAC));
            platform::write_u32(this + 0xB0, platform::read_u32(master + 0xB0));
            platform::write_u32(this + 0xB4, platform::read_u32(master + 0xB4));
            platform::write_u8(this + 0x18C, 1);
        }
        3 | 4 => {
            platform::write_u32(this + 0xAC, platform::read_u32(master + 0xAC));
            scale = platform::read_f32(0x807C_F780);
            platform::write_u32(this + 0xB0, platform::read_u32(master + 0xB0));
            platform::write_u32(this + 0xB4, platform::read_u32(master + 0xB4));
        }
        5 | 6 | 7 | 9 => {
            platform::write_u32(this + 0xAC, platform::read_u32(master + 0xAC));
            platform::write_u32(this + 0xB0, platform::read_u32(master + 0xB0));
            platform::write_u32(this + 0xB4, platform::read_u32(master + 0xB4));
        }
        8 => {
            platform::write_u32(this + 0x200, platform::read_u32(master + 0x23C));
        }
        10 => {
            platform::write_u32(this + 0xAC, platform::read_u32(master + 0xAC));
            scale = platform::read_f32(0x807C_F6B0);
            platform::write_u32(this + 0xB0, platform::read_u32(master + 0xB0));
            platform::write_u32(this + 0xB4, platform::read_u32(master + 0xB4));
        }
        0x0B | 0x0C => {
            platform::write_u32(this + 0xAC, platform::read_u32(master + 0xAC));
            platform::write_u32(this + 0xB0, platform::read_u32(master + 0xB0));
            platform::write_u32(this + 0xB4, platform::read_u32(master + 0xB4));
        }
        _ => {}
    }

    // unknown: 0x80775080 resolves the message id for the volume singleton.
    let message = abi_call2!(
        0x8077_5080,
        platform::read_u32(0x8042_A18C),
        platform::read_u32(this + 0x1F4)
    );
    platform::write_u32(this + 0x2D8, message);

    let model = platform::read_u32(this + 0x294) as usize;
    let value = platform::read_f32(model + 0x18) * scale;
    platform::write_f32(this + 0xDC, value);
    platform::write_f32(this + 0xE0, value);
    platform::write_f32(this + 0xE4, value);
    // observed: the export re-reads the master pointer after the 0x80775080 call.
    let master = platform::read_u32(0x8042_A1A0) as usize;
    platform::write_u32(this + 0xDC, platform::read_u32(master + 0xDC));
    platform::write_u32(this + 0xE0, platform::read_u32(master + 0xE0));
    platform::write_u32(this + 0xE4, platform::read_u32(master + 0xE4));

    platform::write_u8(this + 0x2F8, 0);
    abi_call1!(0x8077_E680, this);
}

/// Advances the height gauge with the full step/clamp state machine.
///
/// # Original
/// - Ghidra: `FUN_80778320` at `0x80778320` (384 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80778320_FUN_80778320.c`
///
/// # Arguments
/// * `this` - gauge owner: character byte at `+0x04`, accumulator at `+0xE0`,
///   step at `+0x4F4`, direction at `+0x4F8`, hold counter at `+0x4FC`, mode at
///   `+0x4EC`, message object at `+0x4B0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Accumulates the step, flips `+0x4F8` from the per-character `0x807CF510`
/// table, clamps against `0x807CF540`/`0x807CF54C`, decrements `+0x4FC` and
/// posts `0x80832A20` when it reaches zero.
///
/// # Safety
/// `this` must be a live owner with the `+0x04` byte indexing the tables.
///
/// # Confidence
/// high - the four table bases and the two clamp branches are literal.
pub unsafe fn fn_80778320(this: usize) {
    let index = (platform::read_u32(this + 4) & 0xFF) as usize * 4;
    let upper = platform::read_f32(0x807C_F540 + index);
    let limit = platform::read_f32(0x807C_F54C + index);

    if platform::read_i32(this + 0x4EC) == 1 {
        let previous = platform::read_f32(this + 0xE0);
        let step = platform::read_f32(this + 0x4F4);
        platform::call0(0x8077_7F60);
        let zero = platform::read_f32(0x807C_F584);
        platform::write_f32(this + 0xE0, previous + step);
        if zero == step {
            if previous <= zero {
                if previous < zero {
                    platform::write_u32(this + 0x4F8, platform::read_u32(0x807C_F510 + index));
                }
            } else {
                platform::write_f32(this + 0x4F8, -platform::read_f32(0x807C_F510 + index));
            }
        }
        if limit <= previous || platform::read_f32(this + 0xE0) < limit {
            if upper < previous && platform::read_f32(this + 0xE0) <= upper {
                platform::write_f32(this + 0x4F8, zero);
            }
        } else {
            platform::write_f32(this + 0x4F8, zero);
            platform::write_i32(this + 0x4FC, platform::read_i32(this + 0x4FC) - 1);
        }
        if platform::read_i32(this + 0x4FC) < 1 {
            let message = this + 0x4B0;
            let post = ptr_at(ptr_at(message) + 0x18);
            abi_call2!(post, message, 0x8083_2A20);
        }
    }
}

