/// Handles the carried-object contact and the `0x130`/`0x135` spawn replies.
///
/// # Original
/// - Ghidra: `FUN_80684680` at `0x80684680` (936 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80684680_FUN_80684680.c`
///
/// # Arguments
/// * `this` - the ridden actor: slot table `+0x668`, carried flags
///   `+0x686`, pose id `+0x38D`, body list `+0x69C`.
/// * `other` - the rider: actor id `+8`, mode byte `+0x38C`, view `+0x60`,
///   vertical speed `+0xEC`, class-token owner `+0x1464`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Marks the carried slot, spawns the impact amount through `0x80685050`,
/// posts `0x80828A60` through virtual `+0xD4`, and halves the amount when a
/// second body is inside the `[0, 12]` height window.
///
/// # Safety
/// `this` and `other` must be live actors; `other+0x60`, `other+0x1464` and the
/// returned token object must hold valid vtables.
///
/// # Confidence
/// high - the export's `func_0x802dcd6c()` 64-bit return is the documented
/// `r25-r31` save helper, so `r3 = this`, `r4 = other` survive (the high word is
/// `this`, the low word `other`). The `char` id is `extsb`-signed, so negative
/// ids index before `+0x686`.
pub unsafe fn fn_80684680(this: usize, other: usize) {
    if platform::read_u8(other + 0x38C) != 1 {
        let id = platform::read_u16(other + 8);
        let slot = platform::read_u32(this + 0x668) as usize;
        if id == 0x130 {
            platform::write_u8(other + slot + 0x5FA, 1);
            if abi_call1!(0x8068_52F0, this) != 0 {
                let method = ptr_at(ptr_at(other + 0x60) + 0xD4);
                abi_call2!(method, other, 0x8082_8A60);
                platform::write_u8(
                    this + 0x38D,
                    platform::read_u8(actor_method0(other, 0x6C) as usize),
                );
            } else if platform::read_u8(other + slot + 0x5FA) != 0
                && platform::read_u8(other + slot + 0x608) == 0
                && platform::read_f32(other + 0xEC) <= platform::read_f32(0x807C_9860)
            {
                call_f32_u32(
                    0x8068_5050,
                    platform::read_f32(other + 0xEC) * platform::read_f32(0x807C_9804),
                    this as u32,
                );
            }
        } else if id == 0x135 {
            if abi_call1!(0x8068_52F0, this) != 0 && platform::read_u8(0x807C_A498) != 0 {
                platform::write_f32(other + 0xEC, platform::read_f32(0x807C_A4A8));
            }
        } else if abi_call1!(0x8068_52F0, this) != 0 {
            platform::write_f32(other + 0xEC, platform::read_f32(0x807C_9870));
        }
        return;
    }

    // observed: `lbz` + `extsb` - the carried id is a signed byte.
    let carried = platform::read_u8(actor_method0(other, 0x6C) as usize) as i8;
    let cell = (this as isize + carried as isize) as usize;
    platform::write_u8(cell + 0x686, 1);
    if abi_call2!(0x8068_52C0, this, carried as i32 as u32) == 0 {
        if abi_call1!(0x8068_52F0, this) != 0 {
            let method = ptr_at(ptr_at(other + 0x60) + 0x3FC);
            call_f32x2_u32x4(
                method,
                platform::read_f32(0x807C_981C),
                platform::read_f32(other + 0xE8),
                other as u32,
                1,
                2,
                0,
            );
        }
        return;
    }

    if abi_call2!(0x8005_6CF0, other, 0x1C) != 0
        || abi_call2!(0x8005_6CF0, other, 0x1F) != 0
    {
        let zero = platform::read_f32(0x807C_9860);
        let twelve = platform::read_f32(0x807C_9820);
        let mut hit = 0usize;
        let mut index = 0usize;
        while index < 2 {
            if abi_call3!(0x8068_43B0, other, this, index) == 0 {
                let entry = ptr_at(this + index * 4 + 0x69C);
                let delta = platform::read_f32(this + 0xB0) - platform::read_f32(entry + 0xB0);
                if zero <= delta && delta <= twelve {
                    hit = entry;
                    break;
                }
            }
            index += 1;
        }
        abi_call2!(0x8068_4FA0, this, carried as i32 as u32);
        let mut amount = platform::read_f32(0x807C_97FC);
        if hit != 0 {
            abi_call2!(0x8068_4FA0, hit, carried as i32 as u32);
            amount *= platform::read_f32(0x807C_985C);
            call_f32_u32(0x8068_5050, amount, hit as u32);
        }
        call_f32_u32(0x8068_5050, amount, this as u32);
        return;
    }

    // observed: three class tokens are tested in turn; the third shares the
    // second's `0.05` factor, and only `0.03`/`0.05`/`0.0` are reachable.
    let mut factor = platform::read_f32(other + 0xEC);
    let mut token = vmethod0(other + 0x1464, 0x28) as usize;
    if vmethod1(token, 0x10, 0x8035_425C) != 0 {
        factor *= platform::read_f32(0x807C_9800);
    } else {
        token = vmethod0(other + 0x1464, 0x28) as usize;
        if vmethod1(token, 0x10, 0x8035_429C) != 0 {
            factor *= platform::read_f32(0x807C_9808);
        } else {
            token = vmethod0(other + 0x1464, 0x28) as usize;
            if vmethod1(token, 0x10, 0x8035_431C) != 0 {
                factor *= platform::read_f32(0x807C_9808);
            } else {
                factor *= platform::read_f32(0x807C_9860);
            }
        }
    }
    call_f32_u32(0x8068_5050, factor, this as u32);
}

/// Unpacks the spawn word of the `0x9A10`-sized object and builds its panes.
///
/// # Original
/// - Ghidra: `FUN_8068e0b0` at `0x8068E0B0` (912 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8068e0b0_FUN_8068e0b0.c`
///
/// # Arguments
/// * `this` - freshly allocated object: spawn word `+4`, flag byte `+0x38F`,
///   pane array count `+0xC68`, model pane `+0x3D0`, holder `+0x394`, array
///   block `+0x4B4` with `0xE4`-byte entries.
///
/// # Returns
/// Always `1`.
///
/// # Side effects
/// Writes the unpacked nibbles at `+0x348`, `+0xC38`, `+0xC3C`, `+0xC68`,
/// `+0xC4C`, `+0xC48`, the two table-driven heights `+0xB4`, builds the model
/// pane through `0x8007FB80` and adds `0xE4`-stride panes through
/// `0x8007FAD0`.
///
/// # Safety
/// `this` must be a writable object with the `+0xC3C..+0xC7E` block, a valid
/// `+0x394` holder and the `0x807EF418` descriptor table readable.
///
/// # Confidence
/// medium - all stores and arguments are literal, but the two tables at
/// `0x807C9C08`/`0x807C9C10` are one flat array read with a two-word skew, so
/// only indices 0/1 yield plausible integers; the twelve-word `0x800A42B0`
/// record is copied verbatim and the `0x807EF418` triples have no visible
/// element type.
pub unsafe fn fn_8068e0b0(this: usize) -> u32 {
    let word = platform::read_u32(this + 4);
    let index = ((word >> 6) & 0xF) as usize;
    let table_word = platform::read_u32(0x807C_9C08 + index * 4);
    let table_float = platform::read_f32(0x807C_9C10 + index * 4);

    let ten = platform::read_f32(0x807C_9C18);
    let one = platform::read_f32(0x807C_9C1C);
    let thirty_two = platform::read_f32(0x807C_9C20);
    let scale = ten * (one / (ten * table_float));
    // observed: `lfd`/`fsubs` with 0x807C9C40 (plain 2^52) - the unsigned
    // nibble converted through the 2^52 idiom.
    let half_word = f64::from_bits(0x4330_0000_0000_0000u64 | (((word >> 20) & 0xF) as u64))
        - read_f64(0x807C_9C40);

    platform::write_f32(this + 0xB4, platform::read_f32(0x807C_9C24));
    platform::write_u8(this + 0x348, ((word >> 12) & 1) as u8);
    platform::write_u32(this + 0xC3C, word & 0xFF);
    platform::write_u32(this + 0xC38, (word >> 8) & 0xF);
    platform::write_u32(this + 0xC68, table_word);
    platform::write_f32(this + 0xC4C, table_float);
    // observed: `fctiwz` then `sth` of the low word.
    let angle = scale * thirty_two * (one + half_word as f32);
    platform::write_u16(this + 0xC48, angle as i32 as u16);

    if platform::read_u8(this + 0x38F) == 1 {
        platform::write_f32(this + 0xB4, platform::read_f32(0x807C_9C28));
    }

    let second = f64::from_bits(0x4330_0000_0000_0000u64 | (((word >> 16) & 0xF) as u64))
        - read_f64(0x807C_9C40);
    platform::write_f32(
        this + 0xB4,
        platform::read_f32(this + 0xB4) - ten * (second as f32),
    );

    abi_call1!(0x8068_E820, this);
    let spread = platform::read_f32(0x807C_9C2C) * platform::read_f32(this + 0xC4C);
    if platform::read_u32(this + 0xC3C) == 0 {
        vmethod1(this + 0x394, 0x18, 0x8082_AE70);
    } else {
        let handle = abi_call1!(0x8068_E8E0, this);
        if handle == 0 {
            vmethod1(this + 0x394, 0x18, 0x8082_AE30);
        } else {
            abi_call2!(0x8068_E970, this, handle);
            vmethod1(this + 0x394, 0x18, 0x8082_AE70);
        }
    }

    platform::write_u16(this + 0x104, platform::read_u16(this + 0xC7E));
    let mut vector = [0u32; 4];
    vector[0] = platform::read_u32(this + 0xAC);
    vector[1] = platform::read_u32(this + 0xB0);
    vector[2] = spread.to_bits();
    vector[3] = 0;
    let resource = abi_call2!(
        0x8006_6890,
        platform::read_u32(0x8042_9D40),
        vector.as_ptr() as u32
    );
    platform::write_u32(this + 0xC40, resource);

    call_f32x3_u32x7(
        0x8007_FB80,
        platform::read_f32(0x807C_9C30),
        platform::read_f32(0x807C_9C30),
        spread,
        (this + 0x3D0) as u32,
        this as u32,
        0x8068_E6A0,
        0,
        0,
        1,
        platform::read_u8(this + 0x38F) as u32,
    );
    platform::write_u32(this + 0x4A0, platform::read_u32(this + 0x4A0) | 0x0080_0000);
    abi_call1!(0x8007_F900, this + 0x3D0);

    let zero = platform::read_f32(0x807C_9C30);
    platform::write_f32(this + 0xD0, zero);
    platform::write_f32(this + 0xD4, zero);
    platform::write_f32(this + 0xD8, zero);

    let mut scale_triple = [one, one, one];
    let count = platform::read_u32(this + 0xC68);
    if count > 1 {
        let mut step = 1usize;
        while (step as u32) < count {
            // observed: `local_b8`/`local_b4` = {-24.0, 32.0 + spread} and
            // `local_c0`/`local_bc` = {24.0, spread - 8.0}; the first pair sits
            // at the lower address, so the vector order is the reverse of the
            // literal assignment order.
            let lower = [
                platform::read_f32(0x807C_9C34),
                thirty_two + spread,
            ];
            let upper = [
                platform::read_f32(0x807C_9C38),
                spread - platform::read_f32(0x807C_9C3C),
            ];
            let pane = this + 0x4B4 + 0xE4 * step;
            call_u32x10(
                0x8007_FAD0,
                pane as u32,
                this as u32,
                lower.as_ptr() as u32,
                upper.as_ptr() as u32,
                platform::read_u32(0x807E_F418 + 12 * step),
                platform::read_u32(0x807E_F41C + 12 * step),
                platform::read_u32(0x807E_F420 + 12 * step),
                1,
                platform::read_u8(this + 0x38F) as u32,
                scale_triple.as_mut_ptr() as u32,
            );
            let link = this + 0xC6E + 2 * step;
            // observed: `lha`/`add`/`sth` over the `0x807C9BF6` step table.
            platform::write_u16(
                link,
                (platform::read_u16(this + 0xC7E) as i16)
                    .wrapping_add(platform::read_u16(0x807C_9BF6 + 2 * step) as i16)
                    as u16,
            );
            abi_call2!(0x8007_FD80, pane as u32, link as u32);
            // observed: the export's `iVar5 + 0x584` with `iVar5 = this + 0xE4*i`
            // (the pane's flag word at `pane - 0x14`).
            let flags = this + 0x584 + 0xE4 * step;
            platform::write_u32(flags, platform::read_u32(flags) | 0x0080_0000);
            abi_call1!(0x8007_F900, pane as u32);
            step += 1;
        }
    }
    1
}

/// Runs the four-state `MSG`-driven tutorial gate.
///
/// # Original
/// - Ghidra: `FUN_806fe480` at `0x806FE480` (892 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806fe480_FUN_806fe480.c`
///
/// # Arguments
/// * `this` - gate owner: state `+0x21C`, countdown `+0x214`, flag bytes
///   `+0x1D5`/`+0x1D6`, eighteen `0x10`-byte records at `+0x70`, holder
///   `+0x194`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Arms up to ten message slots, walks the eighteen records through
/// `0x806FBEB0`/`0x806FBDA0`, posts `0x5F0`/`0x5F1`/`0x5FE` through
/// `0x80195380` and finally posts `0x8082F008` through virtual `+0x18`.
///
/// # Safety
/// `this` must be a live owner; `[0x8042A488]`, `[0x8042A4A8]` and the eighteen
/// records' `+0x80` pointers must be valid.
///
/// # Confidence
/// high - the `addic.` countdown, the unsigned `(x - 7) > 2` record test and the
/// two-clock (CTR = 2) nine-byte scan of state 2 are all literal.
pub unsafe fn fn_806fe480(this: usize) {
    abi_call1!(0x806F_D7A0, this);

    match platform::read_i32(this + 0x21C) {
        0 => {
            platform::write_i32(this + 0x214, platform::read_i32(this + 0x214) - 1);
            let mut trigger = false;
            if platform::read_u8(this + 0x1D6) != 0
                && abi_call2!(0x8019_6600, platform::read_u32(0x8042_A488), 0x5EE) == 0
                && platform::read_u8(this + 0x1D6) != 0
                && abi_call2!(0x8019_6600, platform::read_u32(0x8042_A488), 0x5EF) == 0
            {
                trigger = true;
            } else if platform::read_u8(this + 0x1D5) != 0
                && abi_call2!(0x8019_6600, platform::read_u32(0x8042_A488), 0x5EC) == 0
            {
                trigger = true;
            }
            if trigger {
                if platform::read_u8(this + 0x1D6) == 0 {
                    abi_call2!(0x8019_BED0, platform::read_u32(0x8042_A4A8), 7);
                    platform::write_u8(this + 0x6A0, 1);
                    let mut index = 0usize;
                    while index < 0x12 {
                        let record = this + index * 0x10;
                        // observed: `addi r0,r3,-7` / `cmplwi r0,2` / `ble`, so
                        // the test is the unsigned `(row - 7) > 2`.
                        if platform::read_u8(record + 0x7D) != 0
                            && platform::read_u32(record + 0x78).wrapping_sub(7) > 2
                        {
                            abi_call1!(0x806F_BEB0, platform::read_u32(record + 0x80));
                        }
                        index += 1;
                    }
                }
                let mut slot = 0;
                while slot < 4 {
                    let actor = abi_call1!(0x8005_F900, slot);
                    if actor != 0 {
                        abi_call2!(0x8005_6C70, actor, 0x5F);
                        let method = ptr_at(ptr_at(actor as usize + 0x60) + 0x3A0);
                        abi_call1!(method, actor);
                    }
                    slot += 1;
                }
                platform::write_i32(this + 0x214, 0x1E);
                platform::write_i32(this + 0x21C, 1);
            }
        }
        1 => {
            platform::write_i32(this + 0x214, platform::read_i32(this + 0x214) - 1);
            let mut trigger = false;
            if platform::read_u8(this + 0x1D6) != 0
                && abi_call2!(0x8019_6600, platform::read_u32(0x8042_A488), 0x75F) == 0
            {
                trigger = true;
            } else if platform::read_u8(this + 0x1D5) != 0
                && abi_call2!(0x8019_6600, platform::read_u32(0x8042_A488), 0x760) == 0
            {
                trigger = true;
            }
            if trigger {
                abi_call3!(0x8019_5380, platform::read_u32(0x8042_A488), 0x5F0, 1);
                if platform::read_u8(this + 0x1D5) != 0 {
                    abi_call3!(0x8019_5380, platform::read_u32(0x8042_A488), 0x5FE, 1);
                }
                let mut index = 0usize;
                while index < 0x12 {
                    let record = this + index * 0x10;
                    if platform::read_u8(record + 0x7D) == 0 {
                        abi_call1!(0x806F_BDA0, platform::read_u32(record + 0x80));
                    }
                    index += 1;
                }
                platform::write_i32(this + 0x21C, 2);
                platform::write_i32(this + 0x214, 0);
            }
        }
        2 => {
            let remaining = platform::read_i32(this + 0x214) - 1;
            platform::write_i32(this + 0x214, remaining);
            if remaining < 1 {
                // observed: `mtspr CTR,2` + `bdnz`, so two passes over nine
                // bytes at stride 0x10 starting `+0x7D` and `+0x7D + 0x90`.
                let mut filled = 0u32;
                let mut block = 0usize;
                while block < 2 {
                    let base = this + block * 0x90;
                    let mut lane = 0usize;
                    while lane < 9 {
                        if platform::read_u8(base + 0x7D + lane * 0x10) != 0 {
                            filled += 1;
                        }
                        lane += 1;
                    }
                    block += 1;
                }
                if filled == 0x12 {
                    abi_call3!(0x8019_5380, platform::read_u32(0x8042_A488), 0x5F1, 1);
                    platform::write_i32(this + 0x21C, 3);
                    platform::write_i32(this + 0x214, 0x46);
                }
            }
        }
        3 => {
            let remaining = platform::read_i32(this + 0x214) - 1;
            platform::write_i32(this + 0x214, remaining);
            if remaining < 1 {
                platform::write_i32(this + 0x214, 0);
                vmethod1(this + 0x194, 0x18, 0x8082_F008);
            }
        }
        _ => {}
    }
}

/// Synchronises the four model-pane transforms from the `+0x5DC` object table.
///
/// # Original
