    if (platform::read_u8(this + 0x430) as i8) < 0 || platform::read_u8(this + 0x772) == 0 {
        platform::write_f32(this + 0xE8, platform::read_f32(0x807C_B5C8));
        abi_call2!(0x806D_3840, this, 0);
        return;
    }

    let angle = abi_call1!(0x806D_37D0, this) as u16 as i16;
    let previous = platform::read_u16(this + 0x104) as i16;
    let step = abi_call2!(0x806D_3840, this, (-(angle as i32)) as u32) as u16 as i16;
    if (step > 0xB9F && previous < 0xBA1) || (step < -0xB9F && previous > -0xBA1) {
        abi_call2!(0x8004_39B0, this, mask as u32);
        abi_call1!(0x806D_3A60, this);
    }

    let magnitude = (-(step as i32)) as i32 as f32;
    let three_thousand = 3000.0f32;
    let rate = (magnitude * platform::read_f32(0x807C_B59C)) / three_thousand;
    let requested = (magnitude * platform::read_f32(0x807C_B5A4)) / three_thousand;
    let zero = platform::read_f32(0x807C_B5C8);
    let floor = platform::read_f32(0x807C_B5A0);
