            let mut proceed = true;
            let query = vmethod0(this + 0x394, 0x28) as usize;
            if vmethod1(query, 0x14, 0x8083_04D8) == 0 {
                let query = vmethod0(this + 0x394, 0x28) as usize;
                if vmethod1(query, 0x14, 0x8083_0458) == 0 {
                    proceed = false;
                }
            }
            if !proceed {
                let query = vmethod0(this + 0x394, 0x28) as usize;
                if vmethod1(query, 0x14, 0x8083_0498) == 0 {
                    flip = false;
                }
            }
