    let database = platform::read_u32(0x8042_A18C);
    let near = platform::read_u32(this + 0x1F4);
    if platform::read_u32(this + 0x1FC) == near
        || platform::read_u32(this + 0x1F8) == near
    {
        return zero;
    }

    let mut first = [0.0f32; 3];
    let mut second = [0.0f32; 3];
    abi_call3!(
        0x8010_0200,
        first.as_mut_ptr() as usize,
        database,
        near
    );
    abi_call3!(
        0x8010_0200,
        second.as_mut_ptr() as usize,
        database,
        platform::read_u32(this + 0x1FC)
    );
    let mut v1 = [
        second[0] - first[0],
        0.0,
        second[2] - first[2],
    ];

    abi_call3!(
        0x8010_0200,
        first.as_mut_ptr() as usize,
        database,
        near
    );
    abi_call3!(
        0x8010_0200,
        second.as_mut_ptr() as usize,
        database,
        platform::read_u32(this + 0x1F8)
    );
    let mut v2 = [
        second[0] - first[0],
        0.0,
        second[2] - first[2],
    ];

    let zx = platform::read_f32(0x8037_7DC8);
    let zy = platform::read_f32(0x8037_7DCC);
    let zz = platform::read_f32(0x8037_7DD0);
    if (v1[0] == zx && 0.0 == zy && v1[2] == zz)
        || (v2[0] == zx && 0.0 == zy && v2[2] == zz)
    {
        return zero;
    }

    let length1 = call_f32_1(0x801C_14C0, v1.as_mut_ptr() as u32);
    let dot = (v1[0] * v2[0] + v1[1] * v2[1]) + v1[2] * v2[2];
    let length2 = call_f32_1(0x801C_14C0, v2.as_mut_ptr() as u32);
    // observed: `f30 / f31` then `/ f1` - two separate single-precision divides.
    (dot / length1) / length2
