            abi_call2!(
                0x8016_EDD0,
                this + 0x7C,
                angles.as_ptr().add(1) as usize
            );
            abi_call2!(0x8016_ECB0, this + 0x7C, angles.as_ptr() as usize);
            abi_call2!(
                0x8016_EEF0,
                this + 0x7C,
                angles.as_ptr().add(2) as usize
            );
