/// the 48-byte basis is produced only by `0x8016ED10`, so its layout stays
/// opaque.
pub unsafe fn fn_80780bd0(out: *mut f32, this: usize, src: *const f32, extra: i16) {
    // observed: the manager pointer is loaded from main.dol cell 0x8042A18C.
    let manager = platform::read_u32(0x8042_A18C);
    if abi_call2!(0x8077_5800, manager, platform::read_u32(this + 0x1F8)) != 0 {
        platform::write_f32(out as usize, platform::read_f32(src as usize));
        platform::write_f32(out as usize + 4, platform::read_f32(src as usize + 4));
        platform::write_f32(out as usize + 8, platform::read_f32(src as usize + 8));
        return;
    }

    let height = call_f32_1(0x8078_12E0, this as u32);
    let angle = abi_call1!(0x8078_1330, this) as u16;
    let mut angle_slot = [0u16; 8];
    // observed: `sth` truncates the 32-bit sum to 16 bits.
    angle_slot[0] = angle.wrapping_add(extra as u16);

    let mut vector = [0u32; 4];
    platform::write_f32(
        vector.as_mut_ptr() as usize,
        platform::read_f32(0x807C_F698), // 0.0
    );
    platform::write_f32(
        vector.as_mut_ptr() as usize + 4,
        platform::read_f32(0x807C_F698), // 0.0
    );
    platform::write_f32(vector.as_mut_ptr() as usize + 8, height);

    // unknown: 0x8016ED10(&basis48, &angle) and 0x801C1160(&basis48, &v, &v)
    // are the rotation pair; the basis is never read as anything else here.
    let mut basis = [0u32; 12];
    abi_call2!(
        0x8016_ED10,
        basis.as_mut_ptr() as u32,
        angle_slot.as_ptr() as u32
    );
    abi_call3!(
        0x801C_1160,
        basis.as_mut_ptr() as u32,
        vector.as_mut_ptr() as u32,
        vector.as_mut_ptr() as u32
    );

    platform::write_f32(
        out as usize,
        platform::read_f32(vector.as_ptr() as usize) + platform::read_f32(src as usize),
    );
    platform::write_f32(
        out as usize + 4,
        platform::read_f32(vector.as_ptr() as usize + 4) + platform::read_f32(src as usize + 4),
    );
    platform::write_f32(
        out as usize + 8,
        platform::read_f32(vector.as_ptr() as usize + 8) + platform::read_f32(src as usize + 8),
    );
}

/// Re-resolves one pane's level/scale record and inherits the facing angle.
///
/// Copies the two-word lookup at `0x80782050(this+0x214)` to `+0x1F8`/`+0x26C`,
/// asks `0x800F57A0` for the level record and stores `1.0` when it is absent or
/// `0.95` when present, then samples the three floats at `m+0x2D0..0x2D8`
/// through `0x801C1650` and reduces the implicit `f1` with `0x802BE470`. A
/// non-zero reduction copies `m+0x102` into the signed halfword at `+0x1E6`;
/// finally `+0x200` moves to `+0x204` and the pane record is re-resolved.
///
/// # Original
/// - Ghidra: `FUN_80780e20` at `0x80780E20` (292 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80780e20_FUN_80780e20.c`
///
/// # Arguments
/// * `this` - pane: level key `+0x1F4`, lookup base `+0x214`, facing `+0x1E6`,
///   record `+0x200`/`+0x204`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Five calls and seven field writes.
///
/// # Safety
/// `this` must be a live pane and both manager tables reachable.
///
/// # Confidence
/// medium - both strides, the two scale constants and every store are literal;
/// the two-word lookup, the implicit float return and `0x802BE470`'s role are
/// inferred.
pub unsafe fn fn_80780e20(this: usize) {
    // observed: main.dol cell 0x8042A18C holds the manager pointer; the
    // wave-132 prose printed 0x8043A18C.
    let manager = platform::read_u32(0x8042_A18C) as usize;
    let lookup = abi_call1!(0x8078_2050, this + 0x214) as usize;
    platform::write_u32(this + 0x1F8, platform::read_u32(lookup));
    platform::write_u32(this + 0x26C, platform::read_u32(lookup + 4));

    let index = platform::read_u32(manager + 0x338C) as usize;
    let level = abi_call3!(
        0x800F_57A0,
        manager + index * 0x16518 + 0x3394,
        platform::read_u32(this + 0x1F4),
        0x100
    );
    platform::write_f32(
        this + 0x310,
        if level == 0 {
            platform::read_f32(0x807C_F69C) // 1.0
        } else {
            platform::read_f32(0x807C_F7D0) // 0.95
        },
    );

    // observed: 0x8042A1A0 is the main.dol actor cell.
    let actor = platform::read_u32(0x8042_A1A0) as usize;
    let mut sample = [0u32; 3];
    sample[0] = platform::read_u32(actor + 0x2D0);
    sample[1] = platform::read_u32(actor + 0x2D4);
    sample[2] = platform::read_u32(actor + 0x2D8);
    // observed: 0x801C1650 leaves its length in `f1`, which 0x802BE470
    // consumes without any register setup between the two calls.
    let length = call_u32x2_f32(
        0x801C_1650,
        (actor + 0xAC) as u32,
        sample.as_mut_ptr() as u32,
    );
    let reduced = f32_of_f32(0x802B_E470, length);
    if reduced != platform::read_f32(0x807C_F698) {
        platform::write_u16(this + 0x1E6, platform::read_u16(actor + 0x102));
    }

    platform::write_u32(this + 0x204, platform::read_u32(this + 0x200));
    let index = platform::read_u32(manager + 0x338C) as usize;
    let record = abi_call3!(
        0x800F_3330,
        manager + 0x5C7F4 + index * 0x3F08,
        platform::read_u32(this + 0x1F4),
        platform::read_u32(this + 0x1F8)
    );
    platform::write_u32(this + 0x200, record);
}

