    abi_call3!(
        0x801C_0540,
        matrix.as_mut_ptr() as u32,
        (model + 0x108) as u32,
        matrix.as_mut_ptr() as u32
    );

    let mut identity = [0u32; 12]; // 48-byte scratch at r1+0x20
    call_f32x3_u32(
        0x801C_0BD0,
        zero,
        zero,
        zero,
        identity.as_mut_ptr() as u32,
    );
    abi_call3!(
        0x801C_0540,
        matrix.as_mut_ptr() as u32,
        identity.as_mut_ptr() as u32,
        matrix.as_mut_ptr() as u32
    );

    let mut result = [0u32; 3];
