    platform::write_f32(this + 0x1D8, platform::read_f32(pos as usize));
    platform::write_f32(this + 0x1DC, platform::read_f32(pos as usize + 4));
    platform::write_f32(this + 0x1E0, platform::read_f32(pos as usize + 8));

