/// `0x800E7E40(+0x9C20) + 0x800E7E30(+0x9C20) * 0.5` when that is larger. The
/// x coordinate is `0x8065C210(*(f32*)(this+0x9CC8), &-16.0, &0.0)` plus
/// `0x800E80B0(+0x9C20) - 0x800E7E20(+0x9C20)`. The z slot is `7100.0`.
///
/// # Original
/// - Ghidra: `FUN_8065c100` at `0x8065C100` (264 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8065c100_FUN_8065c100.c`
///
/// # Arguments
/// * `this` - actor: base height `+0xAC`, moving sub-object `+0x9C20`, clamp
///   input `+0x9CC8`, embedded submit object `+0x99E4`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Five scalar accessor calls and one virtual `+0xB0` dispatch.
///
/// # Safety
/// `this+0x9C20` must be a live sub-object and `this+0x99E4` must hold a valid
/// vtable with a callable `+0xB0` entry.
///
/// # Confidence
/// medium - every operand and all five calls are literal; the four
/// `0x800E7E2x`/`0x800E7E4x`/`0x800E80B0` contracts are not described by this
/// REL, so their roles stay `// unknown:`.
pub unsafe fn fn_8065c100(this: usize) {
    let moving = this + 0x9C20;
    let base = platform::read_f32(this + 0xAC) + 1088.0; // observed: 0x807E6EEC
    // unknown: 0x800E7E30/0x800E7E40/0x800E7E20/0x800E80B0(this+0x9C20)
    let half = f32_of_obj(0x800E_7E30, moving) * 0.5; // observed: 0x807C8AEC
    let sum = f32_of_obj(0x800E_7E40, moving) + half;
    // observed: `bge` to the `fmr` keeps the base only when `sum < base`
    let y = if sum < base { base } else { sum };

    let a = f32_of_obj(0x800E_7E20, moving);
    let b = f32_of_obj(0x800E_80B0, moving);
    let x = call_f32_u32x2_f32(
        0x8065_C210,
        platform::read_f32(this + 0x9CC8),
        0x807E_6EF0, // observed: -16.0 lerp bound
        0x807E_6EF4, // observed: 0.0 lerp bound
    ) + (b - a);

    let record = [y, x, 7100.0f32]; // observed: 7100.0 is 0x807C8AF0
    let receiver = this + 0x99E4;
    let vtable = platform::read_u32(receiver) as usize;
    let method = platform::read_u32(vtable + 0xB0) as usize;
    abi_call4!(
        method,
        receiver,
        record.as_ptr() as u32,
        0u32,
        0u32
    );
}

/// Raises message `796` while the moving sub-object is below a height ceiling.
///
/// The body returns unless `*(f32*)(this+0xAC)+1088.0 <= 0x800E7E40+0x800E7E30`
/// (the `cror 2,0,2` + `bne` pair branches when the left side is greater). It
/// then builds `(0x800E80B0 - 0x800E7E20*0.5 - (*(f32*)(this+0xB0)+2624.0)) +
/// 0x800E7E20`, truncates it with `fctiwz`, sign-extends the low halfword and
/// passes it to virtual `+0x2C` of the `0x80439D64` singleton as message `796`.
///
/// # Original
/// - Ghidra: `FUN_8065c260` at `0x8065C260` (264 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8065c260_FUN_8065c260.c`
///
/// # Arguments
/// * `this` - actor: height cells `+0xAC`/`+0xB0`, sub-object `+0x9C20`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Up to five accessor calls and one virtual message dispatch.
///
/// # Safety
/// `this+0x9C20` must be live and `[0x80439D64]` must hold a message manager
/// with a callable `+0x2C` slot.
///
/// # Confidence
/// medium - the gate polarities, all five float calls and the
/// `fctiwz`/`extsh` ladder are literal; the accessor contracts and message
/// `796`'s meaning are `// unknown:`.
pub unsafe fn fn_8065c260(this: usize) {
    let moving = this + 0x9C20;
    let base = platform::read_f32(this + 0xAC) + 1088.0; // observed: 0x807E6EEC
    let half = f32_of_obj(0x800E_7E30, moving);
    let ceiling = f32_of_obj(0x800E_7E40, moving) + half;
    // observed: `cror 2,0,2` then `bne` leaves only `base <= ceiling`
    if !(base <= ceiling) {
        return;
    }

    let height = platform::read_f32(this + 0xB0) + 2624.0; // observed: 0x807E7368
    let shrink = f32_of_obj(0x800E_7E20, moving) * 0.5; // observed: 0x807C8AEC
    let offset = f32_of_obj(0x800E_80B0, moving) - shrink;
    // observed: the second 0x800E7E20 call is live; its result is not the first
    let radius = f32_of_obj(0x800E_7E20, moving);
    let value = ((offset - height) + radius) as i32 as i16;

    let singleton = platform::read_u32(0x8043_9D64) as usize;
    let vtable = platform::read_u32(singleton) as usize;
    let method = platform::read_u32(vtable + 0x2C) as usize;
    abi_call4!(method, singleton, 796u32, value as i32 as u32, 0u32);
}

/// Resets the player-cursor state and returns `1`.
///
/// Clears the byte cells `+0x1D4..+0x1D6` and `+0x6A0`, the word cells
/// `+0x1D8`, `+0x1E0`, `+0x1E4`, `+0x1DC`, `+0x1E8`, then burns
/// `rand_mod(1000)` draws, stores `rand_mod(6)` at `+0x1D0`, stores the active
/// player count at `+0x210`, stores `rand_mod(count)` at `+0x208`, resolves it
/// through `0x806FE290` into `+0x208`/`+0x20C`, and clears the remaining
/// counters.
///
/// # Original
/// - Ghidra: `FUN_806fcdf0` at `0x806FCDF0` (268 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806fcdf0_FUN_806fcdf0.c`
///
/// # Arguments
/// * `this` - cursor object: state bytes at `+0x1D4`, counters at `+0x1EC`.
///
/// # Returns
/// Always `1` (the `li r3,1` at `0x806FCE98` is never clobbered).
///
/// # Side effects
/// Six `rand_mod` draws (plus the warm-up loop), two player-count/probe calls
/// and the field clears listed above.
///
/// # Safety
/// `this` must be a live cursor; `[0x80354E60]` must be initialised because
/// `0x8005FEF0` and `0x806FE290` walk the player table.
///
/// # Confidence
/// medium - every store and call is literal (including the interim store of the
/// raw draw at `+0x208`); the return type and the `rand(1000)` loop's purpose
/// are inferred, so they stay commented.
pub unsafe fn fn_806fcdf0(this: usize) -> u32 {
    platform::write_u8(this + 0x1D4, 0);
    platform::write_u8(this + 0x1D5, 0);
    platform::write_u8(this + 0x1D6, 0);
    platform::write_u32(this + 0x1D8, 0);
    platform::write_u32(this + 0x1E0, 0);
    platform::write_u32(this + 0x1E4, 0);
    platform::write_u32(this + 0x1DC, 0);
    platform::write_u32(this + 0x1E8, 0);
    platform::write_u8(this + 0x6A0, 0);

    // unknown: the warm-up loop burns `rand_mod(1000)` draws for an unrecorded
    // reason; the count itself comes from the same generator.
    let warmup = abi_call1!(0x800B_2ED0, 1000u32);
    let mut draw = 0u32;
    while draw < warmup {
        abi_call1!(0x800B_2ED0, 1000u32);
        draw += 1;
    }

    platform::write_u32(this + 0x1D0, abi_call1!(0x800B_2ED0, 6u32));
    let count = call0_ret(0x8005_FEF0);
    platform::write_u32(this + 0x210, count);
    let index = abi_call1!(0x800B_2ED0, count);
    // observed: the raw draw is stored before the probe; the probe receives
    // `this`, so the interim value is observable.
    platform::write_u32(this + 0x208, index);
    let resolved = abi_call2!(0x806F_E290, this, index);
    platform::write_u32(this + 0x208, resolved);
    platform::write_u32(this + 0x20C, resolved);

    platform::write_u8(this + 0x220, 0);
    platform::write_u8(this + 0x460, 0);
    platform::write_u8(this + 0x6A1, 0);
    platform::write_u8(this + 0x6A2, 0xFF);
    platform::write_u32(this + 0x214, 0);
    platform::write_u32(this + 0x218, 0);
    platform::write_u32(this + 0x21C, 7);
    platform::write_u32(this + 0x700, 0);
    platform::write_u32(this + 0x70, 0);
    platform::write_u8(this + 0x704, 0);
    platform::write_u32(this + 0x1EC, 0);
    platform::write_u32(this + 0x1F0, 0);
    platform::write_u32(this + 0x1F4, 0);
    platform::write_u32(this + 0x1F8, 0);
    platform::write_u32(this + 0x1FC, 0);
    platform::write_u32(this + 0x200, 0);
    platform::write_u32(this + 0x204, 0);
    1
}

