            // unknown: 0x8005F900(player_index) returns the player actor.
            let player = abi_call1!(0x8005_F900, i) as usize;
            let dy = platform::read_f32(player + 0xB0) - platform::read_f32(point + 0xB0);
            let dx = platform::read_f32(player + 0xAC) - platform::read_f32(point + 0xAC);
