/// and all eight stores are literal, and the export matches.
pub unsafe fn fn_80725170(this: usize) {
    // observed: `lbz` then `extsb` - the id is a signed byte.
    let character = platform::read_u8(this + 0x38D) as i8 as i32;
    // unknown: 0x8005F900(id) resolves the player object (`*(node + 8)`).
    let player = abi_call1!(0x8005_F900, character) as usize;

    // observed: `lfsx` over the table at 0x807CD208 = {2.5, -2.5, 0.75, -1.5}.
    let index = platform::read_u8(this + 0x348) as usize;
    let table = platform::read_f32(0x807C_D208 + 4 * index);
    // observed: 0x807CD210 is the table's second entry reused as 0.75.
    let height = table + 0.75f32 * platform::read_f32(player + 0xE8);

    // observed: 0x80065CB0(this) is `*(u32*)(this + 0x134) = 0`.
    abi_call1!(0x8006_5CB0, this);

    platform::write_u32(this + 0x59C, platform::read_u32(this + 0x59C) | 0x1000);
    platform::write_f32(this + 0x114, -0.2); // observed: 0x807CD200
    platform::write_f32(this + 0xE8, height);
    platform::write_f32(this + 0xEC, -1.5); // observed: 0x807CD214
    platform::write_f32(this + 0xF0, 0.0); // observed: 0x807CD1BC
    platform::write_u32(this + 0x488, platform::read_u32(this + 0x488) | 0x0090_0000);
    platform::write_u32(this + 0x494, platform::read_u32(this + 0x494) | 0x0090_0000);
    platform::write_u32(this + 0x4BC, 0);
}

/// Classifies the target direction into one of three angular sectors.
///
/// Builds the XZ difference `(target - source)` from the two position pairs,
/// normalises it in place, then returns `1` when the Y component is inside the
/// `±pi/8` band, `0` when it is at or above zero, and `2` when it is below.
///
/// # Original
/// - Ghidra: `FUN_8069a170` at `0x8069A170` (184 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8069a170_FUN_8069a170.c`
///
/// # Arguments
/// * `this` - actor: target `+0x768`/`+0x76C`, source `+0xAC`/`+0xB0`.
///
/// # Returns
/// Sector id `0`, `1` or `2` in `r3`.
///
/// # Side effects
/// One in-place normalise of a three-float stack vector and two angular probes.
///
/// # Safety
/// `this` must be a live actor.
///
/// # Confidence
/// medium - every branch, both subtraction pairs and the three returns are
/// literal; the only inference is that `0x802BE4A0` is `sinf`, which the body
/// does not rely on (it calls the helper and compares).
pub unsafe fn fn_8069a170(this: usize) -> u32 {
    // observed: [0] = +0x768 - +0xAC, [1] = +0x76C - +0xB0, [2] = 0.0.
    let mut vec = [
        platform::read_f32(this + 0x768) - platform::read_f32(this + 0xAC),
        platform::read_f32(this + 0x76C) - platform::read_f32(this + 0xB0),
        platform::read_f32(0x807C_A08C), // observed: 0.0
    ];
    // unknown: 0x80170980(&vec3) normalises the vector in place.
    abi_call1!(0x8017_0980, vec.as_mut_ptr() as u32);

    // inferred: 0x802BE4A0(f32) -> f32 is `sinf`; the pair is ±pi/8.
    let upper = call_f32_f32(0x802B_E4A0, 0.392_699_09);
    let lower = call_f32_f32(0x802B_E4A0, -0.392_699_09);
    let dy = vec[1];

    // observed: `bge` twice on `fcmpu` - the in-band test is the negation of
    // both, so an unordered compare also falls through to `1`.
    if !(lower >= dy) && !(dy >= upper) {
        1
    } else if dy >= 0.0 {
        0
    } else {
        2
    }
}

