///
/// # Side effects
/// One call to [`fn_806561b0`]; no writes.
///
/// # Safety
/// The BSS pointer at `0x80429E00` must point at the live timer object.
///
/// # Confidence
/// medium - the body is fully decoded and the export agrees; the timer object
/// behind `0x80429E00` is BSS (no shipped bytes), so only its two float fields
/// are modelled.
pub unsafe fn fn_80656260(this: usize) -> f32 {
    // unknown: timer object behind 0x80429E00 (main.dol BSS); +0x3C/+0x44 are
    // f32 heights and are the only fields this caller touches.
    let timer = ptr_at(0x8042_9E00);
    let height = platform::read_f32(timer + 0x3C);
    let other = platform::read_f32(timer + 0x44);
    let error = height - 16.0; // observed: 0x807C88FC

    // observed: the three-instruction fold is exact in single precision and is
    // emitted in instruction order: (32.0 + (error - other)) - error.
    let mut sample = 32.0 + (error - other); // observed: 0x807C88F8
    sample -= error;
    sample = sample.abs();
    sample *= 0.0625; // observed: 0x807C8900

    // observed: `fctiwz` - round toward zero into the 32-bit GPR.
    let sample = sample as i32;
    let count = fn_806561b0(this, sample as u32);

    // observed: 0x43300000 ladder over the returned integer.
    let converted = f64::from_bits(0x4330_0000_0000_0000 | (count as u32 as u64 ^ 0x8000_0000))
        - read_f64(0x807C_8908);
    error - 16.0 * converted as f32
}

