/// the two BSS unit cells and of ids `1397`/`1` are inferred.
pub unsafe fn fn_80716590(this: usize) {
    let zero = platform::read_f32(0x807C_CD30); // observed: 0.0
    platform::write_f32(this + 0xE8, zero);
    platform::write_f32(this + 0xEC, zero);
    platform::write_f32(this + 0xF0, zero);
    platform::write_u16(this + 0x7C4, 20); // observed: `li r0,20` / `sth`
    fn_80715ed0(this);

    // observed: 0x8006A4B0(&dst[3], this+0xAC) copies three floats.
    let mut sample = [0u32; 3];
    abi_call2!(0x8006_A4B0, sample.as_mut_ptr() as u32, this + 0xAC);
    // unknown: 0x80198C30(sound_unit, 1397, &vec3, 0) emits a positional sound.
    abi_call4!(
        0x8019_8C30,
        ptr_at(0x8042_9D60),
        0x575,
        sample.as_ptr() as u32,
        0
    );
    // unknown: 0x800D8C60(camera_unit, 0, 1, 0, 0) pushes a camera event.
    abi_call5!(0x800D_8C60, ptr_at(0x8042_A008), 0, 1, 0, 0);
}

/// Sets or clears bit 0 of a render flag and re-stamps the child records.
///
/// When both flag bytes `+0x270` and `+0x271` are set, sets bit 0 of the render
/// record's `+0xBB` byte, fires virtual slot `0x10` on the receiver at `+0xA0`
/// and re-runs [`fn_80608df0`]. Otherwise it only clears that bit. Returns `1` on
/// both paths.
///
/// # Original
/// - Ghidra: `FUN_80608d10` at `0x80608D10` (136 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80608d10_FUN_80608d10.c`
///
/// # Arguments
/// * `this` - actor: flags `+0x270`/`+0x271`, render record `+0x238`, vtable
///   `+0xA8`, receiver `+0xA0`.
///
/// # Returns
/// Always `1`.
///
/// # Side effects
/// One byte store on both paths, plus the virtual call and [`fn_80608df0`] on
/// the set path (which writes twelve render records).
///
/// # Safety
/// `this` must be a live actor and the render record must be writable.
///
/// # Confidence
/// high - all 34 words decode, both arms are literal, and the export matches
/// including the receiver at `this+0xA0` and the `& 0xFE | 1` bit dance.
pub unsafe fn fn_80608d10(this: usize) -> u32 {
    if platform::read_u8(this + 0x270) != 0 && platform::read_u8(this + 0x271) != 0 {
        // observed: the record pointer is read before the virtual call on this
        // path (`lwz r4,568(r3)` at 0x80608D3C).
        let record = platform::read_u32(this + 0x238) as usize;
        platform::write_u8(record + 0xBB, (platform::read_u8(record + 0xBB) & 0xFE) | 1);

        // observed: `lwz r12,168(r3)` / `lwz r12,16(r12)` / `bcctr` with the
        // receiver at `this+0xA0`.
        let vtable = platform::read_u32(this + 0xA8) as usize;
        abi_call1!(platform::read_u32(vtable + 0x10) as usize, this + 0xA0);
        fn_80608df0(this);
    } else {
        // observed: the clear arm re-reads `+0x238` after the branch.
        let record = platform::read_u32(this + 0x238) as usize;
        platform::write_u8(record + 0xBB, platform::read_u8(record + 0xBB) & 0xFE);
    }
    1
}

