/// Rebuilds the two mount transforms from the position and the signed angle.
///
/// Takes the snapshot at `+0xAC`, rotates it by `+0x100..+0x104`, mounts it on
/// `this+0x3F0`, then repeats the whole block for the second mount `this+0x430`
/// using the `+0x4A0` angle (flipped by `0x8000` when `+0x4D0` is set) and the
/// `+0x4A8`/`+0x4AC` radial offset.
///
/// # Original
/// - Ghidra: `FUN_8072bc40` at `0x8072BC40` (604 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8072bc40_FUN_8072bc40.c`
///
/// # Arguments
/// * `this` - object with `+0xAC..+0xB4` position, `+0x100..+0x104` angle,
///   `+0x4A0` angle, `+0x4A8`/`+0x4AC` offsets, `+0x4D0` half-turn flag and the
///   two mounts at `+0x3F0`/`+0x430`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Builds three 48-byte matrices, calls `0x80064AF0`, `0x801C0BD0`,
/// `0x801C0540`, the three mount setters and three binders per mount, then
/// [`fn_8072c180`] and [`fn_8072bea0`].
///
/// # Safety
/// `this` must expose both mounts and the NW4R matrix helpers must be callable.
///
/// # Confidence
/// high - both `qr3` loads are u16 (GQR3 = 0x00050005); every call, constant and
/// matrix argument is literal.
pub unsafe fn fn_8072bc40(this: usize) {
    let zero = platform::read_f32(0x807C_D480);
    let eight = platform::read_f32(0x807C_D484);
    let minus_eight = platform::read_f32(0x807C_D488);
    let thirteen = platform::read_f32(0x807C_D498);
    let inverse256 = platform::read_f32(0x807C_D49C);

    // observed: a 3-float position and a 3-halfword angle triple are passed to
    // 0x80064AF0 in place; the helper rewrites both in the stack slots.
    let mut position = [
        platform::read_f32(this + 0xAC),
        platform::read_f32(this + 0xB0),
        platform::read_f32(this + 0xB4),
    ];
    let mut angle3 = [
        platform::read_u16(this + 0x100),
        platform::read_u16(this + 0x102),
        platform::read_u16(this + 0x104),
    ];
    abi_call3!(
        0x8006_4AF0,
        position.as_mut_ptr() as usize,
        angle3.as_mut_ptr() as usize,
        1
    );

    let mut matrix = [0u32; 12];
    let mut offset = [0u32; 12];
    let out = matrix.as_mut_ptr() as u32;
    call_f32x3_u32(0x801C_0BD0, position[0], position[1], position[2], out);
    // observed: each setter takes a pointer to one halfword.
    let mut half = [0u16; 1];
    half[0] = angle3[1];
    abi_call2!(0x8016_EDD0, out, half.as_mut_ptr() as usize);
    half[0] = angle3[0];
    abi_call2!(0x8016_ECB0, out, half.as_mut_ptr() as usize);

    call_f32x3_u32(
        0x801C_0BD0,
        zero,
        eight,
        zero,
        offset.as_mut_ptr() as u32,
    );
    abi_call3!(
        0x801C_0540,
        out,
        offset.as_mut_ptr() as u32,
        out
    );
    half[0] = angle3[2];
    abi_call2!(0x8016_EEF0, out, half.as_mut_ptr() as usize);
    call_f32x3_u32(
        0x801C_0BD0,
        zero,
        minus_eight,
        zero,
        offset.as_mut_ptr() as u32,
    );
    abi_call3!(
        0x801C_0540,
        out,
        offset.as_mut_ptr() as u32,
        out
    );

    abi_call2!(0x8016_A170, this + 0x3F0, out);
    abi_call2!(0x8016_A150, this + 0x3F0, this + 0xDC);
    abi_call2!(0x8016_A1A0, this + 0x3F0, 0);
    fn_8072c180(this);

    // observed: the second mount uses the radial offset (0.0, 13.0).
    let mut radial = [zero, thirteen, zero];
    let angle = if platform::read_u32(this + 0x4D0) == 0 {
        platform::read_u16(this + 0x4A0) as i16 as i32
    } else {
        (platform::read_u16(this + 0x4A0) as i16 as i32) - 0x8000
    } as u16;
    let radians = angle as f32 * inverse256;
    let cosine = f32_of_f32(0x8023_7C40, radians);
    let sine = f32_of_f32(0x8023_7BD0, radians);
    let offset_x = radial[0];
    let offset_y = radial[1];
    radial[0] = platform::read_f32(this + 0x4A8) + (offset_x * cosine - offset_y * sine);
    radial[1] = platform::read_f32(this + 0x4AC) + (offset_x * sine + offset_y * cosine);
    radial[2] = platform::read_f32(this + 0x4B0);
    abi_call3!(
        0x8006_4AF0,
        radial.as_mut_ptr() as usize,
        0,
        1
    );
    call_f32x3_u32(
        0x801C_0BD0,
        radial[0],
        radial[1],
        radial[2],
        out,
    );
    half[0] = angle;
    abi_call2!(0x8016_EEF0, out, half.as_mut_ptr() as usize);
    abi_call2!(0x8016_A170, this + 0x430, out);
    abi_call2!(0x8016_A150, this + 0x430, this + 0x4C0);
    abi_call2!(0x8016_A1A0, this + 0x430, 0);
    fn_8072bea0(this);
}

/// Rebuilds the per-record radial motion offsets for the current angle.
///
/// Rotates the `+0x4A0` angle (flipped by `0x8000` when `+0x4D0` is set), then
/// fills `+0x4CC` records of stride `0xA4` with the position offset of a ring
/// whose radius starts at `19.0` and grows by an eight-entry table step.
///
/// # Original
/// - Ghidra: `FUN_8072c000` at `0x8072C000` (372 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8072c000_FUN_8072c000.c`
///
/// # Arguments
/// * `this` - object with `+0xAC`/`+0xB0` position, `+0x4A0` angle,
///   `+0x4A8`/`+0x4AC` offsets, `+0x4CC` record count and `+0x4D0` half-turn flag.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x4F0`/`+0x4F4` of every record and calls the cosine/sine helpers.
///
/// # Safety
/// `this` must have `+0x4CC` valid records of `0xA4` bytes from `this`.
///
/// # Confidence
/// medium - both `qr3` loads are u16 (GQR3 = 0x00050005); the eight-entry table
/// at `0x807CD4C0` is read as signed integers (its last word is the `19.0`
/// float cell, transcribed literally).
pub unsafe fn fn_8072c000(this: usize) {
    let zero = platform::read_f32(0x807C_D480);
    let mut radius = platform::read_f32(0x807C_D4DC);
    let angle = if platform::read_u32(this + 0x4D0) == 0 {
        platform::read_u16(this + 0x4A0) as i16 as i32
    } else {
        (platform::read_u16(this + 0x4A0) as i16 as i32) - 0x8000
    } as u16;
    let radians = angle as f32 * platform::read_f32(0x807C_D49C);
    let cosine = f32_of_f32(0x8023_7C40, radians);
    let sine = f32_of_f32(0x8023_7BD0, radians);

    // observed: `lwzx` + `xoris 0x8000` + the 2^52 double is the signed-int
    // to float ladder; the index is `(this[4] & 7)` and bit 8 of `this[4]` adds
    // the 0.25 cell at 0x807CD4E0.
    let mut step =
        platform::read_u32(0x807C_D4C0 + (platform::read_u32(this + 4) & 7) as usize * 4) as i32
            as f32;
    if (platform::read_u32(this + 4) >> 8) & 1 != 0 {
        step += platform::read_f32(0x807C_D4E0);
    }

    let position_x = platform::read_f32(this + 0x4A8);
    let position_y = platform::read_f32(this + 0x4AC);
    for record in 0..platform::read_u32(this + 0x4CC) as usize {
        let base = this + record * 0xA4;
        platform::write_f32(
            base + 0x4F0,
            (position_x + (zero * cosine - radius * sine)) - platform::read_f32(this + 0xAC),
        );
        platform::write_f32(
            base + 0x4F4,
            (position_y + (zero * sine + radius * cosine)) - platform::read_f32(this + 0xB0),
        );
        radius += step;
    }
}

/// Emits the four-arm burst effect and the four trailing particle records.
///
/// Picks a quarter-turn base from `+0x934`, walks four arms `0x4000` apart,
/// places each arm `16.0` from the `+0x8D4`/`0x8D8` centre and emits the
/// `0x15B` effect with an id taken from the shipped `3`/`5` cells. A second loop
/// spawns `"Wm_en_burst_ss"` for the slots selected by the `0x807CD608` mask
/// byte and stores that byte at `+0x954`.
///
/// # Original
/// - Ghidra: `FUN_8072e520` at `0x8072E520` (644 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8072e520_FUN_8072e520.c`
///
/// # Arguments
/// * `this` - object with `+0x934` angle, `+0x92C` mode, `+0x8D4`/`+0x8D8` arm
///   offsets, `+0x8E0` particle records (stride `0xC`) and `+0x954` output mask.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls `0x80064610`, `0x8006A4B0`, `0x80198C30` and `0x8016C890`; writes
/// `+0x954`.
///
/// # Safety
/// `this` must be a live emitter; `0x80429D60` must hold the `main.dol` effect
/// manager.
///
/// # Confidence
/// medium - both `qr3` loads are u16 (GQR3 = 0x00050005); the effect ids and the
/// mask table are read from the image, but their engine meaning is inferred.
pub unsafe fn fn_8072e520(this: usize) {
    // observed: the save helper 0x802DCD5C preserves r3; r25 = this.
    let inverse256 = platform::read_f32(0x807C_D610);
    let sixteen = platform::read_f32(0x807C_D614);
    let zero = platform::read_f32(0x807C_D5D0);

    let angle = platform::read_u16(this + 0x934) as i16;
    let mut arm_angle: u16 = 0;
    let mut quarter = false;
    if angle == 0x2000 || angle == 0x6000 || angle == -0x6000 || angle == -0x2000 {
        arm_angle = 0x2000;
        quarter = true;
    }

    let mut position = [0f32; 3];
    for index in 0..4usize {
        let radians = arm_angle as f32 * inverse256;
        let cosine = f32_of_f32(0x8023_7C40, radians);
        position[0] = platform::read_f32(this + 0x8D4) + sixteen * cosine;
        let sine = f32_of_f32(0x8023_7BD0, radians);
        position[1] = platform::read_f32(this + 0x8D8) + sixteen * sine;
        position[2] = zero;

        // observed: the emit gate depends on the quarter flag and on `+0x92C`;
        // `3056` = 0xBF0. The branches below are the stream's, not the prose's.
        let mode = platform::read_i32(this + 0x92C);
        let skip = if quarter {
            if mode == 0 {
                (2..4).contains(&index)
            } else {
                index < 2
            }
        } else if mode == 0 {
            index == 3
        } else {
            index == 1
        };

        if !skip {
            let id = if quarter {
                platform::read_u32(0x807C_D5F8)
            } else {
                platform::read_u32(0x807C_D5E8)
            };
            let mut record = [0u32; 2];
            abi_call5!(
                0x8006_4610,
                0x15B,
                (id << 4) | 0x200 | (platform::read_u32(this + 4) & 0x30_0000),
                position.as_mut_ptr() as usize,
                0,
                0
            );
            abi_call2!(
                0x8006_A4B0,
                record.as_mut_ptr() as usize,
                position.as_mut_ptr() as usize
            );
            abi_call4!(
                0x8019_8C30,
                platform::read_u32(0x8042_9D60),
                0x2A4,
                record.as_mut_ptr() as usize,
                0
            );
        }

        arm_angle = arm_angle.wrapping_add(0x4000);
    }

    // observed: the mask byte index is `(u16)+0x934 >> 13`.
    let index = (platform::read_u16(this + 0x934) >> 13) as usize;
    let mask = platform::read_u8(0x807C_D608 + index);
    let lifetime = platform::read_f32(0x807C_D618);
    let mut bit = 8u8;
    for slot in 0..4usize {
        if mask & bit != 0 {
            let record = this + 0x8E0 + slot * 0xC;
            let mut spawn = [
                platform::read_u32(record),
                platform::read_u32(record + 4),
                lifetime.to_bits(),
            ];
            abi_call5!(
                0x8016_C890,
                0x8080_CBE0,
                0,
                spawn.as_mut_ptr() as usize,
                0,
                0
            );
        }
        bit >>= 1;
    }
    platform::write_u8(this + 0x954, mask);
}

