    platform::write_u32(this + 0x120, platform::read_u32(this + 0x120) | 0x80);

    let phase = platform::read_u16(this + 0x504);
    let radians = phase as f32 * platform::read_f32(0x807C_AA00);
    platform::write_f32(this + 0x3D4, f32_of_f32(0x8023_7BD0, radians));
    platform::write_f32(this + 0x3D0, f32_of_f32(0x8023_7C40, radians));

    platform::write_f32(this + 0x10C, platform::read_f32(0x807C_AA0C));
    platform::write_u8(this + 0x50C, 1);
    platform::write_u8(this + 0x36D, 4);
