/// Installs the animated cell mode chosen by the current row.
///
/// # Original
/// - Ghidra: `FUN_80629460` at `0x80629460` (116 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80629460_FUN_80629460.c`
///
/// # Arguments
/// * `this` - board owner: cell table `+0xB4`, owner object `+0xE0`, row index
///   from [`fn_80628770`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Sets `owner+0x295 = 1`, reads the row's `+0x1D4` word and writes either
/// `owner+0x28C = 6` plus `owner+0x290 = row[0x1D0]`, or `owner+0x28C = 4`.
///
/// # Safety
/// `this+0xE0` must address the owner object and the row table must be valid.
///
/// # Confidence
/// medium - every read and store is literal; the roles of `+0x28C`/`+0x290` are
/// inferred from the two mutually exclusive values.
pub unsafe fn fn_80629460(this: usize) {
    let owner = platform::read_u32(this + 0xE0) as usize;
    platform::write_u8(owner + 0x295, 1);

    let row = fn_80628770(this) as u32;
    let entry = this + row.wrapping_mul(0x20) as usize;
    if platform::read_u32(entry + 0x1D4) == 2 {
        let owner = platform::read_u32(this + 0xE0) as usize;
        platform::write_u32(owner + 0x28C, 6);
        let owner = platform::read_u32(this + 0xE0) as usize;
        platform::write_u32(owner + 0x290, platform::read_u32(entry + 0x1D0));
    } else {
        let owner = platform::read_u32(this + 0xE0) as usize;
        platform::write_u32(owner + 0x28C, 4);
    }
}

