        let outside = platform::read_u8(actor + 0x38C) != 3
            || platform::read_u16(actor + 0x364) & 10 != 0
            || platform::read_f32(actor + 0xAC) < rect[0]
            || x_max < platform::read_f32(actor + 0xAC)
            || rect[1] < platform::read_f32(actor + 0xB0)
            || platform::read_f32(actor + 0xB0) < y_min;
        if !outside {
            return 0;
        }
        previous = actor;
