                let current = platform::read_f32(this + 0xB0);
                let direction = (platform::read_f32(this + 0x630) < current) as usize;
                let step = platform::read_f32(0x807C_B4B0 + direction * 4);
                let angle = platform::read_u16(0x807C_B4B8 + direction * 2) as i16;
                platform::write_f32(this + 0xEC, step);
                platform::write_f32(this + 0xB0, current + step);
                platform::write_u16(
                    this + 0x656,
                    (platform::read_u16(this + 0x656) as i16)
                        .wrapping_add(angle) as u16,
                );
                fn_806d0510(this, 0x40, 0x180);
                let mut position = [0u32; 3];
                abi_call2!(0x8006_A4B0, position.as_mut_ptr(), this + 0xAC);
                abi_call5!(
                    0x8019_9390,
                    platform::read_u32(0x8042_9D60),
                    0x2B0,
                    platform::read_u32(this),
                    position.as_mut_ptr(),
                    0
                );
                let reached = if direction == 0 {
                    platform::read_f32(this + 0x630) < platform::read_f32(this + 0xB0)
                } else {
                    platform::read_f32(this + 0xB0) < platform::read_f32(this + 0x630)
                };
                if reached {
                    platform::write_f32(this + 0xB0, platform::read_f32(this + 0x630));
                    platform::write_u8(this + 0x65C, 4);
                    platform::write_u32(this + 0x640, 0);
                    platform::write_u16(this + 0x5D8, platform::read_u16(this + 0x5E6));
                }
