        platform::write_u32(this + 0x628, 10);
        platform::write_u8(this + 0x65D, 1);
        platform::write_u8(this + 0x65C, 0);
        platform::write_u16(this + 0x65A, 0x1E);

        // observed: the two negations leave the unsigned 16-bit pose value that
        // the `0x43300000` conversion turns into `v`; 1280.0 is `0x500`.
        let inner = fn_806cfe60(this) as u16 as i16;
        let wrapped = fn_806cff20(this, (0i32 - inner as i32) as u32) as u16 as i16;
        let v = (0i32 - wrapped as i32) as u32;
