                platform::write_i32(this + 0x7B0, next);
                let step = platform::read_u32(this + 0x7B4) as u16 as i16;
                let angle = platform::read_u16(this + 0x102) as i16;
                platform::write_u16(this + 0x102, angle.wrapping_add(step) as u16);
