/// Builds the seven-bit presence/layer mask and refreshes the animation slot.
///
/// The mask always has bit 0 ("unused marker") or bits 1/2/3 from the height,
/// rider and anchor tests. A full `0x0F` mask drives `0x800E41C0` and retires
/// the actor when the layer nibble is zero; any other mask only refreshes the
/// animation slot when the layer nibble is two.
///
/// # Original
/// - Ghidra: `FUN_8067e640` at `0x8067E640` (1,160 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8067e640_FUN_8067e640.c`
///
/// # Arguments
/// * `this` - actor; flags word `+0x3E0`, id byte `+0x3EC`, marker bytes
///   `+0x3ED..+0x3F1`, layer words `+0x3D0`/`+0x3D4`.
///
/// # Returns
/// Nothing; the mask never escapes the function.
///
/// # Side effects
/// Calls `0x800E41C0` with the two-word mask table and retires the actor through
/// `0x80162510` when block A agrees. No field of `this` is written.
///
/// # Safety
/// `this` must be live; `0x80429E98`, `0x8042A1C8`, `0x8042A078`, `0x80429CA8`
/// and `0x80429CA0` must be initialised.
///
/// # Confidence
/// medium - every mask bit, comparison and call argument is literal. The layer
/// nibble and the "active" bit are read from `+0x3E0`, and the two mask words
/// from `+0x3D0`/`+0x3D4`, which differs from the field map in
/// `docs/SPEC_WAVE142_BASES.md`; the raw words confirm the export.
pub unsafe fn fn_8067e640(this: usize) {
    let mut mask = 0u32;
    let mut riders = 0u32;
    let mut heights = [0u8; 56]; // observed: `undefined1 auStack_38[56]`

    if platform::read_u8(this + 0x3ED) as i8 == -1 {
        mask = 1;
    } else {
        let index = platform::read_u8(platform::read_u32(0x8042_A1C8) as usize + 0x120E) as usize;
        let mut entry = platform::read_u32(0x8042_9E98) as usize + index * 0x3B0;
        if platform::read_u32(entry + 0x2C) == 0 {
            entry = 0;
        }
        abi_call3!(
            0x8008_E890,
            entry,
            platform::read_u8(this + 0x3ED) as i8 as i32,
            heights.as_mut_ptr()
        );
        for slot in 0..4u32 {
            let player = abi_call1!(0x8005_F900, slot);
            if player != 0 {
                let vtable = platform::read_u32(player as usize + 0x60) as usize;
                let info = abi_call1!(ptr_at(vtable + 0x6C), player) as usize;
                let bit = platform::read_u8(info) as u32;
                if platform::read_u32(0x8042_9CA8) & 1u32.wrapping_shl(bit) != 0 {
                    let result = abi_call3!(
                        0x8067_DCF0,
                        this,
                        player,
                        heights.as_mut_ptr()
                    );
                    if result & 0xFF != 0 {
                        mask |= result;
                        riders |= 1u32.wrapping_shl(slot);
                    }
                }
            }
        }
    }

    if platform::read_u8(this + 0x3EE) == 0xFF {
        mask |= 2;
    } else if abi_call1!(0x8067_E500, this) != 0 {
        mask |= 2;
    }

    if platform::read_u8(this + 0x3EF) == 0 {
        mask |= 4;
    } else if platform::read_u8(this + 0x3F1) == 0 {
        if platform::read_i32(0x8042_9CA0) < 2 {
            let probe = abi_call1!(0x8067_DC50, this) as usize;
            let index = platform::read_u8(this + 0x3EF);
            if index < 7 {
                if platform::read_u16(0x807C_9610 + (index as usize - 1) * 2) as u32
                    == platform::read_u32(probe + 0x1090)
                {
                    mask |= 4;
                }
            } else {
                let vtable = platform::read_u32(probe + 0x60) as usize;
                if abi_call1!(ptr_at(vtable + 0x3D4), probe) != 0 {
                    mask |= 4;
                }
            }
        } else {
            for slot in 0..4u32 {
                let player = abi_call1!(0x8005_F900, slot);
                if player != 0
                    && platform::read_u16(
                        0x807C_960E + platform::read_u8(this + 0x3EF) as usize * 2,
                    ) as u32
                        == platform::read_u32(player as usize + 0x1090)
                {
                    mask |= 4;
                }
            }
        }
    } else {
        let wanted = platform::read_u8(this + 0x3F1).wrapping_sub(1);
        if platform::read_i32(0x8042_9CA0) < 2 {
            let probe = abi_call1!(0x8067_DC50, this) as usize;
            if platform::read_u8(this + 0x3EF) < 7 {
                let vtable = platform::read_u32(probe + 0x60) as usize;
                let info = abi_call1!(ptr_at(vtable + 0x6C), probe) as usize;
                if wanted == platform::read_u8(info)
                    && platform::read_u16(
                        0x807C_9610
                            + (platform::read_u8(this + 0x3EF) as usize - 1) * 2,
                    ) as u32
                        == platform::read_u32(probe + 0x1090)
                {
                    mask |= 4;
                }
            } else {
                let vtable = platform::read_u32(probe + 0x60) as usize;
                if abi_call1!(ptr_at(vtable + 0x3D4), probe) != 0 {
                    mask |= 4;
                }
            }
        } else {
            for slot in 0..4u32 {
                let player = abi_call1!(0x8005_F900, slot);
                if player != 0 {
                    let vtable = platform::read_u32(player as usize + 0x60) as usize;
                    let info = abi_call1!(ptr_at(vtable + 0x6C), player) as usize;
                    if wanted == platform::read_u8(info)
                        && platform::read_u16(
                            0x807C_960E
                                + platform::read_u8(this + 0x3EF) as usize * 2,
                        ) as u32
                            == platform::read_u32(player as usize + 0x1090)
                    {
                        mask |= 4;
                    }
                }
            }
        }
    }

    if platform::read_u8(this + 0x3F0) == 0 {
        mask |= 8;
    } else if mask & 1 != 0 {
        for slot in 0..4u32 {
            if riders & 1u32.wrapping_shl(slot) != 0 {
                let player = abi_call1!(0x8005_F900, slot);
                if player != 0 {
                    let result = abi_call3!(
                        0x8067_DD60,
                        this,
                        player,
                        platform::read_u8(this + 0x3F0)
                    );
                    mask = (mask | result) & 0xFF;
                }
            }
        }
    }

    mask &= 0xFF;
    let flags = platform::read_u32(this + 0x3E0);
    let layer = (flags >> 4) & 0xF;
    let table = platform::read_u32(0x8042_A078) as usize;
    let first = platform::read_u32(this + 0x3D0) & platform::read_u32(table);
    let second = platform::read_u32(this + 0x3D4) & platform::read_u32(table + 4);

    if mask == 0x0F {
        let mut done = false;
        if flags & 1 == 0 {
            if first == 0 && second == 0 {
                call_u32x9(
                    0x800E_41C0,
                    table as u32,
                    platform::read_u8(this + 0x3EC) as u32,
                    0,
                    1,
                    0,
                    0,
                    0,
                    0,
                    0,
                );
                done = true;
            }
        } else if first != 0 || second != 0 {
            call_u32x9(
                0x800E_41C0,
                table as u32,
                platform::read_u8(this + 0x3EC) as u32,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
            );
            done = true;
        }
        if layer == 0 && done {
            abi_call1!(0x8016_2510, this);
        }
    } else if layer == 2 {
        if flags & 1 == 0 {
            if first != 0 || second != 0 {
                call_u32x9(
                    0x800E_41C0,
                    table as u32,
                    platform::read_u8(this + 0x3EC) as u32,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                );
            }
        } else if first == 0 && second == 0 {
            call_u32x9(
                0x800E_41C0,
                table as u32,
                platform::read_u8(this + 0x3EC) as u32,
                0,
                1,
                0,
                0,
                0,
                0,
                0,
            );
        }
    }
}

/// Binds the twenty-pane `dMultiCourseSelectContents_c` layout once, then shows
