/// # Confidence
/// medium - the gate, the two arguments of `0x80166EF0` and the vtable slot are
/// literal; the animation name is a runtime-built BSS string.
pub unsafe fn fn_8064ac90(this: usize) {
    if platform::read_u32(this + 0x764) != 0 {
        return;
    }
    call_f32_u32x2(
        0x8016_6EF0,
        platform::read_f32(0x807C_8588), // 0.0
        (this + 0x704) as u32,
        0u32,
    );
    let vtable = platform::read_u32(this + 0x60) as usize;
    abi_call2!(ptr_at(vtable + 0xD4), this, 0x8082_7F90u32);
}

