/// # Confidence
/// high - all 220 words decode; `unaff_GQR0`/`ldexpf` in the export are the four
/// `psq_st f28..f31,qr0,0` prologue spills and contain no arithmetic.
pub unsafe fn fn_806e4f30(this: usize) {
    let clip = this + 0x3FC;
    // observed: 0x80166380/0x80166360 return the clip start/end time in f1; the
    // export's `double` is the missing-prototype rendering.
    let start = call_u32x2_f32(0x8016_6380, clip as u32, 0u32);
    let end = call_u32x2_f32(0x8016_6360, clip as u32, 0u32);
    let span = end - start;
    // observed: the `2^52` ladder at 0x807CBCB0 converts `+0x48C` as unsigned.
    let counter = platform::read_u32(this + 0x48C) as f32;
    let state = platform::read_u8(this + 0x588);

    // observed: `(*(*(this+0x428)+0x28))(this+0x428)` and then slot `+0x14`
    // with the `main.dol` BSS type tag at 0x803717E0.
    let animator = this + 0x428;
    let motion =
        abi_call1!(ptr_at(platform::read_u32(animator) as usize + 0x28), animator) as usize;
    let has = abi_call2!(
        ptr_at(platform::read_u32(motion) as usize + 0x14),
        motion,
        0x8037_17E0u32
    ) != 0;

    let set_time = |value: f32| call_u32x2_f32_arg(0x8016_62F0, clip as u32, 0u32, value);

    if state == 1 {
        if has && platform::read_u8(this + 0x49C) == 0 && counter < span {
            abi_call2!(0x806E_4E90, this, 3u32);
            set_time(start + counter);
            platform::write_u8(this + 0x588, 2);
        }
    } else if state == 2 {
        // observed: `counter <= 35.0` is the `fcmpo` + `cror 2,0,2` idiom.
        if has && platform::read_u8(this + 0x49C) == 1 && counter <= 35.0 {
            abi_call2!(0x806E_4E90, this, 1u32);
            set_time((35.0 - counter) + start);
            platform::write_u8(this + 0x588, 1);
        }
    } else if has {
        if platform::read_u8(this + 0x49C) == 1 {
            if counter <= 35.0 {
                abi_call2!(0x806E_4E90, this, 1u32);
                set_time((35.0 - counter) + start);
                platform::write_u8(this + 0x588, 1);
            } else {
                abi_call2!(0x806E_4E90, this, 3u32);
                set_time(start);
                platform::write_u8(this + 0x588, 2);
            }
        } else if counter < span {
            abi_call2!(0x806E_4E90, this, 3u32);
            set_time(counter + start);
            platform::write_u8(this + 0x588, 2);
        } else {
            abi_call2!(0x806E_4E90, this, 1u32);
            set_time(end);
            platform::write_u8(this + 0x588, 1);
        }
    } else if platform::read_u8(this + 0x49C) == 1 {
        abi_call2!(0x806E_4E90, this, 3u32);
        set_time(start);
        platform::write_u8(this + 0x588, 2);
    } else {
        abi_call2!(0x806E_4E90, this, 1u32);
        set_time(end);
        platform::write_u8(this + 0x588, 1);
    }
}

/// Emits the world-map enemy's four-direction burst pattern.
///
/// Probes four compass directions at radius `24.0` around the actor's feet,
/// skips the actor's own facing index, spawns `Wm_en_burst_s`-family bursts at up
/// to three of the four points, records a direction bitmask at `+0xA05`, then
/// spawns up to three more bursts at three fixed offsets selected by that mask.
///
/// # Original
/// - Ghidra: `FUN_807318f0` at `0x807318F0` (876 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/807318f0_FUN_807318f0.c`
///
/// # Arguments
/// * `this` - world-map enemy; probe centre `+0x978`/`+0x97C`, extra burst
///   coordinates `+0x984..+0x9A0`, mode `+0x9CC`, angle `+0x9D4` (`i16`).
///
/// # Returns
/// Nothing. The export's `void` is the `_savegpr_20` artefact; `r3` survives.
///
/// # Side effects
/// Writes `+0xA05` and submits effect records through `0x80064610`,
/// `0x8006A4B0`, `0x80198C30` and `0x8016C890`.
///
/// # Safety
/// `this` must be live through `+0xA05`; the effect manager at `0x80429D60` must
/// be mapped.
///
/// # Confidence
/// high - `qr3` is pinned to `0x00050005`, the five tables are read out of the
/// image, and every call argument register is written before its `bl`. The
/// first `0x80064610` argument is the literal `0x15B` (the spec's
/// `id + 0x15B` does not appear in the stream).
pub unsafe fn fn_807318f0(this: usize) {
    // observed: 0x807CD750 = [5, 4, 6, 7] (diagonal), 0x807CD760 = [3, 1, 2, 0].
    const IDS_DIAGONAL: [u32; 4] = [5, 4, 6, 7];
    const IDS_PLAIN: [u32; 4] = [3, 1, 2, 0];
    // observed: 0x807CD770 = 07 01 0D 09 0F 0A 0E 02.
    const MASK_BYTES: [u8; 8] = [0x07, 0x01, 0x0D, 0x09, 0x0F, 0x0A, 0x0E, 0x02];

    let radius = platform::read_f32(0x807C_D73C); // 24.0
    let scale = platform::read_f32(0x807C_D740); // 1/256
    let angle = platform::read_u16(this + 0x9D4) as i16;
    let mut bump = 0u32;
    let mut diagonal = false;
    if matches!(angle, 0x2000 | 0x6000 | -0x6000 | -0x2000) {
        bump = 0x2000;
        diagonal = true;
    }

    let mode = platform::read_u32(this + 0x9CC);
    let skip: u32 = if mode == 0 {
        match angle {
            i16::MIN | 0x6000 => 3,
            -0x4000 | -0x6000 => 2,
            0 | -0x2000 => 1,
            _ => 0,
        }
    } else {
        match angle {
            i16::MIN | 0x6000 => 1,
            0x2000 | 0x4000 => 2,
            0 | -0x2000 => 3,
            _ => 0,
        }
    };

    for i in 0..4usize {
        if skip == i as u32 {
            bump = bump.wrapping_add(0x4000);
            continue;
        }
        // observed: two `psq_l ...,qr3,W=1` loads of the low half of `bump`,
        // i.e. plain `(f32)(u16)` under GQR3 = 0x00050005.
        let theta = (bump as u16) as f32 * scale;
        let cos = f32_of_f32(0x8023_7C40, theta);
        let sin = f32_of_f32(0x8023_7BD0, theta);
        let point = [
            platform::read_f32(this + 0x978) + radius * cos,
            platform::read_f32(this + 0x97C) + radius * sin,
            platform::read_f32(0x807C_D778), // -50.0
        ];

        let suppress = if diagonal {
            if mode == 0 {
                i >= 2
            } else {
                i < 2
            }
        } else if mode == 0 {
            i == 3
        } else {
            i == 1
        };
        let id = if diagonal {
            IDS_DIAGONAL[i]
        } else {
            IDS_PLAIN[i]
        };
        if !suppress {
            let base = platform::read_u32(this + 4);
            let attr = (id << 4) | 0x301 | (base & 0x300000);
            abi_call5!(
                0x8006_4610,
                0x15Bu32,
                attr,
                point.as_ptr() as u32,
                0u32,
                0u32
            );
            let mut screen = [0u32; 3];
            abi_call2!(
                0x8006_A4B0,
                screen.as_mut_ptr() as u32,
                point.as_ptr() as u32
            );
            abi_call4!(
                0x8019_8C30,
                platform::read_u32(0x8042_9D60),
                0x2A5u32,
                screen.as_ptr() as u32,
                0u32
            );
        }
        bump = bump.wrapping_add(0x4000);
    }

    let index = ((platform::read_u16(this + 0x9D4) >> 13) & 7) as usize;
    let mask = MASK_BYTES[index];
    platform::write_u8(this + 0xA05, mask);

    // observed: three fixed extra bursts at z = 5500.0, gated by mask bits 8/2/1.
    let z = platform::read_f32(0x807C_D77C);
    if (mask & 8) != 0 {
        let point = [
            platform::read_f32(this + 0x984),
            platform::read_f32(this + 0x988),
            z,
        ];
        abi_call5!(
            0x8016_C890,
            0x8080_D0E8u32, // "Wm_en_burst_s"
            0u32,
            point.as_ptr() as u32,
            0u32,
            0u32
        );
    }
    if (mask & 2) != 0 {
        let point = [
            platform::read_f32(this + 0x990),
            platform::read_f32(this + 0x994),
            z,
        ];
        abi_call5!(
            0x8016_C890,
            0x8080_D0E8u32,
            0u32,
            point.as_ptr() as u32,
            0u32,
            0u32
        );
    }
    if (mask & 1) != 0 {
        let point = [
            platform::read_f32(this + 0x99C),
            platform::read_f32(this + 0x9A0),
            z,
        ];
        abi_call5!(
            0x8016_C890,
            0x8080_D0E8u32,
            0u32,
            point.as_ptr() as u32,
            0u32,
            0u32
        );
    }
}

/// Initialises the moving-collision actor: mode, offset transform, collision and
/// hitbox block.
///
/// Selects a mode from two character predicates plus bit `0x10` of the
/// `0x80429F80` flags, writes the two mode setters, offsets the transform
/// (`+176`, `-72`, scale `1.25`), publishes two global timing floats, installs the
/// collision descriptor and three 12.20 motion records, and fills the large
/// hitbox/state block at `+0xD4C..+0xDDC`.
///
/// # Original
/// - Ghidra: `FUN_80699380` at `0x80699380` (868 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80699380_FUN_80699380.c`
///
/// # Arguments
/// * `this` - actor; position `+0xAC..+0xB4`, saved pose `+0x750..+0x758`,
///   collision area `+0x148`, record container `+0x1EC`, callback set `+0x654`.
///
/// # Returns
/// `1`. The export's `void` is the `_savegpr_27` artefact.
///
/// # Side effects
/// Calls virtual slots `+0x360`/`+0x364` and `+0x314` four times, writes
/// `0x807F1410`/`0x807F1414`, installs the `0x807F1408` descriptor, registers the
/// frame callback and hands three motion records to `0x8006D090`.
///
/// # Safety
/// `this` must be a live actor with a vtable at `+0x60`; the `main.dol` BSS
/// cells `0x80429F80` and `0x8042C1A0` must be mapped.
///
/// # Confidence
/// medium - every store and fixed-point mask is an immediate; `0x800A3430` and
/// `0x800FAE40` live outside this REL and the `0x8042C1A0` table cannot be
/// checked here. The export also copies `+0x750..+0x758` to `+0x768..+0x770`,
/// which the wave-146 prose omitted.
pub unsafe fn fn_80699380(this: usize) -> u32 {
    platform::call0(0x800A_3430);
    let mut flag = 0u32;
    if abi_call2!(0x800F_AE40, 3u32, 0x25u32) != 0
        || abi_call2!(0x800F_AE40, 5u32, 0x25u32) != 0
    {
        flag = 1;
    }
    // observed: the flag read is unconditional (it follows the join label).
    if (platform::read_u32(0x8042_9F80) & 0x10) != 0 {
        flag = 1;
    }
    actor_method1(this, 0x360, flag);
    actor_method1(this, 0x364, 0);

    // observed: 0x807CA084 = 176.0, 0x807CA088 = -72.0, 0x807CA080 = 112.0.
    let x = platform::read_f32(this + 0xAC);
    let y = platform::read_f32(this + 0xB0);
    let z = platform::read_f32(this + 0xB4);
    platform::write_f32(this + 0x750, x);
    platform::write_f32(this + 0x754, y);
    platform::write_f32(this + 0x758, z);
    platform::write_f32(this + 0xD50, y - 112.0);
    platform::write_f32(this + 0xAC, x + 176.0);
    platform::write_f32(this + 0xB0, y - 72.0);
    let scale = platform::read_f32(0x807F_1344); // 1.25
    platform::write_f32(this + 0xDC, scale);
    platform::write_f32(this + 0xE0, scale);
    platform::write_f32(this + 0xE4, scale);

    // observed: two slot `+0x314` results become the published timing floats.
    platform::write_f32(0x807F_1410, actor_method0_f32(this, 0x314));
    platform::write_f32(0x807F_1414, actor_method0_f32(this, 0x314));

    abi_call3!(0x8008_C3E0, this + 0x148, this, 0x807F_1408u32);
    platform::write_u8(this + 0x1E6, 1);
    abi_call1!(0x8008_C330, this + 0x148);

    // observed: 0x807CA090 = 0.85, 0x807CA08C = 0.0.
    let rate = platform::read_f32(0x807C_A090) * actor_method0_f32(this, 0x314);
    call_f32x3_u32x7(
        0x8007_FB80,
        platform::read_f32(0x807C_A08C),
        platform::read_f32(0x807C_A08C),
        rate,
        (this + 0x654) as u32,
        this as u32,
        0u32,
        0u32,
        0u32,
        1u32,
        platform::read_u8(this + 0x38F) as u32,
    );
    abi_call1!(0x8007_F900, this + 0x654);

    // observed: three 12.20 records; `fctiwz` truncates, `<<12` drops the
    // fractional bits exactly like the `& 0xFFFFF000` masks.
    platform::write_u32(this + 0xD54, 0);
    platform::write_u32(this + 0xD58, 0);
    let v1 = actor_method0_f32(this, 0x314) as i32;
    platform::write_u32(this + 0xD60, 0);
    platform::write_u32(this + 0xD64, 0);
    platform::write_u32(this + 0xD5C, (v1 << 12) as u32);
    let v2 = actor_method0_f32(this, 0x314) as i32;
    platform::write_u32(this + 0xD6C, 0);
    platform::write_u32(this + 0xD68, (v2 * -0x1000) as u32);
    let v3 = actor_method0_f32(this, 0x314) as i32;
    platform::write_u32(this + 0xD74, 0);
    platform::write_u32(this + 0xD70, (v3 << 12) as u32);
    abi_call5!(
        0x8006_D090,
        this + 0x1EC,
        this,
        this + 0xD60,
        this + 0xD54,
        this + 0xD6C
    );

    // observed: 0x807CA094 = 16.0; 0x807F1364/68/6C/70 = 8.0/4.0/6.0/-7.0.
    let unit = platform::read_f32(0x807C_A094);
    let wide = unit * platform::read_f32(0x807F_1364);
    let mid = unit * platform::read_f32(0x807F_1368);
    let narrow = unit * platform::read_f32(0x807F_136C);
    let down = unit * platform::read_f32(0x807F_1370);
    let saved_x = platform::read_f32(this + 0x750);
    platform::write_f32(this + 0x768, saved_x);
    platform::write_f32(this + 0x76C, platform::read_f32(this + 0x754));
    platform::write_f32(this + 0x770, platform::read_f32(this + 0x758));
    platform::write_f32(this + 0xD98, saved_x - wide);
    platform::write_f32(this + 0xD94, saved_x + wide);
    platform::write_f32(this + 0xDA0, saved_x - mid);
    platform::write_f32(this + 0xD9C, saved_x + mid);
    platform::write_f32(this + 0xDA8, saved_x - narrow);
    platform::write_f32(this + 0xDA4, saved_x + narrow);
    platform::write_f32(this + 0xD90, platform::read_f32(this + 0x754) + down);

    platform::write_u32(this + 0xD7C, 120);
    platform::write_u32(this + 0xD80, 40);
    platform::write_u32(this + 0xD84, 0);
    platform::write_u32(this + 0x748, 0);
    // observed: 0x8042C1A0 is a `main.dol` BSS byte table; 0x807F1354 = 4096.
    let index = platform::read_u8(this + 0x348) as usize;
    let angle = (platform::read_u8(0x8042_C1A0 + index) as i8 as i32) * 4096;
    platform::write_u16(this + 0xD78, angle as u16);
    platform::write_u32(this + 0xD8C, 0);
    platform::write_u32(this + 0xD88, 0);
    platform::write_u32(this + 0xDAC, 0);
    platform::write_u32(this + 0xDB0, 0);
    platform::write_u32(this + 0xDB4, 0);
    platform::write_u32(this + 0xDB8, 0);
    platform::write_u32(this + 0xD4C, 0);
    platform::write_u32(this + 0xDBC, 0);
    let zero = platform::read_f32(0x807C_A08C);
    platform::write_f32(this + 0xDC8, zero);
    platform::write_f32(this + 0xDC4, zero);
    platform::write_f32(this + 0xDC0, zero);
    platform::write_f32(this + 0xDDC, platform::read_f32(0x807C_A098)); // 1.0
    platform::write_u32(this + 0xDCC, 1);
    platform::write_u32(this + 0xDD0, 0xFFFF_FFFF);
    platform::write_u32(this + 0xDD4, 0);
    platform::write_u8(this + 0xDD8, 1);
    1
}

/// Calls a target with two `u32` arguments and returns a `f64`.
///
/// # Original
/// Host-side ABI wrapper for `0x801C1650`, which the export declares `void`
/// because the REL has no prototype; the squared distance is returned in `f1`.
///
/// # Safety
/// `addr` must point to a function with this ABI.
///
/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn call_u32x2_f64(addr: usize, a: u32, b: u32) -> f64 {
    let function: extern "C" fn(u32, u32) -> f64 = core::mem::transmute(addr);
    function(a, b)
}

/// Calls a target that takes one `f64` and returns `f64`.
///
/// # Original
/// Host-side ABI wrapper for `0x802BE470`'s argument/return register pair when
/// the caller passes a true double (the `0x801C1650` squared distance).
///
/// # Safety
/// `addr` must point to a function with this ABI.
///
/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn call_f64_f64(addr: usize, a: f64) -> f64 {
    let function: extern "C" fn(f64) -> f64 = core::mem::transmute(addr);
    function(a)
}

/// Calls the virtual slot at `obj + 0x60` and returns a double.
///
/// # Original
/// Host-side helper for the orientation slots `+0x34C..+0x358` in
/// `8069c2c0_FUN_8069c2c0.c`, whose `f1` results feed the two
/// `0x8015F470` double arguments.
///
/// # Safety
/// `obj + 0x60` must hold a vtable with a valid function at `slot`.
///
/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn actor_method0_f64(obj: usize, slot: usize) -> f64 {
    let vtable = platform::read_u32(obj + 0x60) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    let method: extern "C" fn(u32) -> f64 = core::mem::transmute(function);
    method(obj as u32)
}

/// Calls a target that takes two `u32` arguments and one `f32` argument.
///
/// # Original
/// Host-side ABI wrapper for `0x801662F0`, the clip-time setter. The raw call at
/// `0x806E5018..0x806E5020` loads `r3 = this + 0x3FC`, `r4 = 0` and `f1 = time`,
/// so the float is the *third* argument; the export prints it first only because
/// the REL has no prototype.
///
/// # Safety
/// `addr` must point to a function with this ABI.
///
/// # Confidence
/// high - mechanical wrapper, cross-checked against the call site.
#[inline]
unsafe fn call_u32x2_f32_arg(addr: usize, a: u32, b: u32, c: f32) -> u32 {
    let function: extern "C" fn(u32, u32, f32) -> u32 = core::mem::transmute(addr);
    function(a, b, c)
}

/// Drives the four-state vertical motion of the unnamed `0x1A500`-byte UI actor.
///
/// State 0 integrates a table-driven ease profile, state 1 waits for the
/// `0x806485C0` limit probe, state 2 runs a decaying sine, and state 3 holds then
/// restarts. The height is published to `+0x1A49C` and handed to `0x80648470`
/// every frame.
///
/// # Original
/// - Ghidra: `FUN_80648cb0` at `0x80648CB0` (860 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80648cb0_FUN_80648cb0.c`
///
/// # Arguments
/// * `this` - host object; the motion block is `this + 0x1A49C..+0x1A4F6` and the
///   base height is `+0xB0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the whole motion block and calls `0x80648470` with the published
/// height; state 2/3 read the sine helper `0x80237BD0`.
///
/// # Safety
/// `this` must be live through `+0x1A4F6`.
///
/// # Confidence
/// high - all 215 words decode, the 8-byte phase table `0x807C8518` and every
/// float are read out of the image, and both `qr3` loads are `(f32)(u16)` under
/// `GQR3 = 0x00050005`.
pub unsafe fn fn_80648cb0(this: usize) {
    let scale = platform::read_f32(0x807C_8510); // 1/256
    match platform::read_u16(this + 0x1A4E8) as i16 {
        0 => {
            let counter = platform::read_u16(this + 0x1A4EC);
            let index = (counter >> 5) as usize;
            // observed: 0x807C8518 = 01 01 FF FF 01 FF FF 01 (four s8 pairs).
            let a = platform::read_u8(0x807C_8518 + 2 * index) as i8 as f32;
            let b = platform::read_u8(0x807C_8519 + 2 * index) as i8 as f32;
            let velocity_scale = platform::read_f32(0x807C_8524); // 1/64
            let delta = platform::read_f32(this + 0x1A4B4) * velocity_scale * a;
            let velocity = platform::read_f32(this + 0x1A4CC) + delta;
            platform::write_f32(this + 0x1A4CC, velocity);

            let mut offset = velocity * b;
            if platform::read_u8(this + 0x1A4F6) != 0 {
                offset = -offset;
            }
            if index != 0 {
                offset *= platform::read_f32(0x807C_8484); // 0.5
            }
            let total = platform::read_f32(this + 0x1A4B8) + offset;
            platform::write_f32(this + 0x1A4B8, total);
            platform::write_f32(this + 0x1A49C, platform::read_f32(this + 0xB0) + total);
            abi_call1!(0x8064_8470, this);

            let next = counter.wrapping_sub(1);
            platform::write_u16(this + 0x1A4EC, next);
            if next == 0 {
                platform::write_u16(this + 0x1A4E8, 1);
            }
        }
        1 => {
            let limit = abi_call2!(0x8064_85C0, this, 1u32);
            if limit == 2 {
                platform::write_u8(this + 0x1A4F6, 0);
                platform::write_u16(this + 0x1A4EE, platform::read_u16(this + 0x1A4F2));
            } else if limit == 1 {
                platform::write_u8(this + 0x1A4F6, 1);
                platform::write_u16(this + 0x1A4EE, platform::read_u16(this + 0x1A4F0));
            }
            if limit != 0 {
                platform::write_f32(this + 0x1A4C8, platform::read_f32(0x807C_847C)); // 8.0
                platform::write_u16(this + 0x1A4E8, 2);
            }
            platform::write_f32(
                this + 0x1A49C,
                platform::read_f32(this + 0xB0) + platform::read_f32(this + 0x1A4B8),
            );
            abi_call1!(0x8064_8470, this);
        }
        2 => {
            // observed: `(counter & 0x7F) << 9` halfword, then `* 1/256`.
            let raw = (platform::read_u16(this + 0x1A4EC) << 9) as u16;
            let sine = f32_of_f32(0x8023_7BD0, raw as f32 * scale);
            let amplitude = platform::read_f32(this + 0x1A4C8);
            platform::write_f32(
                this + 0x1A49C,
                amplitude * sine
                    + platform::read_f32(this + 0xB0)
                    + platform::read_f32(this + 0x1A4B8),
            );
            abi_call1!(0x8064_8470, this);
            self::bob_update_counter(this);

            let decay = if platform::read_u16(this + 0x1A4F4) != 0 {
                platform::read_f32(0x807C_852C) // 0.125
            } else {
                platform::read_f32(0x807C_8528) // 0.03125
            };
            let next = amplitude - decay;
            platform::write_f32(this + 0x1A4C8, next);
            if next <= platform::read_f32(0x807C_8508) {
                // 3.0
                platform::write_u16(this + 0x1A4E8, 3);
            }
        }
        3 => {
            let hold = platform::read_u16(this + 0x1A4EE);
            if hold != 0 {
                platform::write_u16(this + 0x1A4EE, hold.wrapping_sub(1));
            } else if (platform::read_u16(this + 0x1A4EC) & 0x7F) == 0 {
                platform::write_f32(this + 0x1A4CC, platform::read_f32(this + 0x1A4B4));
                platform::write_u16(this + 0x1A4EC, 0x3F);
                platform::write_u16(this + 0x1A4E8, 0);
                return;
            }

            let raw = (platform::read_u16(this + 0x1A4EC) << 9) as u16;
            let sine = f32_of_f32(0x8023_7BD0, raw as f32 * scale);
            platform::write_f32(
                this + 0x1A49C,
                platform::read_f32(0x807C_8508) * sine
                    + platform::read_f32(this + 0xB0)
                    + platform::read_f32(this + 0x1A4B8),
            );
            abi_call1!(0x8064_8470, this);
            self::bob_update_counter(this);
        }
        _ => {
            // observed: no other state exists; the image falls through to the
            // epilogue unchanged.
        }
    }
}

/// Advances the `+0x1A4EC` phase counter of [`fn_80648cb0`] at the two sine
/// limits.
///
/// # Original
/// The identical `fcmpu`/`fcmpu` pair at `0x80648EA0`/`0x80648EC0` (state 2) and
/// `0x80648F8C`/`0x80648FAC` (state 3) in
/// `work/ghidra/rel-d_basesNP/export/80648cb0_FUN_80648cb0.c`.
///
/// # Safety
/// `this` must be live through `+0x1A4EC`.
///
/// # Confidence
/// high - both comparisons and both `& 0x7F` masks are literal.
#[inline]
unsafe fn bob_update_counter(this: usize) {
    let offset = platform::read_f32(this + 0x1A4B8);
    let counter = platform::read_u16(this + 0x1A4EC);
    if offset == platform::read_f32(0x807C_850C) {
        platform::write_u16(this + 0x1A4EC, counter.wrapping_sub(1) & 0x7F);
    } else if offset == platform::read_f32(this + 0x1A4B0) {
        platform::write_u16(this + 0x1A4EC, counter.wrapping_add(1) & 0x7F);
    }
}

/// Runs the carried-object's per-frame body (sibling of `0x8069B750`).
///
/// Ticks the `+0x544` rider sub-object, reads the model's two clip-idle
/// predicates, publishes the four sector/direction flags `+0xD30..+0xD34`, runs
/// the two-state `+0x360` launcher timer, then the orientation/collision tail.
///
/// # Original
/// - Ghidra: `FUN_8069c2c0` at `0x8069C2C0` (852 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8069c2c0_FUN_8069c2c0.c`
///
/// # Arguments
/// * `this` - carried object; vtable `+0x60`, position `+0xAC..+0xB4`, vertical
///   speed `+0xEC`, orientation holders `+0x114`/`+0x11C`, collision `+0x1EC`,
///   launch state `+0x360`, timer `+0x500`, rider `+0x544`, model `+0x5F8`.
///
/// # Returns
/// Nothing.
///
