/// Per-frame update of the `+0x544`-rider actor (sibling of [`fn_8069c2c0`]).
///
/// Ticks the rider sub-object, samples the player-like object behind class slot
/// `+0x2DC` through its `+0x5F8` clip interface, latches the five one-shot mode
/// bytes `+0xD30..+0xD34` from the geometry and the `+0xDCC` mode, runs the
/// two-state `+0x360` gate, then the shared orientation/animation tail.
///
/// # Original
/// - Ghidra: `FUN_8069be20` at `0x8069BE20` (844 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8069be20_FUN_8069be20.c`
///
/// # Arguments
/// * `this` - actor; vtable `+0x60`, position `+0xAC..+0xB4`, vertical speed
///   `+0xEC`, orientation holders `+0x114`/`+0x11C`, motion object `+0x1EC`,
///   geometry latch `+0x348`, gate state `+0x360`, timer `+0x500`, rider
///   `+0x544`, clip interface `+0x5F8`, threshold `+0x750`, message gate `+0x788`.
///
/// # Returns
/// Nothing; the epilogue restores `r29-r31`, `f31`, LR without touching `r3`.
///
/// # Side effects
/// Writes the five flag bytes, the `+0x348` latch, the `+0x500` timer and the
/// `+0x360` state; calls the twelve-slot per-frame tail and `0x80699E30`.
///
/// # Safety
/// `this` must be a live actor with a vtable at `+0x60`; the object returned by
/// slot `+0x2DC` and its `+0x5F8` interface must be live.
///
/// # Confidence
/// high - the shared tail matches the transcribed `0x8069B750`/`0x8069C2C0`
/// sequence call for call, and the only `qr0` use is the `f31` prologue spill.
pub unsafe fn fn_8069be20(this: usize) {
    // observed: 0x8069BE44 - tick the embedded rider sub-object.
    vmethod0(this + 0x544, 0x1C);

    let model = actor_method0(this, 0x2DC) as usize;
    let clip = platform::read_u32(model + 0x5F8) as usize;
    // observed: `lwz r12,0xC(vt); bcctr` only runs the `+0x10` predicate when
    // the first one returned zero.
    let both = vmethod0(clip, 0x0C) != 0 || vmethod0(clip, 0x10) != 0;
    if both {
        actor_method0(this, 0x380);
    }

    // observed: 0x8069BECC - `fcmpo [+0xAC],[+0x750]` then `bge` sets the byte.
    let above = platform::read_f32(this + 0xAC) >= platform::read_f32(this + 0x750);
    platform::write_u8(this + 0x348, above as u8);
    if above {
        platform::write_u8(this + 0xD31, 1);
    } else {
        platform::write_u8(this + 0xD32, 1);
    }

    match platform::read_i32(this + 0xDCC) {
        0 => platform::write_u8(this + 0xD33, 1),
        2 => platform::write_u8(this + 0xD34, 1),
        _ => {}
    }

    match platform::read_i32(this + 0x360) {
        1 => {
            if platform::read_u16(this + 0x500) == 0
                && abi_call1!(0x800A_4C10, this) != 0
            {
                platform::write_u8(this + 0xD30, 1);
                // observed: `lwz r4,[0x807F13D8]; sth r4,0x500` = 0x50.
                platform::write_u16(this + 0x500, platform::read_u16(0x807F_13D8));
                platform::write_u32(this + 0x360, 2);
            }
        }
        2 => {
            if actor_method0(this, 0x3A0) != 0 {
                platform::write_u32(this + 0x360, 1);
            }
        }
        _ => {}
    }

    // observed: the shared per-frame tail, in raw order.
    abi_call1!(0x800A_4E90, this);
    actor_method0(this, 0x33C);
    actor_method0(this, 0x340);
    abi_call1!(0x8006_CD90, this);
    abi_call1!(0x8006_CDE0, this);
    abi_call1!(0x8009_55F0, this);

    let first_a = actor_method0_f64(this, 0x350);
    let first_b = actor_method0_f64(this, 0x34C);
    call_f64x2_u32(0x8015_F470, first_b, first_a, (this + 0x114) as u32);
    let second_a = actor_method0_f64(this, 0x358);
    let second_b = actor_method0_f64(this, 0x354);
    call_f64x2_u32(0x8015_F470, second_b, second_a, (this + 0x11C) as u32);

    actor_method0(this, 0x344);
    if abi_call1!(0x8007_2BC0, this + 0x1EC) != 0
        && platform::read_f32(this + 0xEC) < 0.0
    {
        platform::write_f32(this + 0xEC, 0.0);
    }
    if abi_call2!(0x8006_EF40, this + 0x1EC, 0u32) != 0
        && 0.0 < platform::read_f32(this + 0xEC)
    {
        platform::write_f32(this + 0xEC, 0.0);
    }
    abi_call2!(0x8006_FA40, this + 0x1EC, 0u32);
    abi_call1!(0x8069_9E30, this);

    let selector = actor_method0(this, 0x374) as i16;
    abi_call2!(0x800A_4480, this, selector as i32);

    // observed: 0x8069C110 - the one-shot `+0xD4` message; the vtable pointer is
    // read from `this + 0x60` (actor layout, not the zero-offset vmethod helper)
    // and the second argument is the REL BSS message cell 0x8082B5AC.
    if abi_call1!(0x8069_9FB0, this) != 0 && platform::read_u32(this + 0x788) == 0 {
        actor_method1(this, 0xD4, 0x8082_B5AC);
    }
}

/// Paints a vertical run of 16x16 tiles for the `0x8080DF54` draw slot.
///
/// Picks the top-row tile family from `+0x63C`/`+0x644`/`+0x648`, blits one or
/// two tiles at `([+0xAC]-8, [+0xB0]-8)`, then walks down in 16-unit steps while
/// the y coordinate is above `16 + [+0x550] - [+0x644]`.
///
/// # Original
/// - Ghidra: `FUN_807373b0` at `0x807373B0` (844 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/807373b0_FUN_807373b0.c`
///
/// # Arguments
/// * `this` - painter object; `+0xAC`/`+0xB0` position, `+0x550` run end,
///   `+0x63C` tile-set column, `+0x644`/`+0x648` mode heights.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Blits through `0x80077860` at 16.4 fixed-point coordinates and probes the map
/// once with `0x80070BF0`.
///
/// # Safety
/// `this` must be live through `+0x648`; `0x80429DD0` must hold the tile manager
/// and the six `0x807CDBxx` tables must be mapped.
///
/// # Confidence
/// high - every table, constant and blit argument is literal; the roles of
/// `+0x550`/`+0x644`/`+0x648` are `// inferred:`. The four `qr0` brackets are
/// `f28..f31` register saves only, retiring the wave-30/101 rejection.
pub unsafe fn fn_807373b0(this: usize) {
    let x = platform::read_f32(this + 0xAC) - 8.0;
    let mut y = platform::read_f32(this + 0xB0) - 8.0;
    let idx = (platform::read_i32(this + 0x63C) as usize) * 4;

    // observed: the blit takes `(manager, x, -y, 0, tile_id & 0xFFFF)`; `x` and
    // `y` reach the callee as 16.4 fixed point (`fctiwz`, then `& 0xFFFF`).
    let manager = platform::read_u32(0x8042_9DD0);
    let top = |table: usize, x: f32, y: f32| {
        let tile = platform::read_u32(table + idx) & 0xFFFF;
        abi_call5!(
            0x8007_7860,
            manager,
            (x as i32 as u32) & 0xFFFF,
            ((-y) as i32 as u32) & 0xFFFF,
            0u32,
            tile
        );
    };

    if platform::read_f32(this + 0x648) == 0.0 {
        top(0x807C_DB18, x, y);
        top(0x807C_DB24, 16.0 + x, y);
    } else if platform::read_f32(this + 0x644) == platform::read_f32(this + 0x648) {
        // observed: 0x807374B4 - `(u8)0x80070BF0(x, y, 0) != 4` returns without
        // painting the strip.
        if (call_f32x2_u32(0x8007_0BF0, x, y, 0) & 0xFF) != 4 {
            return;
        }
        top(0x807C_DB18, x, y);
        top(0x807C_DB24, 16.0 + x, y);
        return;
    } else {
        top(0x807C_DB30, x, y);
        top(0x807C_DB3C, 16.0 + x, y);
    }

    // observed: 0x80737608 pre-computes the two integer x coordinates once.
    let xi0 = x as i32;
    let xi1 = (16.0 + x) as i32;
    while y > 16.0 + (platform::read_f32(this + 0x550) - platform::read_f32(this + 0x644)) {
        y -= 16.0;
        let tile0 = platform::read_u32(0x807C_DB48 + idx) & 0xFFFF;
        abi_call5!(
            0x8007_7860,
            manager,
            (xi0 as u32) & 0xFFFF,
            ((-y) as i32 as u32) & 0xFFFF,
            0u32,
            tile0
        );
        let tile1 = platform::read_u32(0x807C_DB54 + idx) & 0xFFFF;
        abi_call5!(
            0x8007_7860,
            manager,
            (xi1 as u32) & 0xFFFF,
            ((-y) as i32 as u32) & 0xFFFF,
            0u32,
            tile1
        );
    }
}

/// Post-load initialiser of the `obj_nut` actor.
///
/// Runs the model loader [`fn_80705fb0`], sizes and centres the nut block from
/// the `+0x04` bitfield, installs the collision record at `+0x148` with callback
/// `0x80706280`, writes the pose at `+0x164..+0x170`, creates one motion record
/// (three words at `+0x41C` or four at `+0x428`), copies the class word into the
/// twelve records at `+0x43C`, starts the `0x8082F360` clip and returns `1`.
///
/// # Original
/// - Ghidra: `FUN_80705c60` at `0x80705C60` (840 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80705c60_FUN_80705c60.c`
///
/// # Arguments
/// * `this` - `obj_nut` actor; bitfield `+0x04`, position `+0xAC..+0xB4`,
///   collision record `+0x148`, pose `+0x164..+0x170`, motion `+0x1EC`,
///   extents `+0x318..+0x344`, `+0x404..+0x418`, records `+0x41C`/`+0x428`.
///
/// # Returns
/// `1` on every path (`li r3,1` at `0x80705F90`).
///
/// # Side effects
/// Writes the whole layout above, registers the collision record and starts the
/// idle clip through the animator at `+0x394` (slot `+0x18`).
///
/// # Safety
/// `this` must be a freshly allocated `obj_nut` actor; `0x8042BB08`,
/// `0x8042BB0C` and the `0x807CC6xx` literal block must be mapped.
///
/// # Confidence
/// medium - every instruction, constant and call is literal; the meaning of the
/// motion records is not proven, and the `+0x420`/`+0x434` conversions are an
/// artefact of the shipped single-precision sequence (they evaluate to `0`, not
/// to a fixed-point constant).
pub unsafe fn fn_80705c60(this: usize) -> u32 {
    abi_call1!(0x8070_5FB0, this);

    let bits = platform::read_u32(this + 0x04);
    // observed: `rlwinm r5,r0,0,29,31` = bits 0-2, `rlwinm r4,r0,28,31,31` =
    // bit 4.
    let width = 16.0 * ((bits & 7) as f32 + 4.0);
    let height = 16.0 * (((bits >> 4) & 1) as f32 + 1.0);
    let half_width = 0.5 * width;
    let half_height = 0.5 * height;
    let x = platform::read_f32(this + 0xAC) + half_width;
    let y = platform::read_f32(this + 0xB0) - half_height;
    let z = platform::read_f32(this + 0xB4);

    // observed: 0x80705CD4..0x80705D3C, store order preserved.
    platform::write_f32(this + 0x404, width);
    platform::write_f32(this + 0x408, height);
    platform::write_f32(this + 0xDC, 1.0);
    platform::write_f32(this + 0xE0, 1.0);
    platform::write_f32(this + 0xE4, 1.0);
    platform::write_f32(this + 0xAC, x);
    platform::write_f32(this + 0xB0, y);
    platform::write_f32(this + 0x410, x);
    platform::write_f32(this + 0x414, y);
    platform::write_f32(this + 0x418, z);

    let world_a = platform::read_f32(0x8042_BB0C);
    let world_b = platform::read_f32(0x8042_BB08) + 160.0;
    platform::write_f32(this + 0x338, world_a);
    platform::write_f32(this + 0x33C, world_a);
    platform::write_f32(this + 0x340, world_b);
    platform::write_f32(this + 0x344, world_b);
    platform::write_f32(this + 0x320, 0.0);
    platform::write_f32(this + 0x324, 0.0);
    platform::write_f32(this + 0x318, half_width);
    platform::write_f32(this + 0x31C, half_height);

    // observed: the template `0x807CC648` supplies the six-word collision
    // record and the `0x80706280` touch callback.
    abi_call3!(0x8008_C3E0, this + 0x148, this, 0x807C_C648);
    abi_call1!(0x8008_C330, this + 0x148);

    // observed: pose block; `12.0 * [+0xE0]`, `0.5 * [+0x404]`.
    platform::write_f32(this + 0x164, 0.0);
    platform::write_f32(
        this + 0x168,
        12.0 * platform::read_f32(this + 0xE0),
    );
    platform::write_f32(
        this + 0x16C,
        0.5 * platform::read_f32(this + 0x404),
    );
    platform::write_f32(this + 0x170, 2.0);

    // observed: the shipped sequence is `fsubs` of `(f32)(2^52 + 0x38000)` and
    // `(f32)2^52`, then `fmuls` by `[+0xDC]` and `fctiwz`. Both operands round
    // to 2^52 in single precision, so the product is 0.0 in both arms. The
    // expression is kept so the provenance is visible.
    let arm_value = (((1u64 << 52) + 0x38000) as f64 as f32
        - ((1u64 << 52) as f64) as f32)
        * platform::read_f32(this + 0xDC);

    // observed: `rlwinm. r0,r0,28,31,31` selects one bit, so the `== 2` and
    // `== 3` arms at 0x80705E84..0x80705F68 are dead in the shipped image.
    if ((bits >> 4) & 1) == 0 {
        platform::write_u32(this + 0x41C, 0);
        platform::write_u32(this + 0x424, 0);
        platform::write_i32(this + 0x420, arm_value as i32);
        abi_call5!(0x8006_D090, this + 0x1EC, this, 0u32, 0u32, this + 0x41C);
    } else {
        platform::write_u32(this + 0x428, 1);
        platform::write_u32(this + 0x42C, 0x0000_C000);
        platform::write_u32(this + 0x430, 0xFFFF_4000);
        platform::write_i32(this + 0x434, arm_value as i32);
        abi_call5!(0x8006_D090, this + 0x1EC, this, 0u32, 0u32, this + 0x428);
    }

    abi_call1!(0x8070_61F0, this);
    // observed: animator slot `+0x18` starts the `0x8082F360` clip.
    vmethod1(this + 0x394, 0x18, 0x8082_F360);
    1
}

