    let area = platform::read_i32(this + 0x3388);

    let mut message = 0u32;
    let mut selected = false;
    match area {
        0 => {
            message = 0x28F;
            selected = true;
        }
        3 => {
            message = 0x290;
            selected = true;
        }
        4 => {
            message = 0x291;
            selected = true;
        }
        2 => {
            message = 0x292;
            selected = true;
        }
        6 => {
            message = 0x293;
            selected = true;
        }
        _ => {}
    }

    abi_call2!(
        0x800E_0380,
        platform::read_u32(0x8042_A040),
        0xFFFF_FFFFu32
    );

