/// # Safety
/// Every node on `+0x40C` must be live, each `+0x04` word must hold an actor
/// with a model at `+0x60`, and `0x8005F900` must accept ids `0..3`.
///
/// # Confidence
/// medium - the loop, the character-id test and both vtable slots are literal,
/// and `f1`/`f2` are both the `0.0` at `0x807CAF68`; the meaning of the
/// `0x400`/`0x434` slots and of the `0x1E` word is `// unknown:`.
pub unsafe fn fn_806c12f0(this: usize) {
    let mut node = platform::read_u32(this + 0x40C) as usize;
    while node != 0 {
        let actor = platform::read_u32(node + 4) as usize;
        let model = platform::read_u32(actor + 0x60) as usize;
        let character =
            abi_call1!(platform::read_u32(model + 0x6C) as usize, actor) as usize;
        let id = platform::read_u8(character) as i8;
        if (id as u32) < 4 {
            let player = abi_call1!(0x8005_F900, id as u32) as usize;
            if player != 0 {
                let player_model = platform::read_u32(player + 0x60) as usize;
                let value = platform::read_f32(0x807C_AF68);
                call_f32x2_u32x4(
                    platform::read_u32(player_model + 0x400) as usize,
                    value,
                    value,
                    player as u32,
                    1u32,
                    2u32,
                    0u32,
                );
                abi_call3!(
                    platform::read_u32(player_model + 0x434) as usize,
                    player as u32,
                    0x1Eu32,
                    0u32
                );
            }
        }
        node = platform::read_u32(node + 8) as usize;
    }
}

