// Wave 153: `0x8064` planner bucket
// ---------------------------------------------------------------------------

/// Shifts a 64-bit accumulator one bit toward a two-word input scan mask.
///
/// The object keeps a 64-bit word in `{hi = +0x358, lo = +0x35C}` and two scan
/// masks `{+0x1A490, +0x1A494}` together with the two input words
/// `{+0x1A488, +0x1A48C}`. The body compares the live bit of each mask with the
/// corresponding input word; when a mask bit is set and the global selection
/// word agrees it shifts the 64-bit word left and latches `+0x1A4F6 = 1`, when
/// the mask agrees but the selection does not it shifts right and latches
/// `0xFF`. Otherwise it shifts the two-word input left and retries until the
/// input is zero or exceeds the accumulator.
///
/// # Original
/// - Ghidra: `FUN_80648770` at `0x80648770` (288 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80648770_FUN_80648770.c`
///
/// # Arguments
/// * `this` - the owner of the `0x1A4xx` state block; only the fields above are
///   touched.
///
/// # Returns
/// Nothing; every path ends in `blr`.
///
/// # Side effects
/// Writes `+0x1A490`, `+0x1A494`, `+0x358`, `+0x35C` and `+0x1A4F6`.
///
/// # Safety
/// `this` must be live and `[0x8042A078]` is dereferenced as a two-word pointer.
///
/// # Confidence
/// medium - every shift, mask and store is literal (`rlwinm`/`rlwimi` give the
/// 64-bit shift pair exactly), but the roles of the two masks, the 64-bit word
/// and the `0x8042A078` selection record are `// unknown:`, so only the data flow
/// is provable.
pub unsafe fn fn_80648770(this: usize) {
    // unknown: [0x8042A078] is a main.dol pointer to a two-word selection record.
    let selection = platform::read_u32(0x8042_A078) as usize;
    let mut input_hi = platform::read_u32(this + 0x1A488);
    let mut input_lo = platform::read_u32(this + 0x1A48C);

    loop {
        let mask_lo = platform::read_u32(this + 0x1A490);
        let mask_hi = platform::read_u32(this + 0x1A494);

        if (mask_lo & input_hi) | (mask_hi & input_lo) == 0 {
            let sel_lo = platform::read_u32(selection);
            let sel_hi = platform::read_u32(selection + 4);
            if (input_hi & sel_lo) | (input_lo & sel_hi) != 0 {
                // Mask bit set and selection agrees: shift the 64-bit word left.
                let hi = platform::read_u32(this + 0x358);
                let lo = platform::read_u32(this + 0x35C);
                platform::write_u32(this + 0x1A490, mask_lo | input_hi);
                platform::write_u32(this + 0x1A494, mask_hi | input_lo);
                platform::write_u32(this + 0x35C, lo << 1);
                platform::write_u32(this + 0x358, (hi << 1) | (lo >> 31));
                platform::write_u8(this + 0x1A4F6, 1);
                return;
            }
        } else {
            let sel_lo = platform::read_u32(selection);
            let sel_hi = platform::read_u32(selection + 4);
            if (input_hi & sel_lo) | (input_lo & sel_hi) == 0 {
                // Mask bit set but selection disagrees: shift the word right.
                let hi = platform::read_u32(this + 0x358);
                let lo = platform::read_u32(this + 0x35C);
                platform::write_u32(this + 0x1A490, mask_lo ^ input_hi);
                platform::write_u32(this + 0x1A494, mask_hi ^ input_lo);
                platform::write_u32(this + 0x358, hi >> 1);
                platform::write_u32(this + 0x35C, (lo >> 1) | (hi << 31));
                platform::write_u8(this + 0x1A4F6, 0xFF);
                return;
            }
        }

        // Shift the two-word input left one bit; a zero result ends the scan.
        let next_lo = input_lo << 1;
        let next_hi = (input_hi << 1) | (input_lo >> 31);
        if next_hi == 0 && next_lo == 0 {
            return;
        }
        input_lo = next_lo;
        input_hi = next_hi;

        // observed: the multiword `subfc`/`subfe` chain returns when the shifted
        // input is greater than the accumulator.
        let hi = platform::read_u32(this + 0x358);
        let lo = platform::read_u32(this + 0x35C);
        let input = ((input_hi as u64) << 32) | input_lo as u64;
        let current = ((hi as u64) << 32) | lo as u64;
        if input > current {
            return;
        }
    }
}

/// Loads one of the three `I_kinoko` variant models and its animation clips.
///
/// The variant index at `+0x6E4` (0..4) selects an archive pane, a BRRES path
/// and a body pane out of three parallel pointer tables at `0x807E43AC`,
/// `0x807E444C` and `0x807E447C`. The body opens the `+0x3D0` render block,
/// loads the archive into `+0x3EC`, builds the body model and its `+0x3F0`
/// animation object, binds the `wait2` clip at `+0x430`, and for variants `0`
/// and `4` also builds the `I_kinoko_switch` animation at `+0x468`, installs it
/// on the model through virtual `+0x18`, and sets its frame pair (`2.0` for
/// variant `4`, `0.0` otherwise).
///
/// # Original
/// - Ghidra: `FUN_8064cd60` at `0x8064CD60` (488 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8064cd60_FUN_8064cd60.c`
///
/// # Arguments
/// * `this` - the `I_kinoko` power-up actor; `+0x6E4` is the variant index.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x3EC`, `+0x3F0`, `+0x430`, `+0x468` and the render block `+0x3D0`.
///
/// # Safety
/// `this` must be live and `[0x8042A038]` (the stage archive table) readable.
///
/// # Confidence
/// medium - every table address, call and store is literal; the variant meanings
/// (which pane belongs to which power-up) are inferred from the strings in the
/// three tables, and `0x80166830`/`0x80166BD0`/`0x80166EF0` are named by address
/// only.
pub unsafe fn fn_8064cd60(this: usize) {
    let variant = platform::read_u32(this + 0x6E4) as usize;

    // Render block; the fourth argument is the *value* at 0x80377C48.
    abi_call6!(
        0x8016_A7F0,
        this + 0x3D0,
        0xFFFF_FFFF,
        platform::read_u32(0x8037_7C48),
        0,
        0x20,
        0,
    );

    // Archive pane and BRRES path come from two 5-entry pointer tables.
    let pane = platform::read_u32(0x807E_43AC + variant * 4);
    let archive = platform::read_u32(0x807E_444C + variant * 4);
    let handle = abi_call3!(
        0x800D_F180,
        platform::read_u32(0x8042_A038) + 4,
        pane,
        archive,
    );
    platform::write_u32(this + 0x3EC, handle);

    let mut model = abi_call2!(
        0x8023_9E30,
        this + 0x3EC,
        platform::read_u32(0x807E_447C + variant * 4),
    );
    abi_call6!(
        0x8016_9D90,
        this + 0x3F0,
        &mut model as *mut u32 as u32,
        this + 0x3D0,
        platform::read_u32(0x807C_8614 + variant * 4),
        1,
        0,
    );
    abi_call1!(0x8006_4C10, this + 0x3F0);

    // The shared "wait2" clip at +0x430.
    let mut wait_clip = abi_call2!(0x8023_A0B0, this + 0x3EC, 0x807E_4498);
    let mut wait_model = model;
    abi_call5!(
        0x8016_50D0,
        this + 0x430,
        &mut wait_model as *mut u32 as u32,
        &mut wait_clip as *mut u32 as u32,
        this + 0x3D0,
        0,
    );
    abi_call4!(
        0x8016_51F0,
        this + 0x430,
        this + 0x3F0,
        &mut wait_clip as *mut u32 as u32,
        0,
    );
    call_f32_u32x2(0x8016_9F80, 1.0, (this + 0x3F0) as u32, (this + 0x430) as u32);

    // Variants 0 and 4 also carry the switch animation at +0x468.
    if variant == 0 || variant == 4 {
        let mut switch_anim = abi_call2!(0x8023_A200, this + 0x3EC, 0x807E_44A0);
        let mut switch_model = model;
        abi_call6!(
            0x8016_6830,
            this + 0x468,
            &mut switch_model as *mut u32 as u32,
            &mut switch_anim as *mut u32 as u32,
            this + 0x3D0,
            0,
            1,
        );
        abi_call5!(
            0x8016_6BD0,
            this + 0x468,
            this + 0x3F0,
            &mut switch_anim as *mut u32 as u32,
            0,
            1,
        );
        vmethod2(this + 0x3F0, 0x18, (this + 0x3F0) as u32, (this + 0x468) as u32);
        let frame = if variant == 4 { 2.0 } else { 0.0 };
        call_f32_u32x2(0x8016_6EF0, frame, (this + 0x468) as u32, 0);
        call_f32_u32x2(0x8016_6F10, 0.0, (this + 0x468) as u32, 0);
    }

    abi_call1!(0x8016_A8E0, this + 0x3D0);
}

