    for off in [0x28usize, 0x29, 0x2A] {
        platform::write_u8(dst + off, platform::read_u8(src + off));
    }
    for off in [0x2Cusize, 0x30, 0x34, 0x38] {
        platform::write_u32(dst + off, platform::read_u32(src + off));
    }
