/// # Original
/// Host-side helper for the compiler-generated move in `FUN_8063a960`
/// (`work/ghidra/rel-d_basesNP/export/8063a960_FUN_8063a960.c`). The byte at
/// `+0x00`, the five words `+0x04..+0x14` and the bytes `+0x18`/`+0x19` are
/// copied; `+0x01..+0x03` and `+0x1A`/`+0x1B` are not.
///
/// # Safety
/// Both pointers must be readable/writable for `0x1C` bytes.
///
/// # Confidence
/// high - the field list is the export's own store list.
#[inline]
unsafe fn copy_player_record_short(dst: usize, src: usize) {
    platform::write_u8(dst, platform::read_u8(src));
    for off in [0x04usize, 0x08, 0x0C, 0x10, 0x14] {
        platform::write_u32(dst + off, platform::read_u32(src + off));
    }
    platform::write_u8(dst + 0x18, platform::read_u8(src + 0x18));
    platform::write_u8(dst + 0x19, platform::read_u8(src + 0x19));
}

/// Builds the four per-player records at `+0x2CC` and reorders them to
/// controller order `{0,1,3,2}`.
///
/// Reads the order table `0x80354E60` written by [`fn_807b2050`], fills each
/// record from the player base cell `0x80429FB0` (or clears it when
/// `0x800B4710(i)` reports the player absent), then sorts the four records into
/// `{0,1,3,2}` through a `0x70`-byte stack buffer. It finishes by running the two
/// record finalisers, setting the `+0x33D`/`+0x33E`/`+0x340` bytes and sending
/// the `0x80826EE0` descriptor to virtual `+0x18` of `this + 0x208`.
///
/// # Original
/// - Ghidra: `FUN_8063a960` at `0x8063A960` (604 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8063a960_FUN_8063a960.c`
///
/// # Arguments
/// * `this` - the owner (entry `r3`, preserved by the `0x802DCD64` prologue, so
///   Ghidra prints no parameter); records `+0x2CC`, interface object `+0x208`.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// `this` must be live, `0x80354E60` must hold a permutation of `0..3`, and the
/// player base cell must expose `+0x58` and `+0x08..+0x38`.
///
/// # Confidence
/// medium - every field, constant and callee is literal; the `0x1C`-byte record
/// is copied as `0x1A` bytes with `+0x1A`/`+0x1B` left from the stack in the
/// original (zero-filled here), and three callees stay address-only.
pub unsafe fn fn_8063a960(this: usize) {
    let base = platform::read_u32(0x8042_9FB0) as usize;

    for i in 0..4usize {
        let id = platform::read_u32(0x8035_4E60 + i * 4) as usize;
        let record = this + 0x2CC + id * 0x1C;
        platform::write_u32(record + 0x14, id as u32);
        let present = abi_call1!(0x800B_4710, i as u32);
        if present == 0 {
            platform::write_u8(record + 0x00, 0);
            platform::write_u32(record + 0x04, 0);
            platform::write_u8(record + 0x19, 0);
            platform::write_u32(record + 0x08, 0);
            platform::write_u32(record + 0x0C, 0);
            platform::write_u32(record + 0x10, 0);
        } else {
            platform::write_u8(record + 0x19, 1);
            platform::write_u32(record + 0x04, platform::read_u32(base + i * 4 + 0x18));
            platform::write_u8(record + 0x00, platform::read_u8(base + id + 0x58));
            platform::write_u32(record + 0x08, platform::read_u32(base + i * 4 + 0x28));
            platform::write_u32(record + 0x10, platform::read_u32(base + i * 4 + 0x38));
            platform::write_u32(record + 0x0C, platform::read_u32(base + i * 4 + 0x08));
        }
        platform::write_u8(record + 0x18, 0);
        abi_call2!(0x8063_A8C0, this, id as u32);
    }

    let mut staging = [0u8; 0x70];
    let staging_base = staging.as_mut_ptr() as usize;
    for k in 0..4usize {
        let want = platform::read_u32(0x807C_7F70 + k * 4); // {0, 1, 3, 2}
        for i in 0..4usize {
            let record = this + 0x2CC + i * 0x1C;
            if platform::read_u32(record + 0x14) == want {
                // observed: the original leaves `+0x1A`/`+0x1B` from the stack;
                // they are never copied back, so zero-filled staging is exact.
                copy_player_record_short(staging_base + k * 0x1C, record);
                break;
            }
        }
    }
    for k in 0..4usize {
        copy_player_record_short(this + 0x2CC + k * 0x1C, staging_base + k * 0x1C);
    }

    abi_call1!(0x8063_A680, this);
    abi_call1!(0x8063_A850, this);
    platform::write_u8(this + 0x33E, 0);
    platform::write_u8(this + 0x33D, 1);
    platform::write_u8(this + 0x340, 0);
    let object = this + 0x208;
    vmethod1(object, 0x18, 0x8082_6EE0);
}

/// Releases a resource owner when it is non-null.
///
/// Calls `0x8015F800(owner, 0)` on every non-null owner and then, only when
/// `amount` is positive, hands the same owner to the allocator's release entry
/// `0x802B9280`. The owner is returned unchanged.
///
/// # Original
/// - Ghidra: `FUN_806f1b30` at `0x806F1B30` (88 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806f1b30_FUN_806f1b30.c`
///
/// # Arguments
/// * `this` - the resource owner, or `0`.
/// * `amount` - element count; the free call runs only when it is above zero.
///
/// # Returns
/// `this`, so callers can chain the null test.
///
/// # Safety
/// A non-null `this` must be a live owner accepted by both callees.
///
/// # Confidence
/// high - the null test, the unconditional first call and the signed
/// `amount > 0` test are literal.
pub unsafe fn fn_806f1b30(this: usize, amount: i32) -> usize {
    if this != 0 {
        abi_call2!(0x8015_F800, this, 0);
        if amount > 0 {
            // unknown: 0x802B9280 is the heap release entry used by this family.
            abi_call1!(0x802B_9280, this);
        }
    }
    this
}

/// Counts a per-owner timer down and reports a confirm edge while either pad
/// button `0x100` or `0x800` is held.
///
/// Decrements `+0x218`, then reads the pad word at
/// `[[0x80429F50]+4]+0x1C`. When either bit `0x100` or `0x800` is set and the
/// counter has reached zero, the counter is clamped to `0` and the function
/// returns `1`; every other path returns `0`.
///
/// # Original
/// - Ghidra: `FUN_806fdc50` at `0x806FDC50` (72 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806fdc50_FUN_806fdc50.c`
///
/// # Arguments
/// * `this` - the owner; countdown `+0x218`.
///
/// # Returns
/// `1` on the confirm edge, `0` otherwise.
///
/// # Safety
/// `this` must be live and the two global cells must hold valid pointers.
///
/// # Confidence
/// high - the decrement, the `rlwinm`/`rlwimi` bit pair and the clamp are
/// literal; the pad cell layout comes from the two loads.
pub unsafe fn fn_806fdc50(this: usize) -> u32 {
    let remaining = platform::read_i32(this + 0x218) - 1;
    platform::write_i32(this + 0x218, remaining);
    let manager = platform::read_u32(0x8042_9F50) as usize;
    let pad = platform::read_u32(platform::read_u32(manager + 4) as usize + 0x1C);
    if (pad & 0x900) != 0 && remaining < 1 {
        platform::write_i32(this + 0x218, 0);
        return 1;
    }
    0
}

/// Stores a new value in the owner's `+0x218` countdown.
///
/// # Original
/// - Ghidra: `FUN_806fdca0` at `0x806FDCA0` (8 bytes)
