/// Nothing.
///
/// # Side effects
/// Writes the two latch bytes and fires the `(4, 1)` / `(8, 1)` flag calls;
/// applies the one-shot course id to the save image.
///
/// # Safety
/// The scene manager cell `0x8042A18C` and the save-image record cell
/// `0x8042A040` must be live.
///
/// # Confidence
/// medium - all 147 words decoded and every offset, mask and bound is literal;
/// four `0x800Fxxxx` scene-API callees stay address-only and the two engine
/// predicates are only fixed to "returns zero" (`countlz(v) >> 5`).
pub unsafe fn fn_8079bf00(this: usize, node: u32, kind: u32) {
    let scene = platform::read_u32(0x8042_A18C) as usize;
    let record = abi_call2!(
        0x800E_0380,
        platform::read_u32(0x8042_A040),
        0xFFFF_FFFF
    );
    let id = fn_80799b00(this, node, kind);

    let mut position = [0.0f32; 3];
    abi_call3!(
        0x8010_0200,
        position.as_mut_ptr() as u32,
        scene,
        id
    );
    let table = scene + platform::read_i32(scene + 0x338C) as usize * 0x16518 + 0x3394;

    // Half 1: layer 0x1000. `countLeadingZeros(v) >> 5` is `v == 0`.
    if abi_call3!(0x800F_57A0, table, id, 0x1000) != 0 {
        let probe = position;
        if abi_call1!(0x800F_A070, probe.as_ptr() as u32) == 0 {
            platform::write_u8(this + 0x25A, 1);
            abi_call3!(0x80C5_61E0, platform::read_u32(this + 0x29C), 4, 1);
        }
    }

    // Half 2: layer 0x2000 (the store follows the sound call here).
    if abi_call3!(0x800F_57A0, table, id, 0x2000) != 0 {
        let probe = position;
        if abi_call1!(0x800F_A0E0, probe.as_ptr() as u32) == 0 {
            abi_call3!(0x80C5_61E0, platform::read_u32(this + 0x29C), 8, 1);
            platform::write_u8(this + 0x25B, 1);
        }
    }

    if platform::read_u8(this + 0x25A) != 0 || platform::read_u8(this + 0x25B) != 0 {
        let target = abi_call2!(0x800F_57E0, table, id);
        if target != 0 {
            for slot in 0..192u32 {
                if abi_call3!(0x800F_57A0, table, slot, 1) == 0 {
                    continue;
                }
                if abi_call2!(0x800F_57E0, table, slot) != target {
                    continue;
                }

                let course = platform::read_u8(0x8042_A24D) as u32;
                abi_call2!(0x800F_56B0, table, slot);
                let value = call0_ret(0x800F_9530) & 0xFF;
                if abi_call4!(0x800C_E3C0, record, course, value, 0x20) != 0 {
                    platform::write_u8(this + 0x25A, 0);
                    platform::write_u8(this + 0x25B, 0);
                }
                // The first handle match ends the scan even when the course-id
                // test then fails.
                break;
            }
        }
    }
}

