    // length; `0x80819214` is the format "g3d/%s.brres".
    let suffix_length = abi_call1!(0x802D_C69C, 0x8081_9208);
    let name_length = abi_call1!(0x802D_C69C, name);
    let mut path = [0u8; 0x100];
