/// Advances the bomb's contact/explosion state machine.
///
/// Reads the `+0x3D0` handle through `0x80162D00`, mirrors its `+0x394` value
/// into `+0x3EC`, and when that value crosses `0.0` (was non-zero, previous
/// sample `0.0`) clears `+0x3E0`, rotates the four-phase word `+0x3F4` and
/// resets `+0x3F8`/`+0x3FC`. While the phase word is odd the body tests the
/// `0.1`/`0.2` thresholds, runs the `+0x3E0`/`+0x400` countdowns and calls
/// `0x806564A0(actor, falling)`.
///
/// # Original
/// - Ghidra: `FUN_806566f0` at `0x806566F0` (404 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/806566f0_FUN_806566f0.c`
///
/// # Arguments
/// * `actor` - the actor; handle `+0x3D0`, state `+0x3E0`, samples
///   `+0x3EC`/`+0x3F0`, phase `+0x3F4`, flags `+0x3F8`/`+0x3FC`, counter
///   `+0x400`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// The sample/phase stores and one `0x806564A0` call per eligible frame.
///
/// # Safety
/// `[actor+0x3D0]` must resolve through `0x80162D00` to a record readable at
/// `+0x394`/`+0x398`.
///
/// # Confidence
/// medium - every offset, threshold and branch is literal; `0x80162D00`'s
/// record layout (a height/nozzle pair) is inferred from the two compared
/// floats, and `0x806564A0` is called address-only.
pub unsafe fn fn_806566f0(actor: usize) {
    let record = abi_call1!(0x8016_2D00, platform::read_u32(actor + 0x3D0)) as usize;
    // observed: 0.0f is `0x807C8910`, 0.1f `0x807C8918`, 0.2f `0x807C891C`.
    let zero = platform::read_f32(0x807C_8910);
    if record == 0 {
        return;
    }

    let sample = platform::read_f32(record + 0x394);
    platform::write_f32(actor + 0x3EC, sample);
    if sample != zero && platform::read_f32(actor + 0x3F0) == zero {
        platform::write_u32(actor + 0x3E0, 0);
        let phase = (platform::read_i32(actor + 0x3F4) + 1) as u32 & 3;
        platform::write_u32(actor + 0x3F4, phase);
        platform::write_u32(actor + 0x3F8, 0);
        if platform::read_i32(actor + 0x400) == 0 {
            platform::write_u32(actor + 0x3FC, 0);
        }
    }
    platform::write_f32(actor + 0x3F0, platform::read_f32(actor + 0x3EC));

    let limit = platform::read_f32(record + 0x398);
    if platform::read_f32(actor + 0x3EC) == limit {
        platform::write_u32(actor + 0x3F8, 1);
    }
    if platform::read_u32(actor + 0x3F4) & 1 == 0 {
        return;
    }

    let mut trigger = false;
    if platform::read_i32(actor + 0x3F8) == 0 {
        if platform::read_f32(0x807C_8918) <= platform::read_f32(actor + 0x3EC) {
            trigger = true;
        }
    } else if platform::read_i32(actor + 0x3FC) != 0 {
        if platform::read_i32(actor + 0x400) != 0 {
            let counter = platform::read_i32(actor + 0x400) - 1;
            platform::write_i32(actor + 0x400, counter);
        }
        if platform::read_i32(actor + 0x400) != 0
            && platform::read_f32(actor + 0x3EC) == limit
        {
            trigger = true;
        }
    }
    if !trigger {
        return;
    }

    let falling = platform::read_f32(actor + 0x3EC) <= zero;
    if platform::read_i32(actor + 0x3E0) != 0 {
        let timer = platform::read_i32(actor + 0x3E0) - 1;
        platform::write_i32(actor + 0x3E0, timer);
    }
    if platform::read_i32(actor + 0x3E0) == 0 {
        let wait = if platform::read_f32(actor + 0x3EC) < platform::read_f32(0x807C_891C) {
            0x20
        } else {
            8
        };
        platform::write_i32(actor + 0x3E0, wait);
        // unknown: 0x806564A0 advances the explosion effect; its own export
        // ends in the out-of-range call 0x80A46F60, so it stays address-only.
        abi_call2!(0x8065_64A0, actor, falling as u32);
    }
}

