#[inline]
unsafe fn call_f32x3_u32x2_f32(addr: usize, a: f32, b: f32, c: f32, d: u32, e: u32) -> f32 {
    let function: extern "C" fn(f32, f32, f32, u32, u32) -> f32 = core::mem::transmute(addr);
    function(a, b, c, d, e)
}

