        platform::write_f32(this + 0xAC, platform::read_f32(this + 0xAC) - offset[0]);
        platform::write_f32(this + 0xB0, platform::read_f32(this + 0xB0) - offset[1]);
        platform::write_f32(this + 0xB4, platform::read_f32(this + 0xB4) - offset[2]);
