        platform::write_f32(this + 0xAC, platform::read_f32(this + 0xAC) + 0.0);
        platform::write_f32(this + 0xB0, platform::read_f32(this + 0xB0) + 0.0);
        platform::write_f32(this + 0xB4, platform::read_f32(this + 0xB4) + 0.0);
