    let aim_y = (node[1] - element_offset[1]) + 0.0;
    let aim_z = (node[2] - element_offset[2]) + 0.0;
    platform::write_f32(this + 0x784, aim_x);
    platform::write_f32(this + 0x788, aim_y);
