    abi_call1!(platform::read_u32(surface + 0x1C) as usize, this + 0x1AC);
    let effect = platform::read_u32(this + 0x1B8) as usize;
    abi_call1!(platform::read_u32(effect + 0x14) as usize, this + 0x1B8);

    fn_8075c930(this);
    1
