    platform::write_u32(this + 0x518, 0);
    platform::write_f32(this + 0x524, zero);
    platform::write_f32(this + 0x528, zero);
    platform::write_f32(this + 0x52C, zero);
    platform::write_f32(this + 0x530, zero);

    let gain = platform::read_f32(0x807C_D8CC);
    let inverse256 = platform::read_f32(0x807C_D8E0);
    let half = platform::read_f32(0x807C_D8E4);

