    abi_call1!(0x8063_7310, this);
    abi_call2!(0x8063_7610, this, 1);

    platform::write_u8(this + 0x8AE, 0);
    platform::write_u8(this + 0x8AD, 1);
    platform::write_u8(this + 0x8B0, 0);
    vmethod1(this + 0x6A8, 0x18, 0x8082_6AE0);
