    let ability = platform::read_u32(this + 0x29C) as usize;
    let bit = abi_call2!(0x80C5_6B20, ability, mask);
    let self_bit = (platform::read_u32(ability + 0x70) & bit) != 0;
    let node = platform::read_i32(this + 0x22C);
    let route = scene + platform::read_i32(scene + 0x338C) as usize * 0x16518 + 0x3394;

    let node_on = abi_call3!(0x800F_57A0, route, node, mask) != 0;
    let mut enabled = false;
