    platform::write_f32(this + 0x320, platform::read_f32(0x807C_BCC0)); // 24.0
    platform::write_f32(this + 0x324, height);
    platform::write_f32(this + 0x318, platform::read_f32(0x807C_BCC4)); // 48.0
