    call_f32_u32(0x8016_80E0, platform::read_f32(0x807C_EB9C), (this + 0x744) as u32);
    call_f32_u32(0x8016_8FE0, platform::read_f32(0x807C_EB9C), (this + 0x744) as u32);
    vmethod1(this + 0x704, 0x18, (this + 0x744) as u32);

