/// Counts the firepillar burst, bounces the height step and dispatches the end
/// state.
///
/// # Original
/// - Ghidra: `FUN_807a28b0` at `0x807A28B0` (440 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/807a28b0_FUN_807a28b0.c`
///
/// # Arguments
/// * `actor` - firepillar actor; effect objects `+0x4C4`/`+0x5EC`, effect
///   matrix `+0x4AC`, height `+0xE0`, step `+0x4A0`, step target `+0x4A8`,
///   burst counter `+0x4BC`, state object `+0x394`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Triggers the `Wm_ob_firespillar01`/`02` panes, advances the step through
/// [`fn_807a24e0`] and adds it to `+0xE0`. When the step has just reached zero
/// it bounces the target to `-0.0075` (`+0x4A0 > 0`) or, for a negative step,
/// decrements `+0x4BC`, queues sound `0x309` and reverses to `+0.0075`.
/// Crossing the `0.18` height window in either direction zeroes the target.
/// With `+0x4BC < 1` it dispatches state `0x80833020` on `+0x394`.
///
/// # Safety
/// `actor` must be live and both effect objects initialised.
///
/// # Confidence
/// high - the effect names, the `0x309` sound, the `0.0075`/`0.18`/`0.0`
/// constants and the `0x80833020` state pointer are literal. The Ghidra
/// comparison directions were re-checked against the raw `bc` BO/BI fields
/// (`4,1` = `ble`, `4,0` = `bge`).
pub unsafe fn fn_807a28b0(actor: usize) {
    let first_method = ptr_at(ptr_at(actor + 0x4C4) + 0xA0);
    abi_call6!(
        first_method,
        actor + 0x4C4,
        0x8081_C630, // observed: "Wm_ob_firespillar01"
        0,
        actor + 0x4AC,
        0,
        0
    );
    let second_method = ptr_at(ptr_at(actor + 0x5EC) + 0xA0);
    abi_call6!(
        second_method,
        actor + 0x5EC,
        0x8081_C61C, // observed: "Wm_ob_firespillar02"
        0,
        actor + 0x4AC,
        0,
        0
    );

    // observed: f31 and f30 hold the pre-call height and step; the gate below
    // tests the step that 0x807A24E0 produced.
    let old_height = platform::read_f32(actor + 0xE0);
    let old_step = platform::read_f32(actor + 0x4A0);
    fn_807a24e0(actor);
    let step = platform::read_f32(actor + 0x4A0);
    let height = platform::read_f32(actor + 0xE0) + step;
    platform::write_f32(actor + 0xE0, height);

    if step == platform::read_f32(0x807D_0388) {
        if old_step > platform::read_f32(0x807D_0388) {
            platform::write_f32(actor + 0x4A8, -platform::read_f32(0x807D_0300));
        } else if old_step < platform::read_f32(0x807D_0388) {
            let counter = platform::read_i32(actor + 0x4BC) - 1;
            platform::write_i32(actor + 0x4BC, counter);
            let mut position = [0u32; 4];
            abi_call2!(0x8006_A4B0, position.as_mut_ptr() as u32, actor + 0xAC);
            abi_call4!(
                0x8019_8C30,
                platform::read_u32(0x8042_9D60),
                0x309,
                position.as_mut_ptr() as u32,
                0
            );
            platform::write_f32(actor + 0x4A8, platform::read_f32(0x807D_0300));
        }
    }

    let threshold = platform::read_f32(0x807D_0324);
    if threshold <= old_height || height < threshold {
        if threshold < old_height && height <= threshold {
            platform::write_f32(actor + 0x4A8, platform::read_f32(0x807D_0388));
        }
    } else {
        platform::write_f32(actor + 0x4A8, platform::read_f32(0x807D_0388));
    }

    if platform::read_i32(actor + 0x4BC) < 1 {
        let method = ptr_at(ptr_at(actor + 0x394) + 0x18);
        abi_call2!(method, actor + 0x394, 0x8083_3020);
    }
}

/// Copies the ten per-slot model transforms into their `+0x244` targets.
///
/// # Original
/// - Ghidra: `FUN_80628450` at `0x80628450` (444 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80628450_FUN_80628450.c`
///
/// # Arguments
/// * `this` - screen object; manager `+0xB0` (flag byte `+0x27D`, source
///   transforms `+0x24C + i*4` for ten slots and `+0x274` for the single
///   target), owner array `+0xB4 + i*4`, single owner `+0xDC`. Ghidra drops the
///   `r3` argument because it mistakes the `0x802DCD74` save helper for a call;
///   the class is `// unknown:`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// When `manager[0x27D] != 0`, writes five words into each target's
/// `+0x2C..+0x34`/`+0x44`/`+0x48` from the source's `+0x90`, `+0xA0`, `0.0`,
/// `+0x84` and `+0x98`.
///
/// # Safety
/// `this`, the manager and all ten owner objects must be live.
///
/// # Confidence
/// high - every offset, the loop count and the `0x807C79D8` zero constant are
/// literal.
pub unsafe fn fn_80628450(this: usize) {
    let manager = ptr_at(this + 0xB0);
    if platform::read_u8(manager + 0x27D) != 0 {
        for index in 0..10 {
            let source = ptr_at(manager + 0x24C + index * 4);
            let target = ptr_at(ptr_at(this + 0xB4 + index * 4) + 0x244);
            platform::write_f32(target + 0x2C, platform::read_f32(source + 0x90));
            platform::write_f32(target + 0x30, platform::read_f32(source + 0xA0));
            platform::write_f32(target + 0x34, platform::read_f32(0x807C_79D8));
            platform::write_f32(target + 0x44, platform::read_f32(source + 0x84));
            platform::write_f32(target + 0x48, platform::read_f32(source + 0x98));
        }

        let source = ptr_at(manager + 0x274);
        let target = ptr_at(ptr_at(this + 0xDC) + 0x244);
        platform::write_f32(target + 0x2C, platform::read_f32(source + 0x90));
        platform::write_f32(target + 0x30, platform::read_f32(source + 0xA0));
        platform::write_f32(target + 0x34, platform::read_f32(0x807C_79D8));
        platform::write_f32(target + 0x44, platform::read_f32(source + 0x84));
        platform::write_f32(target + 0x48, platform::read_f32(source + 0x98));
    }
}

