        descriptor[1] = platform::read_u32(queue + 0x8);
        descriptor[2] = platform::read_u32(queue + 0xc);

        // observed: five outer blocks of `0x54` bytes (seven 12-byte entries
        // each); within a block the first two words of every entry are copied
        // from the next entry one slot up.
        let mut block = queue;
