/// `0x80237BD0`/`0x80237C40` sine/cosine identities remain `// inferred:`.
pub unsafe fn fn_80758880(this: usize) {
    // observed: `li 0x3000` / `neg` + `extsh` for the negative arm.
    let step: i32 = if platform::read_i32(this + 0x240) == 1 {
        -0x3000
    } else {
        0x3000
    };

    // observed: the `0x807CEA5C` (0.0) third component of the `r1+0xC` scratch
    // vector is dead; only `f1 = dx` and `f2 = dz` reach 0x801611C0.
    let aim = call_f32x2(
        0x8016_11C0,
        platform::read_f32(this + 0x22C) - platform::read_f32(this + 0xAC),
        platform::read_f32(this + 0x230) - platform::read_f32(this + 0xB0),
    ) as i16 as i32;

    // observed: `lha` + `add` + `sth`, then `extsh` of the sum for the tests.
    let sum = (platform::read_u16(this + 0x102) as i16 as i32).wrapping_add(step);
    platform::write_u16(this + 0x102, sum as u16);
    let angle = sum as i16 as i32;
    let inside = if step < 0 {
        angle < 0 && angle > aim
    } else {
        angle >= 0 && angle < aim
    };
    if inside {
        return;
    }
    platform::write_u16(this + 0x102, aim as u16);

    let state = platform::read_i32(this + 0x23C);
    if state == 2 || state == 3 {
        platform::write_f32(this + 0x250, platform::read_f32(0x807C_EAC4)); // 3.0
    }

    let model = platform::read_u32(platform::read_u32(this + 0x128) as usize + 4) as usize;
    let zero = platform::read_f32(0x807C_EA5C);
    vmethod_f32x3_u32(
        model,
        0x5C,
        platform::read_f32(this + 0x250),
        zero,
        zero,
        state as u32,
    );

    // observed: `psq_l ...,1,3` dequantises the u16 angle (GQR3 = 0x00050005,
    // unsigned 16-bit samples) before the `1/256` scale.
    let radians = angle as u16 as f32 * platform::read_f32(0x807C_EAC8);
    // inferred: 0x80237BD0 / 0x80237C40 are the paired sine/cosine helpers.
    let first = f32_of_f32(0x8023_7BD0, radians);
    let second = f32_of_f32(0x8023_7C40, radians);
    let scale = platform::read_f32(0x807C_EAC0); // 8.0
    platform::write_f32(this + 0xE8, scale * first);
    platform::write_f32(this + 0xEC, scale * second);
    platform::write_f32(this + 0xF0, zero);
    platform::write_u8(this + 0x263, 0);
    platform::write_u8(this + 0x262, 1);
    // observed: `rlwinm r0,r0,2,26,29` = `(word & 0xF) * 4`, then `lfsx`.
    let index = (platform::read_u32(this + 4) & 0xF) as usize;
    platform::write_f32(this + 0x24C, platform::read_f32(0x807C_EAB0 + index * 4));
    vmethod1(this + 0x12C, 0x18, 0x8083_2380);
}

/// Refreshes the date-file screen's two pad-status flags and the matching panes.
///
/// Reads the current file index `+0xE44`, asks the save-file manager
/// (`[0x8042A040]`) for the two per-file records through `0x800E0380` and
/// `0x800E03B0`, and publishes bit 0 of each record's `+2` status byte into
/// `+0xE4A`/`+0xE4B`. The `+0xE4B` branch stops the closed pane, starts
/// animation `5`, pushes the `+0xE40` float into the channel at
/// `[+0x1F8] + 0xC8`, starts animation `6` and reveals `+0xDEC`.
///
/// # Original
/// - Ghidra: `FUN_80610510` at `0x8061_0510` (460 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/80610510_FUN_80610510.c`
///
/// # Arguments
/// * `screen` - `dDateFile_c` screen; layout `+0x74`, channel owner `+0x1F8`,
///   panes `+0xDEC`/`+0xDE4`/`+0xDE8`, text panes `+0xE10`/`+0xE14`, file index
///   `+0xE44`, flags `+0xE4A`/`+0xE4B`/`+0xE4F`, scale `+0xE40`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the two flags and `+0xE4F`, optionally starts layout animations `5`
/// and `6`, sets channel `+0xC8`, toggles bit 0 of five panes' `+0xBB` byte,
/// writes two text rows through `0x800C9A60`, and renders the pressed button
/// through [`fn_80610320`].
///
/// # Safety
/// `screen`, the manager global `0x8042A040`, its two records and every pane
/// pointer must be live.
///
/// # Confidence
/// high - every offset, mask, animation id, text id and call is literal;
/// `observed:` the `0x802DCD6C` prologue is the compiler register-save thunk
/// (Ghidra prints `void`, the incoming `r3` is `screen`), and the record `+2`
/// bit roles are `// inferred:` from [`fn_80610320`], which takes the same
/// record as its pad argument.
pub unsafe fn fn_80610510(screen: usize) {
    let manager = platform::read_u32(0x8042_A040);
    // observed: `lwz` + `extsb` sign-extends the low byte of the index word.
    let index = platform::read_i32(screen + 0xE44) as i8 as u32;
    let record_a = abi_call2!(0x800E_0380, manager, index) as usize;
    let record_b = abi_call2!(0x800E_03B0, manager, index) as usize;
    let token = call0_ret(0x800C_DC60);

    platform::write_u8(screen + 0xE4F, 0);
    let flag_a = platform::read_u8(record_a + 2) & 1 != 0;
    let flag_b = platform::read_u8(record_b + 2) & 1 == 0;
    platform::write_u8(screen + 0xE4A, flag_a as u8);
    platform::write_u8(screen + 0xE4B, flag_b as u8);

    if flag_b {
        abi_call2!(0x800C_9380, screen + 0x74, 5);
        let channel = platform::read_u32(screen + 0x1F8) as usize + 0xC8;
        // unknown: 0x801637D0 copies one float into the channel object.
        let set_float: extern "C" fn(f32, u32) = core::mem::transmute(0x8016_37D0usize);
        set_float(
            platform::read_f32(screen + 0xE40),
            platform::read_u32(channel),
        );
        abi_call1!(0x8016_44D0, channel);
        abi_call3!(0x800C_93D0, screen + 0x74, 6, 0);
        let pane = platform::read_u32(screen + 0xDEC) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE | 1);
    } else {
        let pane = platform::read_u32(screen + 0xDEC) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
    }

    if flag_a {
        let pane = platform::read_u32(screen + 0xDE4) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
        let pane = platform::read_u32(screen + 0xDE8) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE | 1);
        abi_call5!(
            0x800C_9A60,
            platform::read_u32(screen + 0xE10),
            token,
            0x32,
            0x11,
            0
        );
        abi_call5!(
            0x800C_9A60,
            platform::read_u32(screen + 0xE14),
            token,
            0x32,
            0x11,
            0
        );
    } else {
        let pane = platform::read_u32(screen + 0xDE4) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE | 1);
        let pane = platform::read_u32(screen + 0xDE8) as usize;
        platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE);
        if flag_b {
            fn_80610320(screen, record_b);
        } else {
            if platform::read_u8(record_a + 2) & 0x40 == 0 {
                platform::write_u8(screen + 0xE4F, 1);
            }
            fn_80610320(screen, record_a);
        }
    }
}

/// Writes the message text of the current window id into both message panes.
///
/// The id at `+0x25C` selects a text row from `0x807C6CA8`. Ids `5..=12` are
/// first formatted as the decimal `id - 4` into a 16-byte stack buffer and
/// stamped with the six-argument form of `0x800C9A60`; every other id uses the
/// five-argument form and the marker `0`, `0x130` (id `19`) or `0x131`
/// (id `20`). The layout clip is then reset, the root pane is shown, `+0x258`
/// is raised and sound `0x7E` plays.
///
/// # Original
/// - Ghidra: `FUN_8061dc70` at `0x8061_DC70` (460 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8061dc70_FUN_8061dc70.c`
///
/// # Arguments
/// * `screen` - window screen; layout `+0xAC`, root pane `+0x244`, message
///   panes `+0x248`/`+0x24C`, dirty byte `+0x258`, window id `+0x25C`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Formats one string, writes both message panes, calls `0x800C92F0` on the
/// layout, sets two panes/flag bytes, and plays sound `0x7E` unless id `4` is
/// already flagged by `0x8042A21E`.
///
/// # Safety
/// `screen`, its layout and the two message panes must be live.
///
/// # Confidence
/// high - both id windows, the table base, the three markers, the buffer
/// capacity, the two call shapes and the sound id are literal. `observed:` the
/// table at `0x807C6CA8` holds `{0x46..0x4F, 0x38, 0}` for ids `1..20`; ids
/// above `20` leave the marker uninitialised in the original (Ghidra prints
/// `unaff_r28`), so they are modelled as `0`.
pub unsafe fn fn_8061dc70(screen: usize) {
    let token = call0_ret(0x800C_DC60);
    let mode = platform::read_i32(screen + 0x25C);
    let row = platform::read_u32(
        0x807C_6CA8u32.wrapping_add(mode.wrapping_sub(1).wrapping_mul(4) as u32) as usize,
    );

    if (5..=12).contains(&mode) {
        let mut buffer = [0u8; 16];
        abi_call5!(
            0x800C_DDB0,
            (mode - 4) as u32,
            buffer.as_mut_ptr() as u32,
            0x10,
            1,
            0
        );
        abi_call6!(
            0x800C_9A60,
            platform::read_u32(screen + 0x248),
            token,
            0,
            row,
            1,
            buffer.as_ptr() as u32
        );
        abi_call6!(
            0x800C_9A60,
            platform::read_u32(screen + 0x24C),
            token,
            0,
            row,
            1,
            buffer.as_ptr() as u32
        );
    } else {
        let marker = if mode == 19 {
            0x130u32
        } else if mode == 20 {
            0x131
        } else {
            0
        };
        abi_call5!(
            0x800C_9A60,
            platform::read_u32(screen + 0x248),
            token,
            marker,
            row,
            0
        );
        abi_call5!(
            0x800C_9A60,
            platform::read_u32(screen + 0x24C),
            token,
            marker,
            row,
            0
        );
    }

    abi_call3!(0x800C_92F0, screen + 0xAC, 0, 0);
    let pane = platform::read_u32(screen + 0x244) as usize;
    platform::write_u8(pane + 0xBB, platform::read_u8(pane + 0xBB) & 0xFE | 1);
    platform::write_u8(screen + 0x258, 1);
    if mode == 4 {
        if platform::read_u8(0x8042_A21E) == 0 {
            abi_call3!(0x8019_5380, platform::read_u32(0x8042_A488), 0x7E, 1);
        }
    } else {
        abi_call3!(0x8019_5380, platform::read_u32(0x8042_A488), 0x7E, 1);
    }
}

/// Rebuilds the emitter transform and uploads its two scale-driven values.
///
/// Samples the placement position with `0x8006CED0`, rotates it by the angles
/// `+0x100..+0x104` with `0x80064AF0`, builds the matrix at `+0x7C`, attaches
/// it to the model at `+0x544` with the unit scale, then patches channel `2` of
/// the model from `+0x1610 * 127` and channel `3` from `[0x8082F770] * 255`.
///
/// # Original
/// - Ghidra: `FUN_8070fe40` at `0x8070_FE40` (460 bytes)
/// - Synthetic base: `0x80600000`; this is not a runtime address.
/// - Evidence: `work/ghidra/rel-d_basesNP/export/8070fe40_FUN_8070fe40.c`
///
/// # Arguments
/// * `this` - witchcraft emitter owner; matrix `+0x7C`, angles
///   `+0x100..+0x104`, model `+0x544`, channel byte `+0x160C`, intensity
///   `+0x1610`, position source `+0xAC`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the matrix, the three Euler angles and the model transform, and
/// rewrites the low byte of the channel-`2`/`3` records of `+0x544`.
///
/// # Safety
/// `this` and the model object must be live; the `+0x160C` byte must be a
/// valid animation channel index.
///
/// # Confidence
/// high - every call, offset and constant is literal; the export's
/// `ldexpf`/`unaff_GQR0` text is the compiler's GQR0 float-save bracket. The
/// value sources are read out of the REL: `0x807CCA78 = 1.0`,
/// `0x80806628 = 127`, `0x80806629 = 255`, and `0x807CCA98 = 2^52` is the
/// unsigned `u8 -> f32` magic. `0x8082F770` is this image's BSS, so its `f32`
/// is read at runtime.
pub unsafe fn fn_8070fe40(this: usize) {
    let mut position = [0.0f32; 3];
    abi_call2!(0x8006_CED0, position.as_mut_ptr() as u32, this);
    // observed: `lha`/`sth` copies the three halfwords verbatim.
    let mut angles = [
        platform::read_u16(this + 0x100),
        platform::read_u16(this + 0x102),
        platform::read_u16(this + 0x104),
    ];
    // unknown: 0x80064AF0 adjusts the position/rotation pair for one sample.
    abi_call3!(
        0x8006_4AF0,
        position.as_mut_ptr() as u32,
        angles.as_mut_ptr() as u32,
        1
    );
    call_f32x3_u32(
        0x801C_0BD0,
        position[0],
        position[1],
        position[2],
        (this + 0x7C) as u32,
    );

    // observed: each setter receives a pointer to one halfword copy, Y first.
    let mut angle_y = [angles[1]];
    abi_call2!(0x8016_EDD0, this + 0x7C, angle_y.as_mut_ptr() as u32);
    let mut angle_x = [angles[0]];
    abi_call2!(0x8016_ECB0, this + 0x7C, angle_x.as_mut_ptr() as u32);
    let mut angle_z = [angles[2]];
    abi_call2!(0x8016_EEF0, this + 0x7C, angle_z.as_mut_ptr() as u32);

    abi_call2!(0x8016_A170, this + 0x544, this + 0x7C);
    let ones = [platform::read_f32(0x807C_CA78); 3];
    abi_call2!(0x8016_A150, this + 0x544, ones.as_ptr() as u32);

    let index = platform::read_u8(this + 0x160C) as u32;

    // observed: `0x8000D5B0(&word, model, index, 2)` fills the word, the
    // `fctiwz` result replaces its last byte, and the patched copy is passed on.
    let mut record = 0u32;
    abi_call4!(
        0x8000_D5B0,
        &mut record as *mut u32 as u32,
        this + 0x544,
        index,
        2
    );
    let scaled = (platform::read_f32(this + 0x1610)
        * platform::read_u8(0x8080_6628) as f32) as i32;
    let patched = (record & 0xFFFF_FF00) | scaled as u8 as u32;
    abi_call5!(
        0x8016_8880,
        this + 0x544,
        index,
        2,
        &patched as *const u32 as u32,
        0
    );

    let mut record = 0u32;
    abi_call4!(
        0x8000_D5B0,
        &mut record as *mut u32 as u32,
        this + 0x544,
        index,
        3
    );
    let scaled = (platform::read_f32(0x8082_F770)
        * platform::read_u8(0x8080_6629) as f32) as i32;
    let patched = (record & 0xFFFF_FF00) | scaled as u8 as u32;
    abi_call5!(
        0x8016_8880,
        this + 0x544,
        index,
        3,
        &patched as *const u32 as u32,
        0
    );
}

