    abi_call3!(0x8016_8180, this + 0x3F0, 1, buffer.as_mut_ptr() as u32);
    abi_call2!(
        0x8016_F130,
        buffer.as_mut_ptr() as u32,
        position.as_mut_ptr() as u32
    );
    let edge_x = position[0];
    let edge_y = position[1] + platform::read_f32(0x807C_C0B0);
    platform::write_f32(this + 0x700, edge_x - platform::read_f32(this + 0xAC));
    platform::write_f32(this + 0x704, edge_y - platform::read_f32(this + 0xB0));

    // observed: pane 1 is the reference X for the four pane-2..5 spreads.
    abi_call3!(0x8016_8180, this + 0x3F0, 1, buffer.as_mut_ptr() as u32);
    abi_call2!(
        0x8016_F130,
        buffer.as_mut_ptr() as u32,
        position.as_mut_ptr() as u32
    );
