    // unknown: 0x800B3B50 queries a controller record; -1 scans every pad.
    if abi_call1!(0x800B_3B50, 0xFFFF_FFFF) != 0 {
        return 0;
    }
    // unknown: 0x80600510 is the screen-side probe whose zero result is the
    // answer this routine reports.
    let value = call0_ret(0x8060_0510);
    // observed: countLeadingZeros(value) >> 5 is 1 only when value == 0.
    if value == 0 {
        1
    } else {
        0
    }
