/// # Safety
/// `this` and every resolved player must be live.
///
/// # Confidence
/// high - the mode split, the four-slot scan and both kill calls are literal.
pub unsafe fn fn_8067ecc0(this: usize) {
    let variant = platform::read_u8(this + 0x349);
    if platform::read_u32(0x8042_9CA0) == 1 {
        let player = fn_8067dc50();
        if variant != platform::read_u8(player + 0x349) {
            abi_call2!(0x8006_4D10, this, 0);
        }
    } else {
        let mut found = false;
        for index in 0..4u32 {
            let player = abi_call1!(0x8005_F900, index) as usize;
            if player != 0 && variant == platform::read_u8(player + 0x349) {
                found = true;
            }
        }
        if !found {
            abi_call2!(0x8006_4D10, this, 0);
        }
    }
}

/// Resets the eight shape floats and re-registers four `0x18`-byte records.
///
/// # Original
