/// `0x801611C0` (16-bit angle) and `0x807073D0` twice.
///
/// # Safety
/// Both objects must be live; `0x807073D0` indexes the byte table at
/// `0x8042C1A0` with `target + 0x3E1`.
///
/// # Confidence
/// high - every store, both angle helpers and the `sqrt` input are literal; the
/// helper identities match their already translated uses in [`fn_806eae50`]
/// and [`fn_807073d0`].
pub unsafe fn fn_8072fba0(this: usize, target: usize) {
    platform::write_u32(this + 0x4E8, platform::read_u32(target));

    let dx = platform::read_f32(this + 0xAC) - platform::read_f32(target + 0xAC);
    let dy = platform::read_f32(this + 0xB0) - platform::read_f32(target + 0xB0);
    let distance = call_f32_f32(0x802B_E470, dx * dx + dy * dy);
    platform::write_f32(this + 0x4EC, distance);

    let target_yaw = fn_807073d0(target);
    let this_yaw = platform::read_u16(this + 0x104) as i16 as i32;
    platform::write_u16(this + 0x4F0, this_yaw.wrapping_sub(target_yaw) as u16);

    let aim = call_f32x2(0x8016_11C0, dy, dx);
    let target_aim = fn_807073d0(target);
    platform::write_u16(this + 0x4F2, aim.wrapping_sub(target_aim as u32) as u16);

    platform::write_u32(this + 0x4F8, platform::read_u8(target + 0x3E1) as u32);
    platform::write_u16(this + 0x4F4, platform::read_u16(target + 0x104));
}

