/// Four `stfs` stores; no reads through `this`.
///
/// # Safety
/// `this + 0x318..+0x327` must be writable.
///
/// # Confidence
/// high - every `lfs`/`stfs` offset and each of the four table variants are
/// read from the raw words: `0x807CCF98` = `16, -136, 992, 752`,
/// `+0x10` = `256`, `+0x14` = `136`, `+0x18` = `-256`, `+0x1C` = `-16`.
pub unsafe fn fn_8071bc50(this: usize, variant: i32) {
    let table = 0x807C_CF98;
    let (w320, w324, w318, w31c) = match variant {
        0 => (
            platform::read_f32(table),
            platform::read_f32(table + 4),
            platform::read_f32(table + 8),
            platform::read_f32(table + 0xC),
        ),
        1 => (
            platform::read_f32(table + 0x10),
            platform::read_f32(table + 4),
            platform::read_f32(table + 8),
            platform::read_f32(table + 0xC),
        ),
        2 => (
            platform::read_f32(table + 0x14),
            platform::read_f32(table + 0x18),
            platform::read_f32(table + 0xC),
            platform::read_f32(table + 8),
        ),
        _ => (
            platform::read_f32(table + 0x14),
            platform::read_f32(table + 0x1C),
            platform::read_f32(table + 0xC),
            platform::read_f32(table + 8),
        ),
    };

    platform::write_f32(this + 0x320, w320);
    platform::write_f32(this + 0x324, w324);
    platform::write_f32(this + 0x318, w318);
    platform::write_f32(this + 0x31C, w31c);
}

