    let dy = platform::read_f32(this + 0x5FC);
    let dz = platform::read_f32(this + 0x600);

    platform::write_f32(this + 0x4B0, platform::read_f32(this + 0x4B0) + dx);
    platform::write_f32(this + 0x4B4, platform::read_f32(this + 0x4B4) + dy);
    platform::write_f32(this + 0x4B8, platform::read_f32(this + 0x4B8) + dz);
    platform::write_f32(this + 0x4BC, platform::read_f32(this + 0x4BC) + dx);
    platform::write_f32(this + 0x4C0, platform::read_f32(this + 0x4C0) + dy);
    platform::write_f32(this + 0x4C4, platform::read_f32(this + 0x4C4) + dz);

