    let scene = platform::read_u32(0x8042_A18C) as usize;
    let record = scene + platform::read_i32(scene + 0x338C) as usize * 0x16518;
    let count = platform::read_i32(record + 0x33A0);

    let mut index = 0i32;
    while index < count {
        if fn_807c09b0(this as u32, index as u32) != 0 {
            return 1;
        }
        index += 1;
    }
