    let phase_x = (platform::read_u16(this + 0x500) as i16).wrapping_add(0x200);
    platform::write_u16(this + 0x500, phase_x as u16);
    let sine = f32_of_f32(0x8023_7BD0, (phase_x as u16) as f32 * scale);
    platform::write_u16(
        this + 0x100,
        (sine * platform::read_f32(0x807C_9DD0)) as i32 as u16,
    );

    let phase_y = (platform::read_u16(this + 0x502) as i16).wrapping_add(0x400);
    platform::write_u16(this + 0x502, phase_y as u16);
    let sine = f32_of_f32(0x8023_7BD0, (phase_y as u16) as f32 * scale);
    platform::write_u16(
        this + 0x102,
        (sine * platform::read_f32(0x807C_9DD4)) as i32 as u16,
    );

    let phase_z = (platform::read_u16(this + 0x504) as i16).wrapping_add(0x200);
    platform::write_u16(this + 0x504, phase_z as u16);
    let sine = f32_of_f32(0x8023_7BD0, (phase_z as u16) as f32 * scale);
    platform::write_u16(
        this + 0x104,
        (sine * platform::read_f32(0x807C_9DD8)) as i32 as u16,
    );
