    let scale = actor_method0_f32(this, 0x35C);
    platform::write_f32(this + 0xE8, platform::read_f32(target) / scale);

    let scale = actor_method0_f32(this, 0x35C);
    platform::write_f32(this + 0xEC, platform::read_f32(target + 4) / scale);

    let owner = actor_method0(this, 0x2DC) as usize;
    let mut active = true;
