    if variant > 2 {
        variant = 2;
    }

    fn_806c0e10(this, variant);

    let one = platform::read_f32(0x807C_AF84); // 1.0
    platform::write_f32(this + 0xDC, one);
    platform::write_f32(this + 0xE0, one);
    platform::write_f32(this + 0xE4, one);

    abi_call1!(0x806C_0F00, this);
    fn_806c1020(this, platform::read_u16(this + 0x104));

    // observed: 0x807CAF80 holds [8, 12, 16, 0]; only the clamped variants
    // 0..2 are reachable.
    let panes = [8u8, 12, 16, 0];
    let pane = panes[variant as usize];

    platform::write_f32(this + 0x318, platform::read_f32(0x807C_AF74)); // 512.0
    platform::write_f32(this + 0x31C, platform::read_f32(0x807C_AF8C)); // 256.0
    platform::write_f32(this + 0x320, platform::read_f32(0x807C_AF68)); // 0.0
    platform::write_f32(this + 0x324, platform::read_f32(0x807C_AF88)); // -128.0
    platform::write_u8(this + 0x526, pane);

    // observed: r3..r10 hold the eight integer arguments and the ninth, a
    // constant zero, is the single stack argument at 0x8(r1).
    call_u32x9(
        0x800D_2610,
        (this + 0x3FC) as u32,
        this as u32,
        pane as u32,
        (this + 0x43C) as u32,
        0x807C_AEC8, // "A"
        (this + 0x4C4) as u32,
        2,
        1,
        0,
    );

    abi_call2!(0x8016_A000, this + 0x3BC, this + 0x394);
