    let threshold = platform::read_f32(0x807C_B450); // 0.0
    let active = platform::read_u8(0x8042_9CA8);

    let mut lowest = threshold;
    let initial = lowest;

    for index in 0..4u32 {
        if (active as u32 & (1u32 << index)) != 0 {
            let player = abi_call1!(0x8005_F900, index) as usize;
            if abi_call1!(0x8007_0CB0, player + 0x1EC) != 0 {
                let height = platform::read_f32(player + 0xB0);
                if fn_806d00e0(height, threshold) != 0 {
                    if lowest == initial {
                        lowest = height;
                    } else if height <= lowest {
                        lowest = height;
                    }
                }
            }
        }
    }
    lowest
