    let mut dx = platform::read_f32(this + 0xAC) - platform::read_f32(other + 0xAC);
    // observed: `fcmpu` against `0x807CA08C` (0.0) then `fneg`, i.e. fabs.
    if dx <= platform::read_f32(0x807C_A08C) {
        dx = -dx;
    }
    if dx > platform::read_f32(0x807F_1390) {
        return 0;
    }

    let mut vector = [
        platform::read_f32(other + 0xAC) - platform::read_f32(this + 0xAC),
        platform::read_f32(other + 0xB0) - platform::read_f32(this + 0xB0),
        platform::read_f32(0x807C_A08C),
    ];
