    abi_call1!(0x8017_0980, vector.as_mut_ptr() as u32);
    // observed: the height component is re-read after the normalisation.
    let dy = vector[1];

    let upper = call_f32_f32(0x802B_E4A0, fn_8069a300(this));
    let lower = call_f32_f32(0x802B_E4A0, -fn_8069a300(this));
    if dy <= lower || upper <= dy {
        0
    } else {
        1
    }
