    platform::write_f32(this + 0x720, platform::read_f32(0x807C_A524));
    platform::write_f32(this + 0x738, platform::read_f32(0x807C_A520));
    platform::write_f32(this + 0x70C, platform::read_f32(0x807C_A528));
