    let mut accepted = false;
    if model != 0 {
        let type_tag: u32 = 0x802F_8FF0;
        if vmethod1(model, 0x08, &type_tag as *const u32 as u32) != 0 {
            accepted = true;
        }
    }
    if !accepted {
        model = 0;
    }

    let mut adapter = [0u32; 17];
    abi_call3!(0x8025_C660, adapter.as_mut_ptr() as u32, model, 1);
    let mut pane = [abi_call2!(0x8025_C470, adapter.as_mut_ptr() as u32, 0)];
    let mut transform = [0u32; 12];
