    let facing = platform::read_u16(parent + 0x104) as i16 as i32
        + platform::read_u16(this + 0x4F0) as i16 as i32;
    platform::write_u16(this + 0x104, facing as u16);

    let raw_angle = platform::read_u16(this + 0x4F2) as i16 as i32
        + platform::read_u16(parent + 0x104) as i16 as i32;
