        platform::write_f32(this + 0x114, platform::read_f32(0x8031_D3A8));
        platform::write_f32(this + 0xEC, platform::read_f32(0x807D_0160));
        platform::write_f32(this + 0x118, platform::read_f32(0x8031_D3AC));
