    platform::write_u16(this + 0x102, 0x7FFF);
    platform::write_u16(this + 0x104, 0);
    platform::write_u16(this + 0x106, 0);
    platform::write_u16(this + 0x108, 0x7FFF);
    platform::write_u16(this + 0x10A, 0);

    platform::write_f32(this + 0x1FC, platform::read_f32(peer + 0xAC));
    platform::write_f32(this + 0x200, platform::read_f32(peer + 0xB0));
    platform::write_f32(this + 0x204, platform::read_f32(peer + 0xB4));
    platform::write_f32(this + 0x264, platform::read_f32(this + 0xAC));
    platform::write_f32(this + 0x268, platform::read_f32(this + 0xB0));
    platform::write_f32(this + 0x26C, platform::read_f32(this + 0xB4));
    platform::write_u32(this + 0x2E0, 0x12);

