    let board = platform::read_u32(0x8042_9F7C) as usize;
    let world = (platform::read_u32(scene + 0x3388) & 0xFF) as u32;
    platform::write_u32(board + 0x44, platform::read_u32(this + 0x22C));
    let selection = fn_8079fa10(this, world);

    let source = abi_call3!(
        0x800B_BBB0,
        board,
        platform::read_u8(0x8042_A24D) as u32,
        platform::read_u32(board + 0x9C)
    ) as usize;
