    let anchor = platform::read_u32(this + 0x29C) as usize;
    platform::write_f32(0x80C7_1158, platform::read_f32(anchor + 0x24));
    platform::write_f32(0x80C7_115C, platform::read_f32(anchor + 0x28));
    platform::write_f32(0x80C7_1160, platform::read_f32(anchor + 0x2C));
